// Export singleton instance
export const adminService = new AdminService();

import { useState, useEffect, lazy, Suspense } from 'react';

import { DEFAULT_SECURITY_CONFIG } from '@odysseus/shared-schemas';
import { X, Shield, Activity, AlertTriangle, Save, RefreshCw, Cog, Gauge, UsersRound } from 'lucide-react';

import { useFocusTrap } from '@shared/hooks/useFocusTrap';
import { ResearcherIcon } from '@shared/ui/components/icons';
import { notifications } from '@shared/utils';

import { adminService } from '../../services/AdminService';

import { TabSkeleton } from './TabSkeleton';

import type { SecurityConfig, AdminUser, SystemMetrics, SyncStatus } from '@odysseus/shared-schemas';

// Lazy-load tab components for code splitting
const SecurityTab = lazy(() =>
  import('./tabs/SecurityTab').then(m => ({ default: m.SecurityTab }))
);
const UserManagementTab = lazy(() =>
  import('./tabs/UserManagementTab').then(m => ({ default: m.UserManagementTab }))
);
const ResearcherManagementTab = lazy(() =>
  import('./tabs/ResearcherManagementTab').then(m => ({ default: m.ResearcherManagementTab }))
);
const SystemConfigTab = lazy(() =>
  import('./tabs/SystemConfigTab').then(m => ({ default: m.SystemConfigTab }))
);
const MonitoringTab = lazy(() =>
  import('./tabs/MonitoringTab').then(m => ({ default: m.MonitoringTab }))
);

interface AdminSettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function AdminSettingsModal({ isOpen, onClose }: AdminSettingsModalProps) {
  const [activeTab, setActiveTab] = useState<'security' | 'users' | 'researchers' | 'system' | 'monitoring'>('system');
  const [config, setConfig] = useState<SecurityConfig>(DEFAULT_SECURITY_CONFIG);
  const [originalConfig, setOriginalConfig] = useState<SecurityConfig>(DEFAULT_SECURITY_CONFIG);
  const [isSaving, setSaving] = useState(false);
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [systemStats, setSystemStats] = useState<SystemMetrics | null>(null);
  const [syncStatus, setSyncStatus] = useState<SyncStatus | null>(null);
  const [inviteCode, setInviteCode] = useState<string>('');

  // Focus trap (only active when modal is open)
  const trapRef = useFocusTrap({
    isOpen,
    restoreFocus: true,
    autoFocusFirstInput: false // Focus first focusable element (tab button)
  });

  // Load current configuration and data
  useEffect(() => {
    if (isOpen) {
      // SessionManager handles authentication automatically
      void loadConfiguration();
      void loadUsers();
      void loadSystemStats();
      void loadSyncStatus();
    }
  }, [isOpen]);

  const loadConfiguration = async () => {
    try {
      const response = await adminService.getSecurityConfig();

      if (response.success && response.config) {
        // Merge with defaults to ensure all fields are present
        const loadedConfig = { ...DEFAULT_SECURITY_CONFIG, ...response.config };
        setConfig(loadedConfig);
        setOriginalConfig(loadedConfig); // Store original for change tracking
      }
    } catch (error) {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('Failed to load configuration:', error);
      // Keep defaults on error
      setConfig(DEFAULT_SECURITY_CONFIG);
      setOriginalConfig(DEFAULT_SECURITY_CONFIG);
    }
  };

  const loadUsers = async () => {
    try {
      const response = await adminService.getUsers();

      if (response.success && Array.isArray(response.users)) {
        setUsers(response.users);
      } else {
        // API returned unsuccessfully or invalid data - set empty array as fallback
        setUsers([]);
        // eslint-disable-next-line no-console -- Warning logging for production monitoring
        console.warn('Failed to load users: API returned unsuccessful response or invalid data format');
      }
    } catch (error) {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('Failed to load users:', error);
      setUsers([]);
    }
  };

  const loadSystemStats = async () => {
    try {
      const response = await adminService.getMetrics();

      if (response.success && response.data) {
        setSystemStats({
          totalTubes: response.data.totalTubes || 0,
          totalUsers: response.data.totalUsers || 1,
          totalResearchers: response.data.totalResearchers || 0,
          lastBackup: new Date().toISOString(),
        });
      }
    } catch (error) {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('Failed to load system stats:', error);
      setSystemStats({
        totalTubes: 0,
        totalUsers: 1,
        totalResearchers: 0,
        lastBackup: new Date().toISOString(),
      });
    }
  };

  const saveConfiguration = async () => {
    // SessionManager handles authentication automatically

    // Calculate only the fields that actually changed
    const changes: Partial<SecurityConfig> = {};
    Object.keys(config).forEach(key => {
      const configKey = key as keyof SecurityConfig;
      if (config[configKey] !== originalConfig[configKey]) {
        (changes as any)[configKey] = config[configKey];
      }
    });

    setSaving(true);
    try {
      const response = await adminService.updateSecurityConfig(changes);

      if (response.success) {
        notifications.success('Security configuration updated successfully');
        // Update original config to reflect saved state
        setOriginalConfig(config);
        // Close modal after successful save
        onClose();
      } else {
        notifications.error('Failed to update security configuration');
      }
    } catch (error) {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('Failed to save configuration:', error);
      notifications.error('Failed to update security configuration');
    } finally {
      setSaving(false);
    }
  };

  const loadSyncStatus = async () => {
    try {
      const { httpClient } = await import('@infra/api/httpClient');
      const response = await httpClient.get<{ success: boolean; sync: SyncStatus }>('/admin/sync-status');

      if (response.data.success) {
        setSyncStatus(response.data.sync);
      }
    } catch (error) {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('Failed to load sync status:', error);
      setSyncStatus(null);
    }
  };

  const createInviteCode = async (role: 'admin' | 'user' = 'user') => {
    try {
      const { httpClient } = await import('@infra/api/httpClient');
      const response = await httpClient.post<{ success: boolean; inviteCode: string }>('/admin/create-invite', { role });

      if (response.data.success) {
        setInviteCode(response.data.inviteCode);
        notifications.success('Invite code created successfully!');
      } else {
        notifications.error('Failed to create invite code');
      }
    } catch (error) {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('Failed to create invite code:', error);
      notifications.error('Failed to create invite code');
    }
  };

  const handleConfigChange = (field: keyof SecurityConfig, value: boolean | number | string) => {
    setConfig(prev => ({ ...prev, [field]: value }));
  };

  if (!isOpen) return null;

  // Check if there are any unsaved changes
  const hasChanges = Object.keys(config).some(key => {
    const configKey = key as keyof SecurityConfig;
    return config[configKey] !== originalConfig[configKey];
  });

  const tabs = [
    { id: 'system', label: 'System', icon: Gauge },
    { id: 'security', label: 'Security', icon: Shield },
    { id: 'users', label: 'User Management', icon: UsersRound },
    { id: 'researchers', label: 'Researcher Management', icon: ResearcherIcon },
    { id: 'monitoring', label: 'Monitoring', icon: Activity },
  ] as const;

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-[2px] flex items-center justify-center z-50 animate-in fade-in duration-[180ms]">
      <div ref={trapRef} className="bg-white rounded-2xl shadow-2xl border border-gray-200 w-full max-w-5xl h-[85vh] mx-4 overflow-hidden animate-slide-up-fade flex flex-col">
        {/* Header */}
        <div className="bg-gradient-to-r from-danger-hover via-danger-bg to-danger-hover px-6 py-3 text-white flex-shrink-0">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <Cog className="w-6 h-6" />
              <div>
                <h2 className="text-lg font-bold">Admin Settings</h2>
                <p className="text-white/80 text-xs">Security & System Configuration</p>
              </div>
            </div>
            <button
              onClick={onClose}
              className="btn-header-menu text-white/80 hover:text-white hover:bg-danger-hover/50"
            >
              <X size={20} />
            </button>
          </div>
        </div>

        <div className="flex flex-1 min-h-0">
          {/* Sidebar */}
          <div className="w-48 bg-gray-50 border-r border-gray-200 p-4">
            <nav className="space-y-2">
              {tabs.map(tab => {
                const Icon = tab.icon;
                return (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id)}
                    className={`nav-tab ${
                      activeTab === tab.id
                        ? 'bg-danger-light text-danger-hover border border-danger-border'
                        : 'text-gray-600 hover:bg-gray-100 hover:text-gray-900'
                    }`}
                  >
                    <Icon size={tab.id === 'researchers' ? 24 : 20} />
                    <span className="font-medium text-sm">{tab.label}</span>
                  </button>
                );
              })}
            </nav>
          </div>

          {/* Content with Lazy-Loaded Tabs */}
          <div className="flex-1 overflow-y-auto min-w-0">
            <div className="p-6 min-w-0">
              {activeTab === 'security' && (
                <Suspense fallback={<TabSkeleton />}>
                  <SecurityTab
                    config={config}
                    onChange={handleConfigChange}
                  />
                </Suspense>
              )}

              {activeTab === 'users' && (
                <Suspense fallback={<TabSkeleton />}>
                  <UserManagementTab
                    users={users}
                    onUserUpdate={loadUsers}
                    inviteCode={inviteCode}
                    onCreateInvite={createInviteCode}
                  />
                </Suspense>
              )}

              {activeTab === 'researchers' && (
                <Suspense fallback={<TabSkeleton />}>
                  <ResearcherManagementTab
                    onResearcherUpdate={loadSystemStats}
                  />
                </Suspense>
              )}

              {activeTab === 'system' && (
                <Suspense fallback={<TabSkeleton />}>
                  <SystemConfigTab
                    config={config}
                    stats={systemStats}
                    syncStatus={syncStatus}
                    onChange={handleConfigChange}
                    onRefreshSync={loadSyncStatus}
                  />
                </Suspense>
              )}

              {activeTab === 'monitoring' && (
                <Suspense fallback={<TabSkeleton />}>
                  <MonitoringTab />
                </Suspense>
              )}
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="border-t border-gray-200 px-6 py-3 bg-gray-50 flex-shrink-0">
          <div className="flex items-center justify-between gap-4">
            <div className="flex items-center space-x-2 text-xs text-gray-600 flex-shrink min-w-0">
              <AlertTriangle size={14} className="alert-warning-icon flex-shrink-0" />
              <span className="truncate">Changes apply to all users immediately</span>
            </div>
            <div className="flex space-x-2 flex-shrink-0">
              <button
                onClick={onClose}
                className="btn-cancel"
              >
                Cancel
              </button>
              <button
                onClick={saveConfiguration}
                disabled={isSaving || !hasChanges}
                className="btn btn-primary flex items-center space-x-2 text-sm px-3 py-1.5 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isSaving ? <RefreshCw size={14} className="animate-spin" /> : <Save size={14} />}
                <span>{isSaving ? 'Saving...' : 'Save Changes'}</span>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * Audit Log Formatters
 *
 * Utility functions for formatting audit log entry details for display.
 * Extracts formatting logic from AuditLogViewer component.
 */

import type { AuditLogEntry } from '@odysseus/shared-schemas';

/**
 * Format audit log entry details for display
 *
 * Parses the JSON details field and formats it based on entity type and action.
 * Returns a human-readable string describing what happened.
 *
 * @param entry - The audit log entry to format
 * @returns Formatted details string
 */
export function formatAuditDetails(entry: AuditLogEntry): string {
  try {
    const details = JSON.parse(entry.details);
    const action = entry.action;
    const entityType = entry.entityType;

    // TUBES: Show location or bulk update count
    if (entityType === 'tube') {
      if (action === 'tube_bulk_updated' && details.count) {
        return `${details.count} tube${details.count !== 1 ? 's' : ''} updated`;
      }
      if (details.displayLocation) return details.displayLocation;
      if (details.location) return details.location;
      return '-';
    }

    // TANK EVENTS
    if (entityType === 'tank') {
      if (action === 'tank_created') {
        const tankName = details.tankName || details.tankId || '';
        return `Tank '${tankName}'`;
      }
      if (action === 'tank_deleted') {
        const tankName = details.tankName || details.tankId || '';
        return `Tank '${tankName}'`;
      }
      if (action === 'tank_updated' && details.changes) {
        const nameChange = details.changes.find((c: any) => c.field === 'name');
        if (nameChange) {
          return `Tank '${nameChange.oldValue}' renamed to '${nameChange.newValue}'`;
        }
        const activeChange = details.changes.find((c: any) => c.field === 'isActive');
        if (activeChange) {
          const tankName = nameChange?.newValue || details.tankId || '';
          return `Tank '${tankName}' ${activeChange.newValue ? 'activated' : 'deactivated'}`;
        }
      }
      const tankName = details.tankId || '';
      return `Tank '${tankName}'`;
    }

    // RACK EVENTS
    if (entityType === 'rack') {
      const tankName = details.tankName || details.tankId || '';
      const rackName = details.rackName || `Rack ${details.rackId}` || '';
      const path = `${tankName}/${rackName}`;

      if (action === 'rack_created') {
        return path;
      }
      if (action === 'rack_deleted') {
        return path;
      }
      if (action === 'rack_updated' && details.changes) {
        const nameChange = details.changes.find((c: any) => c.field === 'name');
        if (nameChange) {
          const oldPath = `${tankName}/${nameChange.oldValue}`;
          return `${oldPath} renamed to '${nameChange.newValue}'`;
        }
        const activeChange = details.changes.find((c: any) => c.field === 'isActive');
        if (activeChange) {
          return `${path} ${activeChange.newValue ? 'activated' : 'deactivated'}`;
        }
      }
      return path;
    }

    // BOX EVENTS
    if (entityType === 'box') {
      const tankName = details.tankName || details.tankId || '';
      const rackName = details.rackName || `Rack ${details.rackId}` || '';
      const boxName = details.boxName || `Box ${details.boxId}` || '';
      const path = `${tankName}/${rackName}/${boxName}`;

      if (action === 'box_created') {
        return path;
      }
      if (action === 'box_deleted') {
        return path;
      }
      if (action === 'box_updated' && details.changes) {
        const nameChange = details.changes.find((c: any) => c.field === 'name');
        if (nameChange) {
          const oldPath = `${tankName}/${rackName}/Box ${nameChange.oldValue}`;
          return `${oldPath} renamed to 'Box ${nameChange.newValue}'`;
        }
        const rowChange = details.changes.find((c: any) => c.field === 'gridConfig.rows');
        const colChange = details.changes.find((c: any) => c.field === 'gridConfig.cols');
        if (rowChange && colChange) {
          return `${path} resized to ${rowChange.newValue}x${colChange.newValue}`;
        }
        const activeChange = details.changes.find((c: any) => c.field === 'isActive');
        if (activeChange) {
          return `${path} ${activeChange.newValue ? 'activated' : 'deactivated'}`;
        }
      }
      return path;
    }

    // LAB EVENTS
    if (entityType === 'lab') {
      if (action === 'lab_name_changed' && details.oldName && details.newName) {
        return `'${details.oldName}' renamed to '${details.newName}'`;
      }
      return details.newName || '-';
    }

    // RESEARCHER EVENTS
    if (entityType === 'researcher') {
      const researcherName = details.researcherName || '-';
      const createdBy = details.createdBy || '';
      const updatedBy = details.updatedBy || '';
      const deactivatedBy = details.deactivatedBy || '';
      const reactivatedBy = details.reactivatedBy || '';

      if (action === 'researcher_created') {
        const emailPart = details.email ? ` (${details.email})` : '';
        return `${researcherName}${emailPart} by ${createdBy}`;
      }
      if (action === 'researcher_updated' && details.changes) {
        const emailChange = details.changes.find((c: any) => c.field === 'email');
        if (emailChange) {
          return `${researcherName}: Email changed to ${emailChange.newValue} by ${updatedBy}`;
        }
        const positionChange = details.changes.find((c: any) => c.field === 'position');
        if (positionChange) {
          return `${researcherName}: Position changed to '${positionChange.newValue}' by ${updatedBy}`;
        }
        const firstNameChange = details.changes.find((c: any) => c.field === 'firstName');
        const lastNameChange = details.changes.find((c: any) => c.field === 'lastName');
        if (firstNameChange || lastNameChange) {
          return `${researcherName}: Name updated by ${updatedBy}`;
        }
        return `${researcherName} updated by ${updatedBy}`;
      }
      if (action === 'researcher_deactivated') {
        const tubeCount = details.tubesReassignedCount || 0;
        const tubeText = tubeCount > 0 ? ` (${tubeCount} tubes reassigned to Unknown)` : '';
        return `${researcherName}${tubeText} by ${deactivatedBy}`;
      }
      if (action === 'researcher_reactivated') {
        return `${researcherName} by ${reactivatedBy}`;
      }
      return researcherName;
    }

    // USER EVENTS
    if (entityType === 'user') {
      const username = details.username || '-';
      const changedBy = details.changedBy || '';
      const linkedBy = details.linkedBy || '';
      const unlinkedBy = details.unlinkedBy || '';
      const deletedBy = details.deletedBy || '';

      if (action === 'user_created') {
        const role = details.role || 'user';
        const isFirstUser = details.username && username === details.username && !changedBy;
        return isFirstUser ? `${username} (Role: ${role}) - First user setup` : `${username} (Role: ${role})`;
      }
      if (action === 'user_logged_in') {
        return username;
      }
      if (action === 'user_logged_out') {
        return username;
      }
      if (action === 'user_role_changed') {
        const newRole = details.newRole || '';
        return `Role changed to ${newRole}`;
      }
      if (action === 'user_password_changed') {
        return 'Password changed';
      }
      if (action === 'user_linked_to_researcher') {
        const researcherName = details.researcherName || '';
        return `${username} linked to researcher ${researcherName} by ${linkedBy}`;
      }
      if (action === 'user_unlinked_from_researcher') {
        const researcherName = details.researcherName || '';
        return `${username} unlinked from researcher ${researcherName} by ${unlinkedBy}`;
      }
      if (action === 'user_deleted') {
        return `${username} by ${deletedBy}`;
      }
      return username;
    }

    return '-';
  } catch {
    return '-';
  }
}

/**
 * Authentication Application Service
 *
 * Clean separation of concerns - removes business logic from UI components.
 * Coordinates between domain, infrastructure, and UI layers.
 */
import {
  type RegisterWithResearcherRequest,
  type VerificationStatusResponse
} from '@odysseus/shared-schemas';

import { queryClient } from '@app/queryClient';
import { httpClient } from '@infra/api/httpClient';

// Domain types (keep existing types intact)
export interface User {
  id: string;
  username: string;
  role: 'admin' | 'user';
  createdAt: string;
  lastActivity: string;
  status?: 'pending' | 'approved' | 'rejected';
}

export interface AuthResponse {
  user: User;
  tokens: any; // TokenPair from session types
}

export interface RegisterWithResearcherResponse {
  user: User;
  tokens?: any; // Optional - only for approved users
  status: 'approved' | 'pending';
  message: string;
}

export interface RegisterRequest {
  username: string;
  password: string;
  role?: 'admin' | 'user';
}

export interface LoginRequest {
  username: string;
  password: string;
}

export interface PasswordRequirements {
  passwordMinLength: number;
  requireStrongPasswords: boolean;
  passwordRequireSpecialChars: boolean;
}

/**
 * Authentication service with clean business logic
 */
export class AuthService {
  /**
   * Register new user (first-time setup - legacy method)
   */
  async register(request: RegisterRequest): Promise<AuthResponse> {
    try {
      const response = await httpClient.post<{ success: boolean; data: any }>('/public/auth/register', request);

      if (response.data.success && response.data.data) {
        const responseData = response.data.data;

        // Return enhanced response with token pair
        return {
          user: responseData.user,
          tokens: responseData.tokens
        };
      }

      throw new Error('Registration failed');
    } catch (error) {
      if (error && typeof error === 'object' && 'message' in error) {
        throw new Error((error as Error).message);
      }
      throw new Error('Registration failed');
    }
  }

  /**
   * Register user with researcher profile and approval workflow
   *
   * First user: Auto-approved as admin (returns tokens)
   * Subsequent users: Pending approval (no tokens)
   */
  async registerWithResearcher(request: RegisterWithResearcherRequest): Promise<RegisterWithResearcherResponse> {
    try {
      const response = await httpClient.post<{ success: boolean; data: any }>('/public/auth/register-with-researcher', request);

      if (response.data.success && response.data.data) {
        const responseData = response.data.data;

        // Return response with optional tokens (based on approval status)
        return {
          user: responseData.user,
          tokens: responseData.tokens, // undefined for pending users
          status: responseData.status,
          message: responseData.message
        };
      }

      throw new Error('Registration failed');
    } catch (error) {
      if (error && typeof error === 'object' && 'message' in error) {
        throw new Error((error as Error).message);
      }
      throw new Error('Registration failed');
    }
  }

  /**
   * Login with username and password
   */
  async login(request: LoginRequest): Promise<AuthResponse> {
    try {
      // HttpClient automatically transforms dates using existing responseTransformers
      const response = await httpClient.post<{ success: boolean; data: any }>('/public/auth/login', request);
      
      if (response.data.success && response.data.data) {
        const responseData = response.data.data;
        
        // Return transformed response (dates automatically converted by HttpClient)
        return {
          user: responseData.user,
          tokens: responseData.tokens
        };
      }
      
      throw new Error('Login failed');
    } catch (error) {
      if (error && typeof error === 'object' && 'message' in error) {
        throw new Error((error as Error).message);
      }
      throw new Error('Login failed');
    }
  }

  /**
   * Verify current session
   */
  async verifySession(): Promise<AuthResponse> {
    const response = await httpClient.get<{ success: boolean; data: { user: User } }>('/auth/verify');

    if (response.data.success && response.data.data) {
      return {
        user: response.data.data.user,
        tokens: null // No tokens needed for verify - just user info
      };
    }

    // SessionManager will handle token cleanup on error
    throw new Error('Session verification failed');
  }

  /**
   * Check if this is first-time setup
   */
  async checkFirstTime(): Promise<boolean> {
    try {
      const response = await httpClient.get<{ success: boolean; data: { isFirstTime: boolean } }>('/public/auth/first-time');

      if (response.data.success && response.data.data) {
        return response.data.data.isFirstTime;
      }

      return false;
    } catch (error) {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('Failed to check first-time setup:', error);
      return false;
    }
  }

  /**
   * Get password requirements (for registration form validation)
   */
  async getPasswordRequirements(): Promise<PasswordRequirements> {
    try {
      const response = await httpClient.get<{ success: boolean; data: PasswordRequirements }>('/public/auth/password-requirements');

      if (response.data.success && response.data.data) {
        return response.data.data;
      }

      // Default fallback requirements
      return {
        passwordMinLength: 8,
        requireStrongPasswords: false,
        passwordRequireSpecialChars: false
      };
    } catch (error) {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('Failed to get password requirements:', error);
      // Return safe defaults on error
      return {
        passwordMinLength: 8,
        requireStrongPasswords: false,
        passwordRequireSpecialChars: false
      };
    }
  }

  /**
   * Verify email with token from verification link
   * Public endpoint - no authentication required
   */
  async verifyEmail(token: string): Promise<void> {
    try {
      const response = await httpClient.post<{ success: boolean; message: string }>('/public/auth/verify-email', { token });

      if (!response.data.success) {
        throw new Error(response.data.message || 'Email verification failed');
      }
    } catch (error) {
      if (error && typeof error === 'object' && 'message' in error) {
        throw new Error((error as Error).message);
      }
      throw new Error('Email verification failed');
    }
  }

  /**
   * Resend verification email (public endpoint - no authentication required)
   * Rate limited - 5 minute cooldown between requests
   * @param usernameOrEmail - Username or email address to send verification to
   */
  async resendVerificationEmail(usernameOrEmail: string): Promise<void> {
    try {
      const response = await httpClient.post<{ success: boolean; message: string }>(
        '/public/auth/resend-verification',
        { usernameOrEmail }
      );

      if (!response.data.success) {
        throw new Error(response.data.message || 'Failed to resend verification email');
      }
    } catch (error) {
      if (error && typeof error === 'object' && 'message' in error) {
        throw new Error((error as Error).message);
      }
      throw new Error('Failed to resend verification email');
    }
  }

  /**
   * Get email verification status for authenticated user
   */
  async getVerificationStatus(): Promise<VerificationStatusResponse> {
    try {
      const response = await httpClient.get<VerificationStatusResponse>('/auth/verification-status');
      return response.data;
    } catch (error) {
      if (error && typeof error === 'object' && 'message' in error) {
        throw new Error((error as Error).message);
      }
      throw new Error('Failed to get verification status');
    }
  }

  /**
   * Reset password using token (public endpoint - no auth required)
   */
  async resetPasswordWithToken(token: string, newPassword: string): Promise<void> {
    try {
      await httpClient.post('/public/auth/reset-password', {
        token,
        newPassword
      });
    } catch (error) {
      if (error && typeof error === 'object' && 'message' in error) {
        throw new Error((error as Error).message);
      }
      throw new Error('Failed to reset password');
    }
  }

  /**
   * Logout user (SessionManager handles cleanup)
   */
  async logout(): Promise<void> {
    // SessionManager will handle token cleanup and HTTP client state
    queryClient.clear(); // Clear all React Query cache on logout
  }

}

// Singleton instance
export const authService = new AuthService();
export const authenticationService = authService; // Alias for consistency

/**
 * Enhanced Authentication Store
 *
 * OAuth 2.0 dual-token architecture with automatic refresh.
 *
 * Key improvements:
 * - Single token → Dual token (access + refresh)
 * - Manual token passing → Automatic token injection
 * - Reactive failure handling → Proactive token renewal
 */

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

import { SessionManager, LocalStorageSessionStorage } from '@app/services/SessionManager';
import { authHttpClient } from '@infra/api/AuthHttpClient';
import { configureHttpClientWithSessionManager } from '@infra/api/httpClient';
import { env } from '@shared/config';

import { authService } from '../services/AuthenticationService';

import type { RegisterWithResearcherRequest } from '@odysseus/shared-schemas';
import type {
  TokenPair,
  SessionStatus} from '@shared/session/types';

// User interface (unchanged for compatibility)
export interface User {
  id: string;
  username: string;
  lastActivity: string;
  role?: 'admin' | 'user';
}

/**
 * Enhanced authentication state
 */
interface AuthState {
  // Core session data
  user: User | null;
  tokens: TokenPair | null;
  sessionStatus: SessionStatus;

  // UI state
  isLoading: boolean;
  error: string | null;
  logoutReason: 'idle_timeout' | 'token_expired' | 'manual_logout' | null;

  // Computed properties
  isAuthenticated: boolean;
}

/**
 * Authentication actions (clean API)
 */
interface AuthActions {
  // Primary authentication methods
  login: (username: string, password: string) => Promise<boolean>;
  register: (username: string, password: string) => Promise<boolean>;
  registerWithResearcher: (request: RegisterWithResearcherRequest) => Promise<{ success: boolean; status?: 'approved' | 'pending'; message?: string }>;
  logout: () => Promise<void>;
  verify: () => Promise<boolean>;
  checkFirstTime: () => Promise<boolean>;

  // Session management
  updateSessionStatus: () => void;
  initializeFromStorage: () => void;

  // Internal state management
  setAuthData: (user: User, tokens: TokenPair) => void;
  clearAuth: (reason?: 'idle_timeout' | 'token_expired' | 'manual_logout') => void;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  reset: () => void;

  // Development debugging
  getDebugInfo: () => any;
}

interface AuthStore extends AuthState, AuthActions {}

// Initialize session manager with AuthHttpClient to prevent circular dependency
const sessionStorage = new LocalStorageSessionStorage();

// Create session manager with callback for session expiration
// Callback pattern: SessionManager notifies auth store when session expires
const sessionManager = new SessionManager(
  authHttpClient,
  sessionStorage,
  (reason) => {
    // When session expires, clear auth store and trigger UI update
    useAuthStore.getState().clearAuth(reason);
  }
);

// Configure httpClient to use SessionManager for automatic token handling
configureHttpClientWithSessionManager(sessionManager);

/**
 * Enhanced authentication store with OAuth 2.0 dual-token architecture
 */
export const useAuthStore = create<AuthStore>()(
  persist(
    (set, get) => ({
      // STATE
      
      user: null,
      tokens: null,
      sessionStatus: 'unauthenticated',
      isLoading: false,
      error: null,
      logoutReason: null,

      // Authentication state (reactive to token changes)
      isAuthenticated: false,

      // AUTHENTICATION METHODS

      /**
       * Login with username and password (primary method)
       */
      login: async (username: string, password: string) => {
        set({ isLoading: true, error: null, logoutReason: null });

        try {
          const result = await authService.login({ username, password });

          // AuthService now returns AuthResponse directly (not wrapped in success object)
          // Set tokens in session manager (handles HTTP client + storage)
          sessionManager.setTokens(result.tokens);

          // Update store state
          set({
            user: {
              ...result.user,
              lastActivity: new Date().toISOString() // Ensure lastActivity is set
            },
            tokens: result.tokens,
            sessionStatus: 'authenticated',
            isAuthenticated: true, // Update reactive authentication state
            isLoading: false,
            error: null,
            logoutReason: null // Clear any previous logout reason
          });

          return true;
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Login error';
          // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
          console.error('❌ [AUTH STORE] Login exception:', error);
          
          set({
            error: errorMessage,
            isLoading: false
          });
          return false;
        }
      },

      /**
       * Register new user account
       */
      register: async (username: string, password: string) => {
        set({ isLoading: true, error: null });

        try {
          const result = await authService.register({ username, password });

          // AuthService now returns AuthResponse directly (not wrapped in success object)
          // Set tokens in session manager
          sessionManager.setTokens(result.tokens);

          // Update store state
          set({
            user: {
              ...result.user,
              lastActivity: new Date().toISOString() // Ensure lastActivity is set
            },
            tokens: result.tokens,
            sessionStatus: 'authenticated',
            isLoading: false,
            error: null
          });

          return true;
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Registration error';
          // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
          console.error('❌ [AUTH STORE] Registration exception:', error);

          set({
            error: errorMessage,
            isLoading: false
          });
          return false;
        }
      },

      /**
       * Register with researcher profile (approval workflow)
       *
       * First user: Auto-approved as admin (authenticated immediately)
       * Subsequent users: Pending approval (awaiting admin action)
       */
      registerWithResearcher: async (request: RegisterWithResearcherRequest) => {
        set({ isLoading: true, error: null });

        try {
          const result = await authService.registerWithResearcher(request);

          // Case 1: Approved (first user) - Has tokens, authenticate immediately
          if (result.status === 'approved' && result.tokens) {
            sessionManager.setTokens(result.tokens);

            set({
              user: {
                ...result.user,
                lastActivity: new Date().toISOString()
              },
              tokens: result.tokens,
              sessionStatus: 'authenticated',
              isAuthenticated: true,
              isLoading: false,
              error: null
            });

            return {
              success: true,
              status: 'approved',
              message: result.message
            };
          }

          // Case 2: Pending (subsequent users) - No tokens, awaiting approval
          if (result.status === 'pending') {
            set({
              user: null, // Don't set user until approved
              tokens: null,
              sessionStatus: 'unauthenticated',
              isAuthenticated: false,
              isLoading: false,
              error: null
            });

            return {
              success: true,
              status: 'pending',
              message: result.message
            };
          }

          // Unexpected state
          throw new Error('Invalid registration response status');

        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Registration error';
          // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
          console.error('❌ [AUTH STORE] registerWithResearcher exception:', error);

          set({
            error: errorMessage,
            isLoading: false
          });

          return {
            success: false,
            message: errorMessage
          };
        }
      },

      /**
       * Verify existing session
       */
      verify: async () => {
        const tokens = sessionManager.getTokens();
        if (!tokens) {
          set({ sessionStatus: 'unauthenticated' });
          return false;
        }

        try {
          // Use SessionManager to get valid token (auto-refreshes if needed)
          const validToken = await sessionManager.getValidAccessToken();

          if (!validToken) {
            get().clearAuth();
            return false;
          }

          // Verify with backend
          const result = await authService.verifySession();

          // AuthService returns AuthResponse directly
          set({
            user: {
              ...result.user,
              lastActivity: new Date().toISOString() // Ensure lastActivity is set
            },
            tokens: sessionManager.getTokens(),
            sessionStatus: 'authenticated',
            error: null
          });
          return true;
        } catch (error) {
          // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
          console.error('❌ [AUTH STORE] Session verification error:', error);
          get().clearAuth();
          return false;
        }
      },

      /**
       * Check if this is first-time setup
       */
      checkFirstTime: async () => {
        try {
          const result = await authService.checkFirstTime();
          return result; // AuthService returns boolean directly
        } catch (error) {
          // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
          console.error('❌ [AUTH STORE] First time check failed:', error);
          return false;
        }
      },

      /**
       * Logout user and clear session
       */
      logout: async () => {
        set({ isLoading: true });

        try {
          // Attempt graceful logout with backend
          await authService.logout();
        } catch (error) {
          // eslint-disable-next-line no-console -- Warning logging for production monitoring
          console.warn('⚠️ [AUTH STORE] Backend logout failed (clearing local session anyway):', error);
        }

        // Always clear local session regardless of backend response
        sessionManager.clearSession();
        get().clearAuth();
      },

      // SESSION MANAGEMENT

      /**
       * Update session status from SessionManager
       */
      updateSessionStatus: () => {
        const newStatus = sessionManager.getSessionStatus();
        const currentStatus = get().sessionStatus;

        if (newStatus !== currentStatus) {
          set({ sessionStatus: newStatus });
        }
      },

      /**
       * Initialize store from persistent storage
       */
      initializeFromStorage: () => {
        const tokens = sessionManager.getTokens();
        const user = sessionStorage.getUser();

        if (tokens && user) {
          set({
            user,
            tokens,
            sessionStatus: sessionManager.getSessionStatus()
          });
        } else {
          set({ sessionStatus: 'unauthenticated' });
        }
      },

      // INTERNAL STATE MANAGEMENT

      /**
       * Set authentication data (used by login/register)
       */
      setAuthData: (user: User, tokens: TokenPair) => {
        set({
          user,
          tokens,
          sessionStatus: 'authenticated',
          isLoading: false,
          error: null
        });
      },

      /**
       * Clear authentication state
       *
       * @param reason - Why the session is being cleared (for UX messaging)
       */
      clearAuth: (reason: 'idle_timeout' | 'token_expired' | 'manual_logout' = 'manual_logout') => {
        set({
          user: null,
          tokens: null,
          sessionStatus: 'unauthenticated',
          isAuthenticated: false, // Clear authentication state
          isLoading: false,
          error: null,
          logoutReason: reason
        });
      },

      /**
       * Set loading state
       */
      setLoading: (loading: boolean) => {
        set({ isLoading: loading });
      },

      /**
       * Set error state
       */
      setError: (error: string | null) => {
        set({ error });
      },

      /**
       * Reset store to initial state
       */
      reset: () => {
        sessionManager.clearSession();
        get().clearAuth();
      },

      /**
       * Development debugging information
       */
      getDebugInfo: () => {
        if (!env.isDev()) {
          return null;
        }

        const sessionDebug = sessionManager.getDebugInfo();
        const storeState = get();

        return {
          storeState: {
            hasUser: !!storeState.user,
            hasTokens: !!storeState.tokens,
            sessionStatus: storeState.sessionStatus,
            isLoading: storeState.isLoading,
            error: storeState.error
          },
          sessionManager: sessionDebug
        };
      }
    }),
    {
      name: 'odysseus-auth-enhanced',
      
      // Only persist user data, tokens handled by SessionManager
      partialize: (state) => ({
        user: state.user
      }),
      
      // Initialize session manager on rehydration
      onRehydrateStorage: () => (state) => {
        if (state) {
          // Let SessionManager handle token restoration
          const authStore = useAuthStore.getState();
          authStore.initializeFromStorage();
        }
      }
    }
  )
);

// Export session manager for HTTP client integration
export { sessionManager };

// Development-only global debugging (removed in production builds)
if (env.isDev()) {
  (globalThis as any).__ODYSSEUS_SESSION_DEBUG__ = () => {
    const authState = useAuthStore.getState();
    return authState.getDebugInfo();
  };
}

import { NAMING_PATTERNS } from '@odysseus/shared-schemas';

import { useTubeStore } from '@domains/tubes';
import { toPositionKey } from '@shared/types/grid';

