/**
 * SearchEngine - Consolidated client-side search logic
 *
 * This class consolidates all client-side search operations:
 * - Text highlighting for matched queries
 * - Result formatting and enrichment
 * - Navigation to search results
 * - Researcher name resolution
 *
 * Following the "Smart Server, Dumb Client" pattern, this engine
 * handles presentation logic while the server handles search computation.
 */
export class SearchEngine {
  /**
   * Highlight all matches of query within text
   *
   * Returns an array of text segments, each marked as match or non-match.
   * Used by UI components to render bold/colored text for matches.
   *
   * @example
   * highlightMatches("CD34+ Cells", "CD34")
   * // Returns: [
   * //   { text: "CD34", isMatch: true },
   * //   { text: "+ Cells", isMatch: false }
   * // ]
   */
  static highlightMatches(text: string, query: string): HighlightedSegment[] {
    if (!query.trim() || !text) {
      return [{ text, isMatch: false }];
    }

    const segments: HighlightedSegment[] = [];

    // Escape special regex characters in query
    const escapedQuery = query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(escapedQuery, 'gi');

    let lastIndex = 0;
    let match: RegExpExecArray | null;

    while ((match = regex.exec(text)) !== null) {
      // Add non-match before this match
      if (match.index > lastIndex) {
        segments.push({
          text: text.substring(lastIndex, match.index),
          isMatch: false
        });
      }

      // Add the match
      segments.push({
        text: match[0],
        isMatch: true
      });

      lastIndex = regex.lastIndex;
    }

    // Add remaining non-match
    if (lastIndex < text.length) {
      segments.push({
        text: text.substring(lastIndex),
        isMatch: false
      });
    }

    return segments;
  }

  /**
   * Enrich search results with researcher names
   *
   * Resolves researcherId (UUID) to actual researcher names for display.
   * This is a "presenter" pattern - transforming IDs to human-readable names.
   *
   * @param results - Grouped search results from server
   * @param researchers - List of all researchers
   * @returns Results with researcher names added
   */
  static enrichWithResearchers(
    results: GroupedResult[],
    researchers: Researcher[]
  ): GroupedResult[] {
    if (!researchers || researchers.length === 0) {
      return results;
    }

    // Create lookup map for O(1) access
    const researcherMap = new Map(
      researchers.map(r => [r.id, `${r.firstName} ${r.lastName}`])
    );

    return results.map(group => ({
      ...group,
      tubes: group.tubes.map(tube => {
        if (tube.researcherId) {
          const researcherName = researcherMap.get(tube.researcherId);
          return {
            ...tube,
            researcherName // Add researcher name for display
          } as TubeData & { researcherName?: string };
        }
        return tube;
      })
    }));
  }

  /**
   * Format server results for display
   *
   * Takes raw server response and formats it for UI consumption:
   * - Converts API response to TubeData[]
   * - Uses server-side grouping if available (progressive enhancement)
   * - Falls back to client-side grouping if needed
   * - Enriches with researcher names
   * - Prepares highlighting metadata
   *
   * @param serverResult - Raw API response
   * @param query - Search query string
   * @param researchers - List of researchers for name resolution
   * @returns Display-ready results
   */
  static formatResultsForDisplay(
    serverResult: SearchResult | null | undefined,
    query: string,
    researchers: Researcher[] = []
  ): DisplayResults | null {
    if (!serverResult?.data) {
      return null;
    }

    // Convert API response to TubeData format
    const tubes: TubeData[] = serverResult.data.map((tube: any) => ({
      ...tube,
      sample: {
        ...tube.sample,
        // Ensure concentration is a number
        concentration: typeof tube.sample.concentration === 'string'
          ? (tube.sample.concentration ? Number(tube.sample.concentration) : undefined)
          : tube.sample.concentration
      }
    }));

    // Progressive enhancement: Use server-side grouping if available, otherwise client-side
    let grouped: GroupedResult[];

    if (serverResult.grouped && serverResult.grouped.length > 0) {
      // Server provided grouped results (faster, already computed)
      grouped = serverResult.grouped;
    } else {
      // Fallback to client-side grouping (backwards compatibility)
      grouped = groupTubesByRelevance(tubes, query);
    }

    // Enrich with researcher names
    grouped = SearchEngine.enrichWithResearchers(grouped, researchers);

    return {
      tubes,
      grouped,
      total: tubes.length,
      query,
      hasResults: tubes.length > 0
    };
  }

  /**
   * Navigate to search result and select tubes
   *
   * Handles the full navigation flow:
   * 1. Navigate to the tank/rack/box location
   * 2. Select the tubes in the grid
   * 3. Scroll into view
   *
   * This was previously in searchStore.navigateToGroup()
   *
   * @param tubes - Array of tubes to navigate to and select
   */
  static async navigateToResult(tubes: TubeData[]): Promise<void> {
    if (tubes.length === 0) return;

    // Get the first tube to determine navigation target
    const firstTube = tubes[0];
    const tankId = firstTube.location.tankId || NAMING_PATTERNS.TANK.ID_PATTERN(1);
    const rackId = firstTube.location.rackId;
    const boxId = firstTube.location.boxId;

    // Use atomic navigation service
    const { gridNavigationService } = await import('@domains/grid');
    await gridNavigationService.navigateToLocation({ tankId, rackId, boxId });

    const tubeStore = useTubeStore.getState();

    // Select the tubes for immediate visibility
    const positionKeys = tubes.map(tube =>
      toPositionKey(
        { tankId: tube.location.tankId || tankId, rackId: tube.location.rackId, boxId: tube.location.boxId },
        tube.location.position
      )
    );
    tubeStore.setSelection(new Set(positionKeys));
  }
}

import { NAMING_PATTERNS } from '@odysseus/shared-schemas';

import type { TubeData, TubeMedia } from '@domains/tubes/types';
import type { GroupedResult} from '@odysseus/shared-schemas';

/**
 * Convert media object to string for searching
 */
const getMediaString = (media: TubeMedia | undefined): string => {
  if (!media) return '';
  
  // Combine all fields for searching
  return [media.type, media.supplements, media.selection]
    .filter(Boolean)
    .join(' ');
};

/**
 * Group tubes by relevance for search results
 * 
 * This function maintains the existing grouping logic from the original SearchStore
 * but is now extracted as a pure utility function.
 */
export const groupTubesByRelevance = (tubes: TubeData[], query: string): GroupedResult[] => {
  if (!query.trim()) {
    // Group by cell type when no query
    const groups = new Map<string, TubeData[]>();
    tubes.forEach(tube => {
      // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- cellType is required; empty string indicates missing data, display as 'Unknown'
      const key = tube.sample.cellType || 'Unknown';
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key)!.push(tube);
    });

    return Array.from(groups.entries()).map(([key, groupTubes]) => ({
      groupKey: key,
      groupType: 'cellType' as const,
      tubes: groupTubes,
      primaryLocation: getPrimaryLocation(groupTubes),
      totalCount: groupTubes.length
    }));
  }

  const groups = new Map<string, {
    tubes: TubeData[],
    type: GroupedResult['groupType'],
    matchedField: string
  }>();

  tubes.forEach(tube => {
    let groupType: GroupedResult['groupType'] = 'cellType';

    // Determine what field matched the query
    if (tube.sample.donorInternalId?.toLowerCase().includes(query.toLowerCase())) {
      groupType = 'donor';
    } else if (tube.sample.donorSourceId?.toLowerCase().includes(query.toLowerCase())) {
      groupType = 'donor';
    } else if (tube.sample.cellType?.toLowerCase().includes(query.toLowerCase())) {
      groupType = 'cellType';
    } else if (tube.researcherId?.toLowerCase().includes(query.toLowerCase())) {
      // Search by researcherId (ID-based, not name)
      // Note: This searches by ID string. To search by name, need to fetch researcher data separately
      groupType = 'researcher';
    } else if (tube.sample.lotNumber?.toLowerCase().includes(query.toLowerCase())) {
      groupType = 'lotNumber';
    } else if (tube.sample.media && getMediaString(tube.sample.media).toLowerCase().includes(query.toLowerCase())) {
      groupType = 'media';
    } else {
      groupType = 'cellType';
    }

    // Group by tube's CURRENT identifier, not what was matched
    const tankId = tube.location.tankId || NAMING_PATTERNS.TANK.ID_PATTERN(1);
    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Cascading fallback chain: try each identifier, empty values fall through
    const currentGroupKey = tube.sample.donorInternalId || tube.sample.donorSourceId || tube.sample.lotNumber || tube.sample.cellType || 'Unknown';
    const locationKey = `${currentGroupKey}:${tankId}:${tube.location.rackId}:${tube.location.boxId}`;

    if (!groups.has(locationKey)) {
      groups.set(locationKey, { tubes: [], type: groupType, matchedField: currentGroupKey });
    }
    groups.get(locationKey)!.tubes.push(tube);
  });

  return Array.from(groups.entries())
    .map(([_key, { tubes: groupTubes, type, matchedField }]) => ({
      groupKey: matchedField,
      groupType: type,
      tubes: groupTubes,
      primaryLocation: getPrimaryLocation(groupTubes),
      totalCount: groupTubes.length
    }))
    .sort((a, b) => b.totalCount - a.totalCount);
};

/**
 * Get primary location for a group of tubes
 */
export const getPrimaryLocation = (tubes: TubeData[]): string => {
  if (tubes.length === 0) return 'No location';

  // Return raw location data - display names will be resolved in UI components
  const firstTube = tubes[0];
  const tankId = firstTube.location.tankId || NAMING_PATTERNS.TANK.ID_PATTERN(1);

  return `${tankId}:${firstTube.location.rackId}:${firstTube.location.boxId}`;
};

/**
 * Transform search result to SearchResults format
 * 
 * This maintains compatibility with the existing SearchResults interface
 */
export const transformSearchResult = (
  searchResult: { data: any[] }, // Accept flexible API response
  query: string
) => {
  // Convert API response tubes to proper TubeData format
  const tubes: TubeData[] = (searchResult.data || []).map((tube: any) => ({
    ...tube,
    sample: {
      ...tube.sample,
      // Convert concentration from string|number to number for storage consistency
      concentration: typeof tube.sample.concentration === 'string' 
        ? (tube.sample.concentration ? Number(tube.sample.concentration) : undefined)
        : tube.sample.concentration
    }
  }));
  
  const grouped = groupTubesByRelevance(tubes, query);
  
  return {
    tubes,
    grouped,
    total: tubes.length,
    query,
    hasResults: tubes.length > 0
  };
};

import { useMemo } from 'react';

import { formatConcentrationDisplay, formatResearcherDropdownDisplay } from '@odysseus/shared-schemas';
import { Download, MapPin } from 'lucide-react';

import { useUserSettings } from '@domains/authentication';
import { useResearchersQuery } from '@domains/researchers';
import { useSearch, useSearchStore } from '@domains/search';
import { useStorageStore } from '@domains/storage';
import { formatPositionForBox } from '@domains/storage/utils/positionDisplayUtils';
import { useTubeStore } from '@domains/tubes';
import { TubeIcon } from '@shared/ui/components/icons';



import { SortDropdown } from './SortDropdown';

import type { SearchResults as SearchResultsType} from '@domains/search';

interface SearchResultsProps {
  results: SearchResultsType | null;
  isSearching?: boolean;
  onClose?: () => void;
}

export function SearchResults({ results, isSearching = false, onClose }: SearchResultsProps) {
  // ALL HOOKS MUST BE CALLED BEFORE ANY CONDITIONAL RETURNS
  const { navigateToResult } = useSearch();
  const { currentTank } = useTubeStore();
  const { getCurrentTanks, getBox } = useStorageStore();
  const { data: researchers = [] } = useResearchersQuery();
  const { settings: userSettings } = useUserSettings();
  const sortField = useSearchStore(state => state.sortField);
  const sortDirection = useSearchStore(state => state.sortDirection);

  // Extract data for sorting (handle null results safely)
  const tubes = results?.tubes ?? [];
  const totalCount = results?.total ?? 0;
  const query = results?.query ?? '';

  // Client-side sorting of grouped results - MUST be called before early returns
  const sortedGroups = useMemo(() => {
    const groups = results?.grouped ?? [];
    if (!groups || groups.length === 0) return groups;

    const sorted = [...groups].sort((a, b) => {
      const firstTubeA = a.tubes[0];
      const firstTubeB = b.tubes[0];

      let compareValue = 0;

      switch (sortField) {
        case 'location': {
          // Sort by tankId → rackId → boxId → position
          const locationA = `${firstTubeA.location.tankId}:${firstTubeA.location.rackId}:${firstTubeA.location.boxId}:${firstTubeA.location.position}`;
          const locationB = `${firstTubeB.location.tankId}:${firstTubeB.location.rackId}:${firstTubeB.location.boxId}:${firstTubeB.location.position}`;
          compareValue = locationA.localeCompare(locationB);
          break;
        }

        case 'date': {
          const dateA = firstTubeA.sample?.date ? new Date(firstTubeA.sample.date).getTime() : 0;
          const dateB = firstTubeB.sample?.date ? new Date(firstTubeB.sample.date).getTime() : 0;
          compareValue = dateA - dateB;
          break;
        }

        case 'cellType': {
          const cellTypeA = firstTubeA.sample?.cellType ?? '';
          const cellTypeB = firstTubeB.sample?.cellType ?? '';
          compareValue = cellTypeA.localeCompare(cellTypeB);
          break;
        }

        case 'researcher': {
          const researcherA = researchers.find(r => r.id === firstTubeA.researcherId);
          const researcherB = researchers.find(r => r.id === firstTubeB.researcherId);
          const nameA = researcherA ? `${researcherA.lastName}, ${researcherA.firstName}` : '';
          const nameB = researcherB ? `${researcherB.lastName}, ${researcherB.firstName}` : '';
          compareValue = nameA.localeCompare(nameB);
          break;
        }

        case 'lotNumber': {
          const lotA = firstTubeA.sample?.lotNumber ?? '';
          const lotB = firstTubeB.sample?.lotNumber ?? '';
          compareValue = lotA.localeCompare(lotB);
          break;
        }

        default:
          compareValue = 0;
      }

      return sortDirection === 'asc' ? compareValue : -compareValue;
    });

    return sorted;
  }, [results, sortField, sortDirection, researchers]);

  // NOW safe to do early returns after all hooks are called
  if (!results && isSearching) {
    return (
      <div className="p-4">
        <div className="flex items-center justify-center py-8">
          <div className="animate-spin w-6 h-6 border-2 border-blue-600 border-t-transparent rounded-full" />
          <span className="ml-2 text-sm text-gray-600">Searching...</span>
        </div>
      </div>
    );
  }

  if (!results) {
    return null;
  }

  // Helper: Highlight matching terms with modern underline accent
  const highlightText = (text: string, searchQuery: string): React.ReactNode => {
    if (!searchQuery || !text) return text;

    // Extract search terms (split by spaces, remove empty strings)
    const terms = searchQuery
      .toLowerCase()
      .split(/\s+/)
      .filter(t => t.length > 0);

    if (terms.length === 0) return text;

    // Build regex to match any term (case-insensitive)
    const regex = new RegExp(`(${terms.map(t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|')})`, 'gi');

    // Split text by matches
    const parts = text.split(regex);

    return (
      <>
        {parts.map((part, i) => {
          const isMatch = terms.some(term => part.toLowerCase().includes(term));
          return isMatch ? (
            <span
              key={i}
              className="border-b-2 border-[#1e90ff] dark:border-[#4da6ff]"
              style={{
                transition: 'border-color 120ms ease',
                display: 'inline',
                paddingBottom: '1px'
              }}
            >
              {part}
            </span>
          ) : (
            part
          );
        })}
      </>
    );
  };

  // Resolve display names from configuration
  const getDisplayLocation = (primaryLocation: string): string => {
    const [tankId, rackId, boxId] = primaryLocation.split(':');
    const tanks = getCurrentTanks();

    const tank = tanks.find(t => t.id === tankId);
    const tankName = tank?.name ?? `Tank ${tankId}`;

    const rack = tank?.racks?.find(r => r.id === rackId);
    const rackName = rack?.name ?? `Rack ${rackId}`;

    return `${tankName} → ${rackName} → Box ${boxId}`;
  };

  // Get researcher name from ID
  const getResearcherName = (researcherId: string | undefined): string => {
    if (!researcherId) return 'Unknown';
    const researcher = researchers.find(r => r.id === researcherId);
    return researcher ? formatResearcherDropdownDisplay(researcher) : researcherId;
  };

  // Format date as MM/DD/YYYY
  const formatDate = (dateString: string | Date | undefined): string => {
    if (!dateString) return '';
    try {
      const date = dateString instanceof Date ? dateString : new Date(dateString);
      const month = (date.getMonth() + 1).toString().padStart(2, '0');
      const day = date.getDate().toString().padStart(2, '0');
      const year = date.getFullYear();
      return `${month}/${day}/${year}`;
    } catch {
      return typeof dateString === 'string' ? dateString : '';
    }
  };

  const handleExportResults = () => {
    const headers = ['Tank', 'Rack', 'Box', 'Position', 'Position Label', 'Cell Type', 'Donor Internal ID', 'Donor Source ID', 'Lot Number', 'Researcher ID', 'Date'];
    const csvContent = [
      headers.join(','),
      ...tubes.map(tube => {
        // Get box configuration for position label formatting
        const box = getBox(tube.location.tankId, tube.location.rackId, tube.location.boxId);
        let positionLabel = tube.location.position.toString();

        if (box?.gridConfig) {
          try {
            positionLabel = formatPositionForBox(
              tube.location.position,
              tube.location.tankId,
              tube.location.rackId,
              tube.location.boxId,
              box.gridConfig,
              userSettings
            );
          } catch {
            // Fall back to numeric if formatting fails
            positionLabel = tube.location.position.toString();
          }
        }

        return [
          tube.location.tankId,
          tube.location.rackId,
          tube.location.boxId,
          tube.location.position,
          positionLabel,
          tube.sample.cellType ?? '',
          tube.sample.donorInternalId ?? '',
          tube.sample.donorSourceId ?? '',
          tube.sample.lotNumber ?? '',
          tube.researcherId ?? '',
          tube.sample.date ?? ''
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `search_results_${new Date().toISOString().split('T')[0]}.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleGroupClick = async (group: any) => {
    // Add tankId if missing for legacy data compatibility
    const tubesWithTankId = group.tubes.map((tube: any) => ({
      ...tube,
      location: {
        ...tube.location,
        tankId: tube.location?.tankId || currentTank
      }
    }));
    await navigateToResult(tubesWithTankId);

    // Close search results after navigation
    onClose?.();
  };

  const formatPositions = (tubes: any[]): string => {
    if (tubes.length === 0) return '';

    // Get location info from first tube (all tubes in group share same box)
    const firstTube = tubes[0];
    const { tankId, rackId, boxId } = firstTube.location;

    // Get box configuration for grid dimensions
    const box = getBox(tankId, rackId, boxId);
    if (!box?.gridConfig) {
      // Fallback to numeric if box config not found
      const positions = Array.from(new Set(
        tubes.map(tube => tube.location.position).filter(pos => pos != null).map(pos => Number(pos))
      )).sort((a, b) => a - b);
      return positions.length === 1 ? `Pos: ${positions[0]}` : `Pos: ${positions.join(', ')}`;
    }

    // Get unique positions and sort numerically
    const positions = Array.from(new Set(
      tubes
        .map(tube => tube.location.position)
        .filter(pos => pos != null)
        .map(pos => Number(pos))
    )).sort((a, b) => a - b);

    if (positions.length === 1) {
      const label = formatPositionForBox(positions[0], tankId, rackId, boxId, box.gridConfig, userSettings);
      return `Pos: ${label}`;
    }

    if (positions.length <= 3) {
      const labels = positions.map(pos =>
        formatPositionForBox(pos, tankId, rackId, boxId, box.gridConfig, userSettings)
      );
      return `Pos: ${labels.join(', ')}`;
    }

    // Create smart ranges (work on numeric positions, then convert boundaries to labels)
    const ranges: string[] = [];
    let start = positions[0];
    let end = positions[0];

    for (let i = 1; i < positions.length; i++) {
      if (positions[i] === end + 1) {
        end = positions[i];
      } else {
        // Convert range boundaries to labels
        const startLabel = formatPositionForBox(start, tankId, rackId, boxId, box.gridConfig, userSettings);
        const endLabel = formatPositionForBox(end, tankId, rackId, boxId, box.gridConfig, userSettings);
        ranges.push(start === end ? startLabel : `${startLabel}-${endLabel}`);
        start = positions[i];
        end = positions[i];
      }
    }
    // Don't forget the last range
    const startLabel = formatPositionForBox(start, tankId, rackId, boxId, box.gridConfig, userSettings);
    const endLabel = formatPositionForBox(end, tankId, rackId, boxId, box.gridConfig, userSettings);
    ranges.push(start === end ? startLabel : `${startLabel}-${endLabel}`);

    // Limit display to prevent overflow - show first 4 ranges, then count
    if (ranges.length > 4) {
      const displayRanges = ranges.slice(0, 4);
      const remaining = ranges.length - 4;
      return `Pos: ${displayRanges.join(', ')} (+${remaining} more)`;
    }

    return `Pos: ${ranges.join(', ')}`;
  };

  return (
    <div className="max-h-[600px] overflow-hidden relative flex flex-col">
      {/* Loading overlay when refetching */}
      {isSearching && (
        <div className="absolute inset-0 bg-white/50 flex items-start justify-center pt-2 z-10">
          <div className="flex items-center bg-white px-3 py-1 rounded-full shadow-sm border border-gray-200">
            <div className="animate-spin w-3 h-3 border-2 border-blue-600 border-t-transparent rounded-full" />
            <span className="ml-2 text-xs text-gray-600">Updating...</span>
          </div>
        </div>
      )}

      {/* Sort Controls */}
      <SortDropdown />

      {/* Scrollable Results Container */}
      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        {/* Results Header */}
        <div className="flex items-center justify-between border-b pb-2">
        <div className="text-sm text-gray-700 dark:text-gray-300 font-medium">
          {totalCount} tube{totalCount !== 1 ? 's' : ''} found
        </div>

        {tubes.length > 0 && (
          <button
            onClick={handleExportResults}
            className="flex items-center space-x-1 px-2 py-1 text-xs transition-colors"
            style={{ color: '#5987b6' }}
            onMouseEnter={(e) => e.currentTarget.style.color = '#4a7099'}
            onMouseLeave={(e) => e.currentTarget.style.color = '#5987b6'}
            title="Export search results"
          >
            <Download className="w-3 h-3" />
            <span>Export</span>
          </button>
        )}
      </div>

        {/* Grouped Results - New 4-line format */}
        {sortedGroups.length > 0 ? (
          <div className="space-y-2">
            {sortedGroups.map((group, index) => {
            const firstTube = group.tubes[0];
            // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- cellType is required; empty string indicates missing data, display as 'Unknown'
            const cellType = firstTube.sample?.cellType || 'Unknown';
            const donorInternal = firstTube.sample?.donorInternalId ?? '';
            const donorSource = firstTube.sample?.donorSourceId ?? '';
            const cultureCondition = firstTube.sample?.cultureCondition ?? '';
            const lotNumber = firstTube.sample?.lotNumber ?? '';
            const concentration = formatConcentrationDisplay(
              firstTube.sample?.concentration,
              firstTube.sample?.concentrationUnit
            );
            const date = formatDate(firstTube.sample?.date);
            const researcherName = getResearcherName(firstTube.researcherId);
            const location = getDisplayLocation(group.primaryLocation);

            return (
              <button
                type="button"
                key={index}
                onClick={() => handleGroupClick(group)}
                className="w-full text-left p-2.5 border border-gray-200 dark:border-gray-700 rounded-md hover:border-blue-300 dark:hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 cursor-pointer transition-all"
                aria-label={`View ${group.totalCount} tube${group.totalCount !== 1 ? 's' : ''} of ${cellType}${donorInternal ? `, donor ${donorInternal}` : ''}${location ? `, located in ${location}` : ''}`}
              >
                {/* Line 1: Cell Type with tube count badge in top-right */}
                <div className="flex items-start justify-between mb-1">
                  <div className="flex items-center space-x-1.5 flex-1 min-w-0">
                    <TubeIcon className="text-black flex-shrink-0" size={14} aria-hidden="true" />
                    <div className="text-xs font-semibold text-black">
                      {highlightText(cellType, query)}
                    </div>
                  </div>
                  <span className="px-2 py-0.5 rounded-full text-xs font-medium ml-2 flex-shrink-0 text-white" style={{ backgroundColor: '#5987b6' }}>
                    {group.totalCount} tube{group.totalCount !== 1 ? 's' : ''}
                  </span>
                </div>

                {/* Lines 2-4 with vertical indicator line */}
                <div className="flex">
                  {/* Vertical line indicator */}
                  <div className="ml-2 mr-2 mt-0.5 mb-1 border-l-2 border-gray-300"></div>

                  <div className="flex-1">
                    {/* Line 2: Donor IDs */}
                    {(donorInternal || donorSource) && (
                      <div className="text-xs text-black mb-1 flex items-center space-x-2">
                        {donorInternal && (
                          <>
                            <span className="font-normal">Int. ID:</span>
                            <span className="font-semibold">{highlightText(donorInternal, query)}</span>
                          </>
                        )}
                        {donorInternal && donorSource && <span>•</span>}
                        {donorSource && (
                          <>
                            <span className="font-normal">Src. ID:</span>
                            <span className="font-semibold">{highlightText(donorSource, query)}</span>
                          </>
                        )}
                      </div>
                    )}

                    {/* Line 3: Culture Condition • LOT # */}
                    <div className="text-xs text-black mb-1 flex items-center space-x-2">
                      {cultureCondition && (
                        <>
                          <span>{highlightText(cultureCondition, query)}</span>
                          {lotNumber && <span>•</span>}
                        </>
                      )}
                      {lotNumber && (
                        <>
                          <span>LOT #: {highlightText(lotNumber, query)}</span>
                        </>
                      )}
                    </div>

                    {/* Line 4: Concentration • Date • Researcher */}
                    <div className="text-xs text-black mb-1 flex items-center space-x-2">
                      {concentration && (
                        <>
                          <span>{concentration}</span>
                          {(date || researcherName) && <span>•</span>}
                        </>
                      )}
                      {date && (
                        <>
                          <span>{date}</span>
                          {researcherName && <span>•</span>}
                        </>
                      )}
                      {researcherName && <span>{highlightText(researcherName, query)}</span>}
                    </div>
                  </div>
                </div>

                {/* Line 5: Location with map icon aligned with tube icon above */}
                <div className="text-xs flex items-start space-x-1.5 min-w-0" style={{ color: '#5987b6' }}>
                  <MapPin className="w-3 h-3 flex-shrink-0 mt-0.5" aria-hidden="true" />
                  <div className="flex items-baseline flex-wrap gap-x-2 gap-y-0.5 min-w-0">
                    <span className="whitespace-nowrap">{location}</span>
                    <span className="flex-shrink-0">•</span>
                    <span>{formatPositions(group.tubes)}</span>
                  </div>
                </div>
              </button>
              );
            })}
          </div>
        ) : (
          <div className="text-center py-8 text-gray-500 dark:text-gray-400">
            <TubeIcon className="w-8 h-8 mx-auto mb-2 opacity-30" />
            <p className="text-sm">No results found</p>
            <p className="text-xs text-gray-400 dark:text-gray-500 mt-1">Try adjusting your search or filters</p>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Storage Store
 * State management for storage equipment configurations
 * Types from shared-schemas (single source of truth)
 */

import {
  EQUIPMENT_DEFAULTS,
  NAMING_PATTERNS,
  SYSTEM_DEFAULTS,
} from '@odysseus/shared-schemas';
import { create } from 'zustand';
import { persist } from 'zustand/middleware';

import {
  DEFAULT_GRID_CONFIG,
  GRID_TEMPLATES,
} from '../utils/gridHelpers';

import type {
  LabConfiguration,
  SystemConfiguration,
  TankConfiguration,
  RackConfiguration,
  BoxConfiguration,
  GridConfiguration,
  PositionDisplayConfig} from '@odysseus/shared-schemas';

interface ConfigurationState {
  // Current state
  systemConfig: SystemConfiguration;

  // Auto-synced from systemConfig.availableLabs
  // Single source of truth: availableLabs is authoritative, currentLab is auto-computed
  currentLab: LabConfiguration;

  // Actions
  setCurrentLab: (labId: string) => void;
  addLab: (lab: LabConfiguration) => void;
  updateLab: (labId: string, updates: Partial<LabConfiguration>) => void;
  deleteLab: (labId: string) => void;
  
  // Tank management
  addTank: (labId: string, tank: TankConfiguration) => void;
  updateTank: (labId: string, tankId: string, updates: Partial<TankConfiguration>) => void;
  deleteTank: (labId: string, tankId: string) => Promise<void>;
  deleteTankLocally: (labId: string, tankId: string) => void;

  // Equipment management
  addRack: (labId: string, tankId: string, rack: RackConfiguration) => void;
  updateRack: (labId: string, tankId: string, rackId: string, updates: Partial<RackConfiguration>) => void;
  deleteRack: (labId: string, tankId: string, rackId: string) => void;
  
  // Box management (individual customization)
  updateBox: (labId: string, tankId: string, rackId: string, boxId: string, updates: Partial<BoxConfiguration>) => void;
  addBoxToRack: (labId: string, tankId: string, rackId: string, box: BoxConfiguration) => void;
  deleteBox: (labId: string, tankId: string, rackId: string, boxId: string) => void;
  
  // Grid configuration
  updateBoxGridConfig: (labId: string, tankId: string, rackId: string, boxId: string, gridConfig: GridConfiguration) => void;
  getAvailableGridTemplates: () => readonly GridConfiguration[];
  
  // Utilities
  getCurrentTanks: () => TankConfiguration[];
  getCurrentRacks: (tankId?: string) => RackConfiguration[];
  getCurrentBoxes: (tankId: string, rackId: string) => BoxConfiguration[];
  getBox: (tankId: string, rackId: string, boxId: string) => BoxConfiguration | undefined;
  getBoxPositionDisplay: (tankId: string, rackId: string, boxId: string) => PositionDisplayConfig | undefined;
  resetToDefaults: () => void;
  
  // Server synchronization (now delegated to React Query)
  // Note: loadFromServer and saveToServer are deprecated - use React Query hooks instead
  loadFromServer: () => Promise<void>;
  saveToServer: () => Promise<void>;
  migrateConfigurationStructure: (config: any) => any;
  ensureDefaultConfiguration: () => void;
  initialize: () => void;
}

/**
 * Default Box Configuration
 */
const DEFAULT_BOX_CONFIG: BoxConfiguration = {
  id: 'default-box',
  name: 'Standard Box',
  gridConfig: DEFAULT_GRID_CONFIG,
  description: 'Standard laboratory storage box with 9x9 grid',
};

/**
 * Default Tank Configuration
 * Uses shared constants for naming and defaults
 */
const DEFAULT_TANK_CONFIG: TankConfiguration = {
  id: NAMING_PATTERNS.TANK.ID_PATTERN(1),
  name: NAMING_PATTERNS.TANK.DEFAULT_NAME(1),
  location: NAMING_PATTERNS.TANK.DEFAULT_LOCATION,
  isActive: true,
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString(),
  defaultGridConfig: DEFAULT_GRID_CONFIG,
  racks: [
    {
      id: '1',
      name: NAMING_PATTERNS.RACK.DEFAULT_NAME(1),
      capacity: EQUIPMENT_DEFAULTS.BOXES_PER_RACK,
      location: NAMING_PATTERNS.TANK.DEFAULT_LOCATION,
      isActive: true,
      boxes: Array.from({ length: EQUIPMENT_DEFAULTS.BOXES_PER_RACK }, (_, i) => ({
        id: NAMING_PATTERNS.BOX.LETTER_NAME(i),
        name: NAMING_PATTERNS.BOX.DEFAULT_NAME(i),
        gridConfig: DEFAULT_GRID_CONFIG,
        position: i + 1,
      })),
    },
  ],
};

/**
 * Default Lab Configuration
 * Uses shared constants for system defaults
 */
const DEFAULT_LAB_CONFIG: LabConfiguration = {
  id: 'default-lab',
  name: SYSTEM_DEFAULTS.LAB.NAME,
  organization: SYSTEM_DEFAULTS.LAB.ORGANIZATION,
  isActive: true,
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString(),
  equipment: {
    tanks: [DEFAULT_TANK_CONFIG],
    defaultBoxConfig: DEFAULT_BOX_CONFIG,
    defaultGridConfig: DEFAULT_GRID_CONFIG,
  },
  settings: {
    requireAuth: SYSTEM_DEFAULTS.SETTINGS.REQUIRE_AUTH,
    allowDataExport: true,
    enableRealTimeSync: SYSTEM_DEFAULTS.SETTINGS.ENABLE_REAL_TIME_SYNC,
  },
};

/**
 * Create default system configuration
 * Uses shared constants for all defaults
 */
const createDefaultSystemConfig = (): SystemConfiguration => ({
  currentLabId: DEFAULT_LAB_CONFIG.id,
  availableLabs: [DEFAULT_LAB_CONFIG],
  globalSettings: {
    theme: SYSTEM_DEFAULTS.SETTINGS.THEME,
    language: SYSTEM_DEFAULTS.SETTINGS.LANGUAGE,
    timezone: SYSTEM_DEFAULTS.SETTINGS.TIMEZONE,
    autoBackup: SYSTEM_DEFAULTS.SETTINGS.AUTO_BACKUP,
  },
  version: SYSTEM_DEFAULTS.CONFIGURATION.VERSION,
});

/**
 * Migrate old GridConfiguration format to new format
 * Old: {rows, columns, totalPositions, displayName}
 * New: {rows, cols, template}
 */
function migrateGridConfig(oldGrid: any): GridConfiguration {
  if (!oldGrid) return DEFAULT_GRID_CONFIG;

  // If already has new format, return as-is
  if (oldGrid.cols !== undefined && oldGrid.template !== undefined) {
    return oldGrid as GridConfiguration;
  }

  // If has old format, convert it
  if (oldGrid.columns !== undefined) {
    // Determine template based on dimensions
    let template = 'standard';
    if (oldGrid.rows === 8 && oldGrid.columns === 8) template = 'compact';
    else if (oldGrid.rows === 9 && oldGrid.columns === 9) template = 'standard';
    else if (oldGrid.rows === 10 && oldGrid.columns === 10) template = 'large';
    else if (oldGrid.rows === 12 && oldGrid.columns === 8) template = 'rectangular';

    return {
      rows: oldGrid.rows,
      cols: oldGrid.columns,
      template
    };
  }

  return DEFAULT_GRID_CONFIG;
}

export const useStorageStore = create<ConfigurationState>()(
  persist(
    (set, get) => {
      // Helper to derive currentLab from systemConfig
      const deriveCurrentLab = (systemConfig: SystemConfiguration): LabConfiguration => {
        const lab = systemConfig.availableLabs.find(
          l => l.id === systemConfig.currentLabId
        );
        return lab ?? DEFAULT_LAB_CONFIG;
      };

      // Wrapped set function that auto-syncs currentLab
      const syncedSet = (updates: Partial<ConfigurationState> | ((state: ConfigurationState) => Partial<ConfigurationState>)) => {
        if (typeof updates === 'function') {
          set((state) => {
            const partial = updates(state);
            // If systemConfig changed, auto-sync currentLab
            if (partial.systemConfig) {
              return {
                ...partial,
                currentLab: deriveCurrentLab(partial.systemConfig)
              };
            }
            return partial;
          });
        } else {
          // If systemConfig changed, auto-sync currentLab
          if (updates.systemConfig) {
            set({
              ...updates,
              currentLab: deriveCurrentLab(updates.systemConfig)
            });
          } else {
            set(updates);
          }
        }
      };

      const defaultSystemConfig = createDefaultSystemConfig();

      return {
        systemConfig: defaultSystemConfig,
        currentLab: deriveCurrentLab(defaultSystemConfig),

      setCurrentLab: (labId: string) => {
        const { systemConfig } = get();
        const lab = systemConfig.availableLabs.find(l => l.id === labId);
        if (lab) {
          syncedSet({
            systemConfig: {
              ...systemConfig,
              currentLabId: labId
            }
          });
          // currentLab automatically synced
        }
      },

      addLab: (lab: LabConfiguration) => {
        const { systemConfig } = get();
        const newLab = {
          ...lab,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString()
        };

        syncedSet({
          systemConfig: {
            ...systemConfig,
            availableLabs: [...systemConfig.availableLabs, newLab]
          }
        });
      },

      updateLab: (labId: string, updates: Partial<LabConfiguration>) => {
        const { systemConfig } = get();
        const updatedLabs = systemConfig.availableLabs.map(lab =>
          lab.id === labId
            ? { ...lab, ...updates, updatedAt: new Date().toISOString() }
            : lab
        );

        syncedSet({
          systemConfig: {
            ...systemConfig,
            availableLabs: updatedLabs
          }
        });
        // currentLab automatically synced
      },

      deleteLab: (labId: string) => {
        const { systemConfig } = get();
        const filteredLabs = systemConfig.availableLabs.filter(lab => lab.id !== labId);

        // If deleting current lab, switch to first available
        const newCurrentLabId = labId === systemConfig.currentLabId
          ? filteredLabs[0]?.id || DEFAULT_LAB_CONFIG.id
          : systemConfig.currentLabId;

        syncedSet({
          systemConfig: {
            ...systemConfig,
            availableLabs: filteredLabs,
            currentLabId: newCurrentLabId
          }
        });
        // currentLab automatically synced
      },

      addTank: (labId: string, tank: TankConfiguration) => {
        get().updateLab(labId, {
          equipment: {
            ...get().currentLab.equipment,
            tanks: [...get().currentLab.equipment.tanks, tank]
          }
        });
      },

      updateTank: (labId: string, tankId: string, updates: Partial<TankConfiguration>) => {
        const { systemConfig } = get();
        const lab = systemConfig.availableLabs.find(l => l.id === labId);
        if (!lab?.equipment.tanks) return;

        const updatedTanks = lab.equipment.tanks.map(tank =>
          tank.id === tankId ? { ...tank, ...updates, updatedAt: new Date().toISOString() } : tank
        );

        // Create the updated lab with new tank data
        const updatedLab = {
          ...lab,
          equipment: {
            ...lab.equipment,
            tanks: updatedTanks
          },
          updatedAt: new Date().toISOString()
        };

        // Update availableLabs
        const updatedAvailableLabs = systemConfig.availableLabs.map(l =>
          l.id === labId ? updatedLab : l
        );

        syncedSet({
          systemConfig: {
            ...systemConfig,
            availableLabs: updatedAvailableLabs
          }
        });
        // currentLab automatically synced
      },

      deleteTank: async (labId: string, tankId: string) => {
        // Remove tank from local state
        // Server sync handled by caller via saveToServer()
        const lab = get().systemConfig.availableLabs.find(l => l.id === labId);
        if (lab?.equipment?.tanks) {
          const filteredTanks = lab.equipment.tanks.filter(tank => tank.id !== tankId);
          get().updateLab(labId, {
            equipment: {
              ...lab.equipment,
              tanks: filteredTanks
            }
          });
        }
      },

      deleteTankLocally: (labId: string, tankId: string) => {
        // Local tank deletion for use by React Query mutations
        const lab = get().systemConfig.availableLabs.find(l => l.id === labId);
        if (lab?.equipment?.tanks) {
          const filteredTanks = lab.equipment.tanks.filter(tank => tank.id !== tankId);
          get().updateLab(labId, {
            equipment: {
              ...lab.equipment,
              tanks: filteredTanks
            }
          });
        }
      },

      addRack: (labId: string, tankId: string, rack: RackConfiguration) => {
        const lab = get().systemConfig.availableLabs.find(l => l.id === labId);
        if (!lab?.equipment.tanks) return;

        const updatedTanks = lab.equipment.tanks.map(tank =>
          tank.id === tankId 
            ? { ...tank, racks: [...tank.racks, rack] }
            : tank
        );

        get().updateLab(labId, {
          equipment: {
            ...lab.equipment,
            tanks: updatedTanks
          }
        });
      },

      updateRack: (labId: string, tankId: string, rackId: string, updates: Partial<RackConfiguration>) => {
        const lab = get().systemConfig.availableLabs.find(l => l.id === labId);
        if (!lab?.equipment.tanks) return;

        const updatedTanks = lab.equipment.tanks.map(tank =>
          tank.id === tankId
            ? {
                ...tank,
                racks: tank.racks.map(rack =>
                  rack.id === rackId ? { ...rack, ...updates } : rack
                )
              }
            : tank
        );

        get().updateLab(labId, {
          equipment: {
            ...lab.equipment,
            tanks: updatedTanks
          }
        });
      },

      deleteRack: (labId: string, tankId: string, rackId: string) => {
        const lab = get().systemConfig.availableLabs.find(l => l.id === labId);
        if (!lab?.equipment.tanks) return;

        const updatedTanks = lab.equipment.tanks.map(tank =>
          tank.id === tankId
            ? { ...tank, racks: tank.racks.filter(rack => rack.id !== rackId) }
            : tank
        );

        get().updateLab(labId, {
          equipment: {
            ...lab.equipment,
            tanks: updatedTanks
          }
        });
      },

      updateBox: (labId: string, tankId: string, rackId: string, boxId: string, updates: Partial<BoxConfiguration>) => {
        const lab = get().systemConfig.availableLabs.find(l => l.id === labId);
        if (!lab?.equipment.tanks) return;

        const updatedTanks = lab.equipment.tanks.map(tank =>
          tank.id === tankId
            ? {
                ...tank,
                racks: tank.racks.map(rack =>
                  rack.id === rackId
                    ? {
                        ...rack,
                        boxes: rack.boxes.map(box =>
                          box.id === boxId ? { ...box, ...updates } : box
                        )
                      }
                    : rack
                )
              }
            : tank
        );

        get().updateLab(labId, {
          equipment: {
            ...lab.equipment,
            tanks: updatedTanks
          }
        });
      },

      addBoxToRack: (labId: string, tankId: string, rackId: string, box: BoxConfiguration) => {
        const lab = get().systemConfig.availableLabs.find(l => l.id === labId);
        if (!lab?.equipment.tanks) return;

        const updatedTanks = lab.equipment.tanks.map(tank =>
          tank.id === tankId
            ? {
                ...tank,
                racks: tank.racks.map(rack =>
                  rack.id === rackId
                    ? { ...rack, boxes: [...rack.boxes, box] }
                    : rack
                )
              }
            : tank
        );

        get().updateLab(labId, {
          equipment: {
            ...lab.equipment,
            tanks: updatedTanks
          }
        });
      },

      deleteBox: (labId: string, tankId: string, rackId: string, boxId: string) => {
        const lab = get().systemConfig.availableLabs.find(l => l.id === labId);
        if (!lab?.equipment.tanks) return;

        const updatedTanks = lab.equipment.tanks.map(tank =>
          tank.id === tankId
            ? {
                ...tank,
                racks: tank.racks.map(rack =>
                  rack.id === rackId
                    ? { ...rack, boxes: rack.boxes.filter(box => box.id !== boxId) }
                    : rack
                )
              }
            : tank
        );

        get().updateLab(labId, {
          equipment: {
            ...lab.equipment,
            tanks: updatedTanks
          }
        });
      },

      updateBoxGridConfig: (labId: string, tankId: string, rackId: string, boxId: string, gridConfig: GridConfiguration) => {
        get().updateBox(labId, tankId, rackId, boxId, { gridConfig });
      },

      getAvailableGridTemplates: () => GRID_TEMPLATES,

      getCurrentTanks: () => {
        const state = get();
        const currentLab = state.currentLab || DEFAULT_LAB_CONFIG;
        const tanks = currentLab.equipment?.tanks || [];

        return tanks;
      },

      getCurrentRacks: (tankId?: string) => {
        const state = get();
        const currentLab = state.currentLab || DEFAULT_LAB_CONFIG;
        const equipment = currentLab.equipment;
        const tanks = equipment?.tanks || [];
        
        if (!tankId) {
          // Return all racks from all tanks for backwards compatibility
          const allRacks = tanks.flatMap(tank => tank.racks || []);

          return allRacks;
        }
        
        const tank = tanks.find(t => t.id === tankId);
        const racks = tank?.racks ?? [];

        return racks;
      },

      getCurrentBoxes: (tankId: string, rackId: string) => {
        const state = get();
        const currentLab = state.currentLab || DEFAULT_LAB_CONFIG;
        const equipment = currentLab.equipment;
        const tanks = equipment.tanks || [];
        const tank = tanks.find(t => t.id === tankId);
        const rack = tank?.racks?.find(r => r.id === rackId);
        return rack?.boxes ?? [];
      },

      getBox: (tankId: string, rackId: string, boxId: string) => {
        const equipment = get().currentLab.equipment;
        const tanks = equipment.tanks || [];
        const tank = tanks.find(t => t.id === tankId);
        const rack = tank?.racks?.find(r => r.id === rackId);
        const box = rack?.boxes?.find(b => b.id === boxId);
        return box;
      },

      getBoxPositionDisplay: (tankId: string, rackId: string, boxId: string) => {
        const equipment = get().currentLab.equipment;
        const tanks = equipment.tanks || [];
        const tank = tanks.find(t => t.id === tankId);
        const rack = tank?.racks?.find(r => r.id === rackId);
        const box = rack?.boxes?.find(b => b.id === boxId);
        return box?.positionDisplay;
      },

      resetToDefaults: () => {
        syncedSet({
          systemConfig: createDefaultSystemConfig()
        });
        // currentLab automatically synced
      },

      // Server synchronization methods (DEPRECATED - use React Query hooks)
      loadFromServer: async () => {
        // eslint-disable-next-line no-console -- Warning logging for production monitoring
        console.warn('⚠️ ConfigurationStore.loadFromServer() is deprecated. Use useLoadConfigurationQuery() hook instead.');
        
        // Fallback to ensure defaults for legacy compatibility
        get().ensureDefaultConfiguration();
      },

      // Ensure we have a valid default configuration
      ensureDefaultConfiguration: () => {
        const { systemConfig } = get();
        const currentLab = get().currentLab; // Access via getter

        // If current lab doesn't have tanks structure, fix it
        if (!currentLab.equipment.tanks) {

          // Check if we have existing racks to migrate
          const existingRacks = (currentLab.equipment as any)?.racks;

          const tanks = existingRacks ? [
            {
              id: NAMING_PATTERNS.TANK.ID_PATTERN(1),
              name: NAMING_PATTERNS.TANK.DEFAULT_NAME(1),
              location: NAMING_PATTERNS.TANK.DEFAULT_LOCATION,
              isActive: true,
              createdAt: new Date().toISOString(),
              updatedAt: new Date().toISOString(),
              defaultGridConfig: DEFAULT_GRID_CONFIG,
              racks: existingRacks // Use existing racks
            }
          ] : [
            {
              id: NAMING_PATTERNS.TANK.ID_PATTERN(1),
              name: NAMING_PATTERNS.TANK.DEFAULT_NAME(1),
              location: NAMING_PATTERNS.TANK.DEFAULT_LOCATION,
              isActive: true,
              createdAt: new Date().toISOString(),
              updatedAt: new Date().toISOString(),
              defaultGridConfig: DEFAULT_GRID_CONFIG,
              racks: [
                {
                  id: 1,
                  name: NAMING_PATTERNS.RACK.DEFAULT_NAME(1),
                  capacity: EQUIPMENT_DEFAULTS.BOXES_PER_RACK,
                  location: NAMING_PATTERNS.TANK.DEFAULT_LOCATION,
                  isActive: true,
                  boxes: Array.from({ length: EQUIPMENT_DEFAULTS.BOXES_PER_RACK }, (_, i) => ({
                    id: NAMING_PATTERNS.BOX.LETTER_NAME(i),
                    name: NAMING_PATTERNS.BOX.DEFAULT_NAME(i),
                    gridConfig: DEFAULT_GRID_CONFIG,
                    position: i + 1
                  }))
                }
              ]
            }
          ];

          const updatedLab = {
            ...currentLab,
            equipment: {
              ...currentLab.equipment,
              tanks
            }
          };

          // Remove old racks property if it exists
          if ((updatedLab.equipment as any).racks) {
            delete (updatedLab.equipment as any).racks;
          }

          // Update in availableLabs (single source of truth)
          const updatedAvailableLabs = systemConfig.availableLabs.map(lab =>
            lab.id === currentLab.id ? updatedLab : lab
          );

          syncedSet({
            systemConfig: {
              ...systemConfig,
              availableLabs: updatedAvailableLabs
            }
          });
          // currentLab automatically synced
        }
      },

      // Migration helper to convert old racks structure to tanks structure
      migrateConfigurationStructure: (config: any) => {
        if (config.currentLab?.equipment?.racks && !config.currentLab?.equipment?.tanks) {


          // Create a default tank with the existing racks
          const defaultTank = {
            id: NAMING_PATTERNS.TANK.ID_PATTERN(1),
            name: NAMING_PATTERNS.TANK.DEFAULT_NAME(1),
            location: NAMING_PATTERNS.TANK.DEFAULT_LOCATION,
            isActive: true,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
            defaultGridConfig: DEFAULT_GRID_CONFIG,
            racks: config.currentLab.equipment.racks
          };

          // Update the structure
          config.currentLab.equipment.tanks = [defaultTank];
          delete config.currentLab.equipment.racks; // Remove old structure


        }
        return config;
      },

      saveToServer: async () => {
        // eslint-disable-next-line no-console -- Warning logging for production monitoring
        console.warn('⚠️ ConfigurationStore.saveToServer() is deprecated. Use useSaveConfigurationMutation() hook instead.');
        
        // This method is now deprecated in favor of React Query mutations
        // Components should use useSaveConfigurationMutation() for consistent error handling and cache management
      },
      
      // Initialize and migrate data structure
      initialize: () => {
        get().ensureDefaultConfiguration();
      }
    };
  },
    {
      name: 'odysseus-configuration-store',
      version: 2, // Bumped version to trigger migration
      migrate: (persistedState: any, version: number) => {
        // Migrate from version 1 to version 2 (grid schema changes)
        if (version < 2) {
          const state = persistedState as any;

          // Migrate all grid configurations in the stored state
          if (state.currentLab?.equipment?.tanks) {
            state.currentLab.equipment.tanks = state.currentLab.equipment.tanks.map((tank: any) => ({
              ...tank,
              defaultGridConfig: migrateGridConfig(tank.defaultGridConfig),
              racks: tank.racks?.map((rack: any) => ({
                ...rack,
                boxes: rack.boxes?.map((box: any) => ({
                  ...box,
                  gridConfig: migrateGridConfig(box.gridConfig)
                }))
              }))
            }));
          }

          // Migrate default grid configs
          if (state.currentLab?.equipment?.defaultGridConfig) {
            state.currentLab.equipment.defaultGridConfig = migrateGridConfig(state.currentLab.equipment.defaultGridConfig);
          }

          if (state.currentLab?.equipment?.defaultBoxConfig?.gridConfig) {
            state.currentLab.equipment.defaultBoxConfig.gridConfig = migrateGridConfig(state.currentLab.equipment.defaultBoxConfig.gridConfig);
          }

          // Migrate all labs in systemConfig
          if (state.systemConfig?.availableLabs) {
            state.systemConfig.availableLabs = state.systemConfig.availableLabs.map((lab: any) => {
              if (!lab.equipment?.tanks) return lab;

              return {
                ...lab,
                equipment: {
                  ...lab.equipment,
                  defaultGridConfig: migrateGridConfig(lab.equipment.defaultGridConfig),
                  defaultBoxConfig: lab.equipment.defaultBoxConfig ? {
                    ...lab.equipment.defaultBoxConfig,
                    gridConfig: migrateGridConfig(lab.equipment.defaultBoxConfig.gridConfig)
                  } : undefined,
                  tanks: lab.equipment.tanks.map((tank: any) => ({
                    ...tank,
                    defaultGridConfig: migrateGridConfig(tank.defaultGridConfig),
                    racks: tank.racks?.map((rack: any) => ({
                      ...rack,
                      boxes: rack.boxes?.map((box: any) => ({
                        ...box,
                        gridConfig: migrateGridConfig(box.gridConfig)
                      }))
                    }))
                  }))
                }
              };
            });
          }
        }

        return persistedState;
      },
    }
  )
);

// Utility hooks for common operations
export const useCurrentLab = () => {
  const currentLab = useStorageStore(state => state.currentLab);
  return currentLab;
};

export const useCurrentTanks = () => {
  const getCurrentTanks = useStorageStore(state => state.getCurrentTanks);
  return getCurrentTanks();
};

export const useCurrentRacks = (tankId?: string) => {
  const getCurrentRacks = useStorageStore(state => state.getCurrentRacks);
  return getCurrentRacks(tankId);
};

export const useCurrentBoxes = (tankId: string, rackId: string) => {
  const getCurrentBoxes = useStorageStore(state => state.getCurrentBoxes);
  return getCurrentBoxes(tankId, rackId);
};

export const useGridTemplates = () => {
  const getAvailableGridTemplates = useStorageStore(state => state.getAvailableGridTemplates);
  return getAvailableGridTemplates();
};

/**
 * Tube Form Hook - Generic Factory Pattern
 *
 * Generic factory pattern for tube forms:
 * - Private generic implementation contains all logic (DRY)
 * - Public type-safe wrappers provide domain-specific APIs
 * - Full type safety with Zod input/output types
 *
 * Type Flow:
 * 1. User interacts with form → TInput (CreateTubeFormInput: concentration as string)
 * 2. Form submits → Zod validates and transforms → TOutput (CreateTubeRequest: concentration as number)
 * 3. API receives proper output type
 */

import { useCallback } from 'react';

import { zodResolver } from '@hookform/resolvers/zod';
import {
  createTubeRequestSchema,
  updateTubeRequestSchema,
  type CreateTubeRequest,
  type UpdateTubeRequest,
  type CreateTubeFormInput,
  type UpdateTubeFormInput,
  type TubeData
} from '@odysseus/shared-schemas';
import { useQueryClient } from '@tanstack/react-query';
import { useForm } from 'react-hook-form';

import { queryKeys } from '@app/queryKeys';

import {
  useCreateTubeMutation,
  useUpdateTubeMutation
} from './useTubeMutations';

import type { UseFormReturn, FieldValues } from 'react-hook-form';
import type { ZodType } from 'zod';

/**
 * Submit context for providing non-editable external data (e.g., location from grid selection)
 */
export interface SubmitContext {
  location?: TubeData['location'];
}

/**
 * Form submission result
 */
export interface TubeFormSubmissionResult {
  success: boolean;
  data?: TubeData;
  error?: string;
}

// PRIVATE GENERIC IMPLEMENTATION

/**
 * Generic tube form hook - private implementation
 *
 * Contains all form logic. Not exported directly.
 * Public wrappers (useCreateTubeForm, useEditTubeForm) provide type-safe APIs.
 *
 * @template TInput - Form input type (pre-Zod transformation, must be valid form values)
 * @template TOutput - API output type (post-Zod transformation)
 */
function useTubeForm<TInput extends FieldValues, TOutput extends CreateTubeRequest | UpdateTubeRequest>(
  schema: ZodType<TOutput>,
  config: {
    mode: 'create' | 'edit';
    tubeId?: string;
    initialData?: Partial<TInput>;
    onSuccess?: (data: TubeData) => void;
    onError?: (error: Error) => void;
  }
): {
  form: UseFormReturn<TInput>;
  submitTube: (data: TInput, ctx?: SubmitContext) => Promise<TubeFormSubmissionResult>;
  isSubmitting: boolean;
  submitError: Error | null;
} {
  const { mode, tubeId, initialData, onSuccess, onError } = config;
  const queryClient = useQueryClient();

  // React Hook Form with Zod validation
  // Type assertion needed for generic factory pattern - type safety enforced at public wrappers
  const form = useForm<TInput>({
    resolver: zodResolver(schema as any),
    defaultValues: initialData as any,
    mode: 'onChange' // Real-time validation for immediate feedback
  });

  // React Query mutations
  const createTubeMutation = useCreateTubeMutation();
  const updateTubeMutation = useUpdateTubeMutation();

  /**
   * Validate complete payload with business rules (duplicate position, warnings)
   *
   * @param payload - Validated payload (post-transformation)
   */
  const validateCompletePayload = useCallback((payload: TOutput): { warnings: Record<string, string> } => {
    const warnings: Record<string, string> = {};

    // Warning: Duplicate position check (only if we have location)
    if ('location' in payload && payload.location) {
      // Get existing tubes for duplicate validation (fresh on every validation)
      const existingTubes = queryClient.getQueryData<TubeData[]>(queryKeys.tubes.all) ?? [];

      const filteredTubes = mode === 'edit' && tubeId
        ? existingTubes.filter(tube => tube.id !== tubeId)
        : existingTubes;

      const duplicate = filteredTubes.find(tube =>
        tube.location.tankId === payload.location!.tankId &&
        tube.location.rackId === payload.location!.rackId &&
        tube.location.boxId === payload.location!.boxId &&
        tube.location.position === payload.location!.position
      );

      if (duplicate) {
        warnings['position'] = `Position ${payload.location!.position} in Tank ${payload.location!.tankId}, Rack ${payload.location!.rackId}, Box ${payload.location!.boxId} is already occupied`;
      }
    }

    return { warnings };
  }, [queryClient, mode, tubeId]);

  /**
   * Form submission handler with context support
   *
   * Proper type transformation:
   * - Form data is INPUT type (pre-transformation: concentration is string)
   * - Zod validates and transforms: INPUT → OUTPUT type
   * - Mutation receives OUTPUT type (post-transformation: concentration is number)
   */
  const submitTube = useCallback(async (data: TInput, ctx?: SubmitContext): Promise<TubeFormSubmissionResult> => {
    try {
      let result: TubeData;

      if (mode === 'create') {
        if (!ctx?.location) {
          throw new Error('Location is required for create mode');
        }

        // Merge form data with context location
        const formInputWithLocation = {
          ...data,
          location: ctx.location
        };

        // Zod validates and transforms INPUT → OUTPUT
        // Input: concentration as string ("1.5e6")
        // Output: concentration as number (1500000)
        const validatedPayload = schema.parse(formInputWithLocation) as TOutput;

        // Validate complete payload and show warnings (non-blocking)
        const { warnings } = validateCompletePayload(validatedPayload);
        if (Object.keys(warnings).length > 0) {
          // eslint-disable-next-line no-console -- Warning logging for production monitoring
          console.warn('Tube creation warnings:', warnings);
        }

        // Type assertion: we know TOutput is CreateTubeRequest when mode === 'create'
        result = await createTubeMutation.mutateAsync(validatedPayload as CreateTubeRequest);

      } else {
        if (!tubeId) {
          throw new Error('Tube ID is required for edit mode');
        }

        // Merge form data with optional context location
        const formInputWithContext = {
          ...data,
          ...(ctx?.location && { location: ctx.location })
        };

        // Zod validates and transforms INPUT → OUTPUT
        const validatedPayload = schema.parse(formInputWithContext) as TOutput;

        // Validate complete payload and show warnings (non-blocking)
        const { warnings } = validateCompletePayload(validatedPayload);
        if (Object.keys(warnings).length > 0) {
          // eslint-disable-next-line no-console -- Warning logging for production monitoring
          console.warn('Tube update warnings:', warnings);
        }

        // Type assertion: we know TOutput is UpdateTubeRequest when mode === 'edit'
        result = await updateTubeMutation.mutateAsync({
          id: tubeId,
          updates: validatedPayload as UpdateTubeRequest
        });
      }

      // Call success callback
      onSuccess?.(result);

      return {
        success: true,
        data: result
      };

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'An unexpected error occurred';
      onError?.(error instanceof Error ? error : new Error(errorMessage));

      return {
        success: false,
        error: errorMessage
      };
    }
  }, [
    mode,
    tubeId,
    createTubeMutation,
    updateTubeMutation,
    validateCompletePayload,
    schema,
    onSuccess,
    onError
  ]);

  // Loading state
  const isSubmitting = createTubeMutation.isPending || updateTubeMutation.isPending;

  // Error state
  // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Cascading fallback chain, empty string should trigger next option
  const submitError = createTubeMutation.error || updateTubeMutation.error;

  return {
    form,          // Pure React Hook Form instance
    submitTube,    // Custom async submission logic
    isSubmitting,  // Combined loading state
    submitError    // Combined error state
  };
}

// PUBLIC TYPE-SAFE WRAPPERS

/**
 * Hook for tube creation
 *
 * Type-safe wrapper around generic implementation:
 * - Form uses CreateTubeFormInput (pre-transformation)
 * - Enforces location requirement at submit time
 */
export function useCreateTubeForm(config?: {
  initialData?: Partial<CreateTubeFormInput>;
  onSuccess?: (data: TubeData) => void;
  onError?: (error: Error) => void;
}): {
  form: UseFormReturn<CreateTubeFormInput>;
  submitTube: (data: CreateTubeFormInput, location: TubeData['location']) => Promise<TubeFormSubmissionResult>;
  isSubmitting: boolean;
  submitError: Error | null;
} {
  const base = useTubeForm<CreateTubeFormInput, CreateTubeRequest>(
    createTubeRequestSchema,
    {
      mode: 'create',
      ...config
    }
  );

  // Wrapper: location is required parameter
  const submitTube = useCallback(
    (data: CreateTubeFormInput, location: TubeData['location']) =>
      base.submitTube(data, { location }),
    [base]
  );

  return {
    form: base.form,
    submitTube,
    isSubmitting: base.isSubmitting,
    submitError: base.submitError
  };
}

/**
 * Hook for tube editing
 *
 * Type-safe wrapper around generic implementation:
 * - Form uses UpdateTubeFormInput (pre-transformation)
 * - Location optional (preserves existing if not provided)
 */
export function useEditTubeForm(
  tubeId: string,
  config?: {
    initialData?: Partial<UpdateTubeFormInput>;
    onSuccess?: (data: TubeData) => void;
    onError?: (error: Error) => void;
  }
): {
  form: UseFormReturn<UpdateTubeFormInput>;
  submitTube: (data: UpdateTubeFormInput, ctx?: SubmitContext) => Promise<TubeFormSubmissionResult>;
  isSubmitting: boolean;
  submitError: Error | null;
} {
  return useTubeForm<UpdateTubeFormInput, UpdateTubeRequest>(
    updateTubeRequestSchema,
    {
      mode: 'edit',
      tubeId,
      ...config
    }
  );
}

// UTILITY HOOKS

/**
 * Hook for transforming TubeData to form format (for edit mode)
 * Converts domain data to form-ready structure
 *
 * Returns FORM INPUT type (pre-transformation)
 */
export function useTubeFormTransform() {
  const transformToFormData = useCallback((tubeData: TubeData): Partial<CreateTubeFormInput> => {
    return {
      sample: {
        cellType: tubeData.sample.cellType,
        donorInternalId: tubeData.sample.donorInternalId ?? '',
        donorSourceId: tubeData.sample.donorSourceId ?? '',
        concentration: tubeData.sample.concentration,
        concentrationUnit: tubeData.sample.concentrationUnit,
        date: tubeData.sample.date ?? '',
        media: {
          type: tubeData.sample.media?.type ?? '',
          supplements: tubeData.sample.media?.supplements ?? '',
          selection: tubeData.sample.media?.selection ?? ''
        },
        cultureCondition: tubeData.sample.cultureCondition ?? '',
        lotNumber: tubeData.sample.lotNumber ?? '',
        notes: tubeData.sample.notes ?? ''
      },
      researcherId: tubeData.researcherId
    };
  }, []);

  return {
    transformToFormData
  };
}

