/**
 * Tube Query Hooks
 *
 * React Query hooks for tube read operations.
 *
 * - Uses TubeService
 * - Type-safe with centralized query keys
 * - Smart caching and background refresh
 * - Consistent error handling and loading states
 */

import { 
  useQuery, 
  useInfiniteQuery,
  useQueryClient,
  type UseQueryOptions,
  type UseInfiniteQueryOptions
} from '@tanstack/react-query';

import { queryKeys } from '@app/queryKeys';
import { TubeService } from '@domains/tubes/services/TubeService';

import type { TubeData } from '@domains/tubes/types';

// QUERY HOOKS (READ OPERATIONS)

/**
 * Get all tubes with optional filtering
 *
 * Uses canonical base query with client-side filtering via select
 * Replaces: tubeStore.loadTubes()
 */
export const useTubes = (
  filters: {
    tankId?: string;
    rackId?: string;
    boxId?: string;
    searchTerm?: string;
  } = {},
  options: Omit<UseQueryOptions<TubeData[], Error, TubeData[]>, 'queryKey' | 'queryFn' | 'select'> = {}
) => {
  return useQuery<TubeData[], Error, TubeData[]>({
    queryKey: queryKeys.tubes.lists(),
    queryFn: async (): Promise<TubeData[]> => {
      return await TubeService.fetchTubes() as TubeData[];
    },
    select: (tubes: TubeData[]): TubeData[] => {
      let filtered = tubes;
      
      if (filters.tankId) {
        filtered = filtered.filter(tube => tube.location.tankId === filters.tankId);
      }
      
      if (filters.rackId !== undefined) {
        filtered = filtered.filter(tube => tube.location.rackId === filters.rackId);
      }
      
      if (filters.boxId) {
        filtered = filtered.filter(tube => tube.location.boxId === filters.boxId);
      }
      
      if (filters.searchTerm) {
        const searchLower = filters.searchTerm.toLowerCase();
        filtered = filtered.filter(tube =>
          // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Boolean OR logic for multi-field search
          tube.sample.cellType?.toLowerCase().includes(searchLower) ||
          // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Boolean OR logic for multi-field search
          tube.sample.donorInternalId?.toLowerCase().includes(searchLower) ||
          // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Boolean OR logic for multi-field search
          tube.sample.donorSourceId?.toLowerCase().includes(searchLower) ||
          tube.sample.notes?.toLowerCase().includes(searchLower)
        );
      }
      
      return filtered;
    },
    staleTime: 5 * 60 * 1000,
    gcTime: 10 * 60 * 1000,
    ...options
  });
};

/**
 * Get tubes by specific location (tank/rack/box)
 * 
 * Replaces: tubeStore.loadTubesForLocation()
 */
export const useTubesByLocation = (
  tankId: string,
  rackId: string,  boxId: string,  options: Omit<UseQueryOptions<TubeData[]>, 'queryKey' | 'queryFn'> = {}
) => {
  return useQuery({
    queryKey: queryKeys.tubes.location(tankId, rackId, boxId),
    queryFn: async (): Promise<TubeData[]> => {
      return await TubeService.fetchTubesByLocation(tankId, rackId, boxId);
    },
    enabled: !!(tankId && rackId && boxId), // Only run if all params provided
    staleTime: 5 * 60 * 1000, // 5 minutes - WebSocket keeps data fresh
    gcTime: 10 * 60 * 1000,
    ...options
  });
};

/**
 * Get single tube by ID
 * 
 * New functionality - enables individual tube queries
 */
export const useTube = (
  id: string,
  options: Omit<UseQueryOptions<TubeData>, 'queryKey' | 'queryFn'> = {}
) => {
  return useQuery({
    queryKey: queryKeys.tubes.detail(id),
    queryFn: async (): Promise<TubeData> => {
      return await TubeService.fetchTubeById(id);
    },
    enabled: !!id, // Only run if ID provided
    staleTime: 5 * 60 * 1000,
    gcTime: 15 * 60 * 1000, // Individual tubes cached longer
    ...options
  });
};

/**
 * Get tubes with infinite scrolling for large datasets
 * 
 * Replaces: tubeStore.loadMoreTubes() pagination logic
 */
export const useInfiniteTubes = (
  filters: {
    tankId?: string;
    rackId?: string;    boxId?: string;    searchTerm?: string;
  } = {},
  options: Omit<UseInfiniteQueryOptions<any, Error, any, any, number>, 'queryKey' | 'queryFn' | 'getNextPageParam' | 'initialPageParam'> = {}
) => {
  return useInfiniteQuery({
    queryKey: queryKeys.tubes.paginated(filters),
    queryFn: async ({ pageParam }: { pageParam: number }) => {
      let tubes = await TubeService.fetchTubes();
      
      // Apply client-side filtering
      if (filters.tankId) {
        tubes = tubes.filter(tube => tube.location.tankId === filters.tankId);
      }
      
      if (filters.rackId !== undefined) {
        tubes = tubes.filter(tube => tube.location.rackId === filters.rackId);
      }
      
      if (filters.boxId) {
        tubes = tubes.filter(tube => tube.location.boxId === filters.boxId);
      }
      
      if (filters.searchTerm) {
        const searchLower = filters.searchTerm.toLowerCase();
        tubes = tubes.filter(tube =>
          // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Boolean OR logic for multi-field search
          tube.sample.cellType?.toLowerCase().includes(searchLower) ||
          // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Boolean OR logic for multi-field search
          tube.sample.donorInternalId?.toLowerCase().includes(searchLower) ||
          // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Boolean OR logic for multi-field search
          tube.sample.donorSourceId?.toLowerCase().includes(searchLower) ||
          tube.sample.notes?.toLowerCase().includes(searchLower)
        );
      }

      const hasMore = tubes.length === 50; // Client-side pagination

      return {
        tubes,
        nextOffset: hasMore ? pageParam + 50 : undefined,
        hasMore
      };
    },
    getNextPageParam: (lastPage) => lastPage.nextOffset,
    initialPageParam: 0,
    staleTime: 5 * 60 * 1000,
    gcTime: 10 * 60 * 1000,
    ...options
  });
};

/**
 * Search tubes with advanced filtering
 * 
 * New functionality - dedicated search queries
 */
export const useSearchTubes = (
  query: string,
  filters: Record<string, any> = {},
  options: Omit<UseQueryOptions<TubeData[]>, 'queryKey' | 'queryFn'> = {}
) => {
  return useQuery({
    queryKey: queryKeys.search.results(query, filters),
    queryFn: async (): Promise<TubeData[]> => {
      return await TubeService.searchTubes(query, { limit: 100, offset: 0 });
    },
    enabled: !!query && query.length >= 2, // Only search with 2+ characters
    staleTime: 2 * 60 * 1000, // Search results stale faster
    gcTime: 5 * 60 * 1000,
    ...options
  });
};

/**
 * Get bulk tubes by IDs
 * 
 * Used by bulk operations and multi-select scenarios
 */
export const useBulkTubes = (
  tubeIds: string[],
  options: Omit<UseQueryOptions<TubeData[]>, 'queryKey' | 'queryFn'> = {}
) => {
  return useQuery({
    queryKey: ['tubes', 'bulk', { tubeIds: tubeIds.sort(), length: tubeIds.length }],
    queryFn: async (): Promise<TubeData[]> => {
      if (tubeIds.length === 0) {
        return [];
      }

      // Fetch all tubes in parallel
      const tubes = await Promise.all(
        tubeIds.map(id => TubeService.fetchTubeById(id))
      );
      return tubes;
    },
    enabled: tubeIds.length > 0,
    staleTime: 5 * 60 * 1000,
    gcTime: 10 * 60 * 1000,
    ...options
  });
};

// UTILITY HOOKS

/**
 * Prefetch tubes for a location (for smooth navigation)
 * 
 * Replaces: Manual cache warming in navigation
 */
export const usePrefetchTubeLocation = () => {
  const queryClient = useQueryClient();
  
  const prefetchLocation = async (tankId: string, rackId: string, boxId: string) => {
    await queryClient.prefetchQuery({
      queryKey: queryKeys.tubes.location(tankId, rackId, boxId),
      queryFn: async () => {
        return await TubeService.fetchTubesByLocation(tankId, rackId, boxId);
      },
      staleTime: 2 * 60 * 1000
    });
  };
  
  return { prefetchLocation };
};

/**
 * Get tube statistics and aggregations
 * 
 * New functionality - analytics queries
 */
export const useTubeStats = (
  tankId?: string,
  rackId?: string,  boxId?: string,  options: Omit<UseQueryOptions<any>, 'queryKey' | 'queryFn'> = {}
) => {
  return useQuery({
    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Empty string IDs are invalid, use 'all' for aggregated queries
    queryKey: [...queryKeys.tubes.locationStats(tankId || 'all', rackId || 'all'), boxId || 'all'],
    queryFn: async () => {
      // Get all tubes for statistics
      let tubes = await TubeService.fetchTubes();
      
      // Filter by location if specified
      if (tankId && tankId !== 'all') {
        tubes = tubes.filter(tube => tube.location.tankId === tankId);
      }
      if (rackId !== undefined) {
        tubes = tubes.filter(tube => tube.location.rackId === rackId);
      }
      if (boxId) {
        tubes = tubes.filter(tube => tube.location.boxId === boxId);
      }
      
      // Calculate statistics
      const stats = {
        total: tubes.length,
        byTank: {} as Record<string, number>,
        byRack: {} as Record<string, number>,
        byBox: {} as Record<string, number>,
        byResearcher: {} as Record<string, number>,
        byCellType: {} as Record<string, number>,
        emptyPositions: 0,
        occupiedPositions: tubes.length
      };
      
      tubes.forEach(tube => {
        // Tank statistics
        stats.byTank[tube.location.tankId] = (stats.byTank[tube.location.tankId] || 0) + 1;
        
        // Rack statistics
        stats.byRack[tube.location.rackId] = (stats.byRack[tube.location.rackId] || 0) + 1;
        
        // Box statistics
        stats.byBox[tube.location.boxId] = (stats.byBox[tube.location.boxId] || 0) + 1;
        
        // Researcher statistics
        if (tube.researcherId) {
          stats.byResearcher[tube.researcherId] = (stats.byResearcher[tube.researcherId] || 0) + 1;
        }
        
        // Cell type statistics
        if (tube.sample.cellType) {
          stats.byCellType[tube.sample.cellType] = (stats.byCellType[tube.sample.cellType] || 0) + 1;
        }
      });

      return stats;
    },
    staleTime: 10 * 60 * 1000, // Statistics stale slower (10 minutes)
    gcTime: 30 * 60 * 1000,   // Keep stats longer in cache
    ...options
  });
};

/**
 * Tube Socket Integration
 *
 * Socket.IO integration with React Query cache invalidation.
 *
 * - Bridges real-time updates with React Query cache
 * - Smart cache invalidation based on socket events
 * - Optimistic updates with server reconciliation
 * - Connection management with proper cleanup
 */

import { useEffect, useCallback } from 'react';

import { useQueryClient } from '@tanstack/react-query';
import { io } from 'socket.io-client';

import { queryKeys } from '@app/queryKeys';

import type { TubeData } from '@domains/tubes/types';
import type { Socket } from 'socket.io-client';




/**
 * Socket connection manager hook
 * 
 * Manages socket connection and integrates with React Query cache
 */
export const useTubeSocket = () => {
  const queryClient = useQueryClient();

  // Socket connection management
  const initializeSocket = useCallback(() => {
    // eslint-disable-next-line no-console -- Info logging for operational visibility
    console.log('🔌 [Socket] Initializing socket connection');
    
    // Create socket connection
    const socket = io('http://localhost:3001');
    
    // CONNECTION EVENTS
    
    socket.on('connect', () => {
      // eslint-disable-next-line no-console -- Info logging for operational visibility
      console.log('[Socket] Connected to server');
      // Note: Connection notifications handled by SocketQueryBridge to avoid duplicates
    });

    socket.on('disconnect', (reason) => {
      // eslint-disable-next-line no-console -- Info logging for operational visibility
      console.log('❌ [Socket] Disconnected from server:', reason);
      // Note: Disconnection notifications handled by SocketQueryBridge to avoid duplicates
    });

    socket.on('connect_error', (error) => {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('❌ [Socket] Connection error:', error);
      // Note: Connection error notifications handled by SocketQueryBridge to avoid duplicates
    });

    // TUBE DATA EVENTS

    /**
     * Handle tube creation events
     * 
     * Replaces: tubeStore socket handler for tube_created
     */
    socket.on('tube_created', ({ tube }: { tube: TubeData }) => {
      // eslint-disable-next-line no-console -- Info logging for operational visibility
      console.log('🔄 [Socket] Tube created event received:', tube.id);
      
      // Add to individual tube cache immediately
      queryClient.setQueryData(queryKeys.tubes.detail(tube.id), tube);
      
      // Add to existing list queries if they exist
      queryClient.setQueriesData(
        { queryKey: queryKeys.tubes.lists() },
        (oldData: TubeData[] | undefined) => {
          if (!oldData) return undefined; // Don't create new data, just update existing
          
          // Check if tube already exists (avoid duplicates)
          const exists = oldData.some(existingTube => existingTube.id === tube.id);
          if (exists) {
            // eslint-disable-next-line no-console -- Info logging for operational visibility
            console.log('⚠️ [Socket] Tube already exists in cache, skipping add');
            return oldData;
          }
          
          // eslint-disable-next-line no-console -- Info logging for operational visibility
          console.log('[Socket] Adding new tube to cache');
          return [...oldData, tube];
        }
      );
      
      // Update location-specific queries
      if (tube.location.tankId && tube.location.rackId !== undefined && tube.location.boxId) {
        queryClient.setQueryData(
          queryKeys.tubes.location(tube.location.tankId, tube.location.rackId, tube.location.boxId),
          (oldData: TubeData[] | undefined) => {
            if (!oldData) return undefined;
            
            const exists = oldData.some(existingTube => existingTube.id === tube.id);
            if (!exists) {
              return [...oldData, tube];
            }
            return oldData;
          }
        );
      }

      // Invalidate statistics
      void queryClient.invalidateQueries({ queryKey: queryKeys.tubes.stats() });
    });

    /**
     * Handle tube update events
     * 
     * Replaces: tubeStore socket handler for tube_updated
     */
    socket.on('tube_updated', ({ tube }: { tube: TubeData }) => {
      // eslint-disable-next-line no-console -- Info logging for operational visibility
      console.log('🔄 [Socket] Tube updated event received:', tube.id);
      
      // Update individual tube cache
      queryClient.setQueryData(queryKeys.tubes.detail(tube.id), tube);
      
      // Update in all list queries
      queryClient.setQueriesData(
        { queryKey: queryKeys.tubes.lists() },
        (oldData: TubeData[] | undefined) => {
          if (!oldData) return undefined;
          
          return oldData.map(existingTube => 
            existingTube.id === tube.id ? tube : existingTube
          );
        }
      );
      
      // Update location-specific queries
      if (tube.location.tankId && tube.location.rackId !== undefined && tube.location.boxId) {
        queryClient.setQueryData(
          queryKeys.tubes.location(tube.location.tankId, tube.location.rackId, tube.location.boxId),
          (oldData: TubeData[] | undefined) => {
            if (!oldData) return undefined;
            
            return oldData.map(existingTube => 
              existingTube.id === tube.id ? tube : existingTube
            );
          }
        );
      }

      // Invalidate statistics (tube properties might have changed)
      void queryClient.invalidateQueries({ queryKey: queryKeys.tubes.stats() });

      // eslint-disable-next-line no-console -- Info logging for operational visibility
      console.log('[Socket] Tube update applied to cache');
    });

    /**
     * Handle tube deletion events
     * 
     * Replaces: tubeStore socket handler for tube_deleted
     */
    socket.on('tube_deleted', ({ tubeId }: { tubeId: string }) => {
      // eslint-disable-next-line no-console -- Info logging for operational visibility
      console.log('🔄 [Socket] Tube deleted event received:', tubeId);
      
      // Remove from individual tube cache
      queryClient.removeQueries({ queryKey: queryKeys.tubes.detail(tubeId) });
      
      // Remove from all list queries
      queryClient.setQueriesData(
        { queryKey: queryKeys.tubes.lists() },
        (oldData: TubeData[] | undefined) => {
          if (!oldData) return undefined;
          
          return oldData.filter(tube => tube.id !== tubeId);
        }
      );
      
      // Remove from location queries (we don't know which location, so invalidate all)
      void queryClient.invalidateQueries({
        queryKey: queryKeys.tubes.lists(),
        predicate: (query) => {
          const key = query.queryKey as string[];
          return key[0] === 'tubes' && key[1] === 'list' && key[2] === 'location';
        }
      });

      // Invalidate statistics
      void queryClient.invalidateQueries({ queryKey: queryKeys.tubes.stats() });
      
      // eslint-disable-next-line no-console -- Info logging for operational visibility
      console.log('[Socket] Tube deletion applied to cache');
    });

    /**
     * Handle bulk tube update events
     * 
     * Replaces: tubeStore socket handler for tubes_bulk_updated
     */
    socket.on('tubes_bulk_updated', ({ tubes }: { tubes: TubeData[] }) => {
      // eslint-disable-next-line no-console -- Info logging for operational visibility
      console.log(`🔄 [Socket] Bulk update event received: ${tubes.length} tubes`);
      
      tubes.forEach(tube => {
        // Update individual tube caches
        queryClient.setQueryData(queryKeys.tubes.detail(tube.id), tube);
      });
      
      // Update all list queries
      queryClient.setQueriesData(
        { queryKey: queryKeys.tubes.lists() },
        (oldData: TubeData[] | undefined) => {
          if (!oldData) return undefined;
          
          const updatedData = [...oldData];
          
          tubes.forEach(updatedTube => {
            const index = updatedData.findIndex(tube => tube.id === updatedTube.id);
            if (index !== -1) {
              updatedData[index] = updatedTube;
            }
          });
          
          return updatedData;
        }
      );
      
      // Invalidate location queries and statistics (bulk updates might affect multiple locations)
      void queryClient.invalidateQueries({
        queryKey: queryKeys.tubes.lists(),
        predicate: (query) => {
          const key = query.queryKey as string[];
          return key[0] === 'tubes' && key[1] === 'list' && key[2] === 'location';
        }
      });

      void queryClient.invalidateQueries({ queryKey: queryKeys.tubes.stats() });
      
      // eslint-disable-next-line no-console -- Info logging for operational visibility
      console.log('[Socket] Bulk update applied to cache');
    });

    // RESEARCHER EVENTS (if needed)
    
    socket.on('researcher_updated', () => {
      // eslint-disable-next-line no-console -- Info logging for operational visibility
      console.log('🔄 [Socket] Researcher data updated, invalidating related queries');

      // Invalidate researcher queries
      void queryClient.invalidateQueries({ queryKey: queryKeys.researchers.all });

      // Invalidate tube statistics (researcher data affects stats)
      void queryClient.invalidateQueries({ queryKey: queryKeys.tubes.stats() });
    });

    // CONNECTION RECOVERY
    
    socket.on('reconnect', (attemptNumber) => {
      // eslint-disable-next-line no-console -- Info logging for operational visibility
      console.log(`🔄 [Socket] Reconnected after ${attemptNumber} attempts`);

      // Invalidate all queries to refetch fresh data after reconnection
      void queryClient.invalidateQueries();

      // Note: Reconnection notifications handled by SocketQueryBridge to avoid duplicates
    });

    socket.on('reconnect_failed', () => {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('❌ [Socket] Failed to reconnect to server');
      // Note: Reconnection failure notifications handled by SocketQueryBridge to avoid duplicates
    });

    // Store socket in a way that can be accessed for cleanup
    (window as any).__odysseusSocket = socket;
    
    return socket;
  }, [queryClient]);

  // Disconnect socket
  const disconnectSocket = useCallback(() => {
    // eslint-disable-next-line no-console -- Info logging for operational visibility
    console.log('🔌 [Socket] Disconnecting socket');
    
    const socket = (window as any).__odysseusSocket as Socket;
    if (socket) {
      socket.disconnect();
      delete (window as any).__odysseusSocket;
    }
  }, []);

  // Get current socket
  const getSocket = useCallback(() => {
    return (window as any).__odysseusSocket as Socket | null;
  }, []);

  // Get connection status
  const isConnected = useCallback(() => {
    const socket = getSocket();
    return socket?.connected ?? false;
  }, [getSocket]);

  return {
    initializeSocket,
    disconnectSocket,
    getSocket,
    isConnected
  };
};

/**
 * Auto-initializing socket hook
 * 
 * Automatically manages socket lifecycle in components
 */
export const useAutoSocket = () => {
  const { initializeSocket, disconnectSocket, isConnected } = useTubeSocket();

  useEffect(() => {
    // Initialize socket on mount
    initializeSocket();

    // Cleanup on unmount
    return () => {
      disconnectSocket();
    };
  }, [initializeSocket, disconnectSocket]);

  return {
    isConnected: isConnected()
  };
};

/**
 * Socket-aware query hook
 * 
 * Provides real-time data with socket integration
 */
export const useRealtimeTubes = (
  filters: {
    tankId?: string;
    rackId?: number;
    boxId?: string;
  } = {}
) => {
  const queryClient = useQueryClient();
  const { initializeSocket } = useTubeSocket();

  useEffect(() => {
    // Ensure socket is connected for real-time updates
    initializeSocket();
  }, [initializeSocket]);

  // Return the query key for manual invalidation if needed
  return {
    queryKey: queryKeys.tubes.list(filters),
    invalidate: () => {
      void queryClient.invalidateQueries({ queryKey: queryKeys.tubes.list(filters) });
    }
  };
};

/**
 * Bulk Operations Service
 *
 * Bulk operations with progress tracking and error handling.
 */

import { httpClient } from '@infra/api/httpClient';

import type { 
  BulkUpdateItem, 
  BulkUpdateProgress, 
  BulkUpdateError,
  BulkProgressCallback,
  BulkUpdateResult
} from '@shared/types/bulkOperations';

/**
 * Bulk operations service using httpClient
 */
export class BulkOperationsService {
  private static readonly MAX_RETRIES = 3;
  private static readonly RETRY_DELAY = 1000;
  private static readonly BATCH_SIZE = 50;

  /**
   * Check if server supports bulk operations
   */
  async checkBulkOperationsSupport(): Promise<boolean> {
    try {
      const response = await httpClient.get<{ status: string }>('/health');
      return response.data.status === 'healthy';
    } catch (error) {
      // eslint-disable-next-line no-console -- Warning logging for production monitoring
      console.warn('Server health check failed, falling back to individual updates');
      return false;
    }
  }

  /**
   * Perform bulk update with progress tracking
   */
  async bulkUpdateTubes(
    updates: BulkUpdateItem[], 
    onProgress?: BulkProgressCallback
  ): Promise<BulkUpdateResult> {
    const startTime = Date.now();

    // Initialize progress
    const updateProgress = (progress: BulkUpdateProgress) => {
      onProgress?.(progress);
    };

    updateProgress({
      completed: 0,
      current: 0,
      total: updates.length,
      phase: 'preparing',
      errors: []
    });

    try {
      // Process in batches for better performance
      if (updates.length > BulkOperationsService.BATCH_SIZE) {
        return await this.processBatches(updates, onProgress, startTime);
      }

      // Single batch processing
      return await this.processSingleBatch(updates, onProgress, startTime);
      
    } catch (error) {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('Bulk update failed:', error);
      return {
        success: false,
        totalProcessed: 0,
        successCount: 0,
        successful: 0,
        failed: 1,
        errorCount: 1,
        total: updates.length,
        results: [],
        errors: [{
          itemId: 'system',
          tubeId: 'system',
          error: error instanceof Error ? error.message : 'Unknown error'
        }],
        duration: Date.now() - startTime,
        response: {
          updated: 0,
          errors: [{
            itemId: 'system',
            tubeId: 'system',
            error: error instanceof Error ? error.message : 'Unknown error'
          }]
        }
      };
    }
  }

  /**
   * Process updates in multiple batches
   */
  private async processBatches(
    updates: BulkUpdateItem[],
    onProgress?: BulkProgressCallback,
    startTime: number = Date.now()
  ): Promise<BulkUpdateResult> {
    const batches: BulkUpdateItem[][] = [];
    for (let i = 0; i < updates.length; i += BulkOperationsService.BATCH_SIZE) {
      batches.push(updates.slice(i, i + BulkOperationsService.BATCH_SIZE));
    }

    let totalUpdated = 0;
    let allErrors: BulkUpdateError[] = [];

    for (let i = 0; i < batches.length; i++) {
      const batch = batches[i];
      
      onProgress?.({
        completed: i * BulkOperationsService.BATCH_SIZE,
        current: i * BulkOperationsService.BATCH_SIZE,
        total: updates.length,
        phase: 'updating',
        errors: allErrors
      });

      const batchResult = await this.processSingleBatch(batch, onProgress);
      
      if (batchResult.response) {
        totalUpdated += batchResult.response.updated;
        allErrors = [...allErrors, ...batchResult.response.errors];
      }

      // Add delay between batches to prevent server overload
      if (i < batches.length - 1) {
        await new Promise(resolve => setTimeout(resolve, 100));
      }
    }

    return {
      success: totalUpdated > 0,
      totalProcessed: updates.length,
      successCount: totalUpdated,
      successful: totalUpdated,
      failed: allErrors.length,
      errorCount: allErrors.length,
      total: updates.length,
      results: [],
      errors: allErrors,
      duration: Date.now() - startTime,
      response: {
        updated: totalUpdated,
        errors: allErrors
      }
    };
  }

  /**
   * Process a single batch of updates
   */
  private async processSingleBatch(
    updates: BulkUpdateItem[],
    onProgress?: BulkProgressCallback,
    startTime: number = Date.now(),
    retryCount: number = 0
  ): Promise<BulkUpdateResult> {
    try {
      onProgress?.({
        completed: 0,
        current: 0,
        total: updates.length,
        phase: 'updating',
        errors: []
      });

      const response = await httpClient.put<{
        success: boolean;
        updated: number;
        total: number;
        errors: BulkUpdateError[];
        processingTime?: number;
      }>('/tubes/bulk-update', { updates });

      const result = response.data;
      
      onProgress?.({
        current: result.updated,
        total: result.total,
        completed: result.updated,
        phase: 'completing',
        errors: result.errors || []
      });

      return {
        success: result.success,
        totalProcessed: result.updated,
        successCount: result.updated,
        successful: result.updated,
        failed: result.errors?.length || 0,
        errorCount: result.errors?.length || 0,
        total: result.total || updates.length,
        results: [],
        errors: result.errors || [],
        duration: Date.now() - startTime,
        response: {
          updated: result.updated,
          errors: result.errors || []
        }
      };

    } catch (error) {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error(`Bulk update attempt ${retryCount + 1} failed:`, error);
      
      // Retry logic for transient errors
      if (retryCount < BulkOperationsService.MAX_RETRIES) {
        await new Promise(resolve => setTimeout(resolve, BulkOperationsService.RETRY_DELAY * (retryCount + 1)));
        return await this.processSingleBatch(updates, onProgress, startTime, retryCount + 1);
      }

      throw error;
    }
  }

  /**
   * Fallback to individual updates when bulk operations are not supported
   */
  async fallbackIndividualUpdates(
    updates: BulkUpdateItem[],
    tubeStore: any,
    onProgress?: BulkProgressCallback
  ): Promise<BulkUpdateResult> {
    let updated = 0;
    const errors: BulkUpdateError[] = [];

    onProgress?.({
      current: 0,
      total: updates.length,
      completed: 0,
      phase: 'preparing',
      errors: []
    });

    for (let i = 0; i < updates.length; i++) {
      const { id, data: tubeUpdates } = updates[i];
      
      try {
        const success = await tubeStore.updateTube(id, tubeUpdates, '');
        
        if (success) {
          updated++;
        } else {
          errors.push({
            itemId: id,
            tubeId: id,
            error: 'Update failed'
          });
        }
      } catch (error) {
        errors.push({
          itemId: id,
          tubeId: id,
          error: error instanceof Error ? error.message : 'Unknown error'
        });
      }

      // Update progress
      onProgress?.({
        current: i + 1,
        total: updates.length,
        completed: updated,
        phase: 'updating',
        errors: errors
      });

      // Small delay to prevent overwhelming the server
      if (i < updates.length - 1) {
        await new Promise(resolve => setTimeout(resolve, 10));
      }
    }

    onProgress?.({
      current: updated,
      total: updates.length,
      completed: updated,
      phase: 'completing',
      errors: errors
    });

    return {
      success: updated > 0,
      totalProcessed: updates.length,
      successCount: updated,
      successful: updated,
      failed: errors.length,
      errorCount: errors.length,
      total: updates.length,
      results: [],
      errors,
      duration: 0,
      response: {
        updated,
        errors
      }
    };
  }
}

// Export singleton instance
export const bulkOperationsService = new BulkOperationsService();

/**
 * Tube Field Access Service - Domain Service Implementation
 * 
 * Domain service that encapsulates the business logic for resolving nested field
 * access patterns in tube data structures. This service implements the core
 * business capability of accessing structured data through consistent field identifiers.
 * 
 * Following DDD principles:
 * - Encapsulates complex field resolution business logic
 * - Provides consistent interface for domain field access
 * - Handles domain-specific validation and error handling
 * - Maintains business rules for field access patterns
 * - Enables safe navigation of nested data structures
 */

import { DomainError, FieldResolutionError, FieldPathError } from '@shared/domain/errors/DomainError';

import type {
  FieldResolver,
  FieldPathMapping,
  FieldResolutionOptions,
  FieldResolutionResult
} from '../types/FieldResolver';
import type { TubeData } from '@shared/types/tubeTypes';


/**
 * Performance monitoring for field resolution operations
 */
interface PerformanceMetrics {
  totalResolutions: number;
  averageResolutionTime: number;
  cacheHits: number;
  cacheMisses: number;
  errorCount: number;
}

/**
 * TubeFieldAccessService - Domain Service Implementation
 *
 * Implements FieldResolver to provide field resolution capabilities for tube data.
 * This service contains the business logic for safely navigating nested tube data
 * structures and resolving field values through configured path mappings.
 */
export class TubeFieldAccessService implements FieldResolver {
  private readonly pathMapping: FieldPathMapping;
  private readonly performanceMetrics: PerformanceMetrics;
  private readonly pathCache: Map<string, string[]>;
  
  constructor(pathMapping: FieldPathMapping) {
    this.pathMapping = { ...pathMapping }; // Defensive copy
    this.performanceMetrics = {
      totalResolutions: 0,
      averageResolutionTime: 0,
      cacheHits: 0,
      cacheMisses: 0,
      errorCount: 0
    };
    this.pathCache = new Map();
    
    // Validate configuration on construction
    this.validateConfiguration();
  }

  // CORE RESOLUTION METHODS

  getValue<T = any>(
    data: TubeData, 
    fieldKey: string, 
    options: FieldResolutionOptions = {}
  ): T | undefined {
    const startTime = performance.now();
    
    try {
      this.performanceMetrics.totalResolutions++;
      
      // Validate inputs
      this.validateFieldKey(fieldKey);
      this.validateDataObject(data);
      
      const path = this.getFieldPath(fieldKey);
      const value = this.resolvePath(data, path);
      
      // Apply transformation if provided
      const finalValue = options.transform ? options.transform(value) : value;
      
      // Handle missing values
      if (finalValue === undefined || finalValue === null) {
        if (options.throwOnMissing === true) {
          throw new FieldPathError(path, fieldKey, { 
            dataId: data.id,
            options 
          });
        }
        return options.defaultValue as T;
      }
      
      this.updatePerformanceMetrics(startTime);
      return finalValue as T;
      
    } catch (error) {
      this.performanceMetrics.errorCount++;
      this.updatePerformanceMetrics(startTime);
      
      if (error instanceof DomainError) {
        throw error;
      }
      
      // Wrap unexpected errors in domain error
      throw new FieldPathError(
        this.pathMapping[fieldKey] || 'unknown',
        fieldKey,
        { 
          originalError: error instanceof Error ? error.message : String(error),
          dataId: data.id,
          options
        }
      );
    }
  }

  getValues<T = any>(
    data: TubeData[], 
    fieldKey: string,
    options: FieldResolutionOptions = {}
  ): (T | undefined)[] {
    // Validate inputs
    this.validateFieldKey(fieldKey);
    
    if (!Array.isArray(data)) {
      throw new DomainError('Data must be an array for bulk resolution', 'INVALID_INPUT');
    }
    
    // Use single path resolution for all items (performance optimization)
    const path = this.getFieldPath(fieldKey);
    const compiledPath = this.compilePath(path);
    
    return data.map(item => {
      try {
        this.validateDataObject(item);
        const value = this.resolveCompiledPath(item, compiledPath);
        const finalValue = options.transform ? options.transform(value) : value;
        
        if (finalValue === undefined || finalValue === null) {
          return options.defaultValue as T;
        }
        
        return finalValue as T;
      } catch (error) {
        if (options.throwOnMissing === true) {
          throw error;
        }
        return options.defaultValue as T;
      }
    });
  }

  hasValue(data: TubeData, fieldKey: string): boolean {
    try {
      const value = this.getValue(data, fieldKey, { 
        throwOnMissing: false,
        defaultValue: null 
      });
      
      // Business rule: meaningful value check
      return value !== null && 
             value !== undefined && 
             value !== '' &&
             !(Array.isArray(value) && value.length === 0);
             
    } catch (error) {
      return false;
    }
  }

  getFieldPath(fieldKey: string): string {
    const path = this.pathMapping[fieldKey];
    
    if (!path) {
      throw new FieldResolutionError(
        fieldKey,
        this.getAvailableFields(),
        { service: 'TubeFieldAccessService' }
      );
    }
    
    return path;
  }

  isValidField(fieldKey: string): boolean {
    return fieldKey in this.pathMapping;
  }

  resolveField<T = any>(
    data: TubeData, 
    fieldKey: string
  ): FieldResolutionResult<T> {
    let resolved = false;
    let value: T | undefined = undefined;
    let resolvedPath = '';
    let exists = false;
    
    try {
      this.validateFieldKey(fieldKey);
      resolvedPath = this.getFieldPath(fieldKey);
      
      // Check if the path exists in the data structure
      exists = this.pathExists(data, resolvedPath);
      
      if (exists) {
        value = this.resolvePath(data, resolvedPath) as T;
        resolved = true;
      }
      
    } catch (error) {
      // Resolution failed, but we still return metadata
      resolved = false;
    }
    
    return {
      value,
      resolved,
      resolvedPath,
      exists
    };
  }

  getAvailableFields(): string[] {
    return Object.keys(this.pathMapping).sort();
  }

  validateConfiguration(): void {
    if (!this.pathMapping || typeof this.pathMapping !== 'object') {
      throw new DomainError(
        'Field path mapping must be a valid object',
        'INVALID_CONFIGURATION'
      );
    }
    
    const keys = Object.keys(this.pathMapping);
    if (keys.length === 0) {
      throw new DomainError(
        'Field path mapping cannot be empty',
        'EMPTY_CONFIGURATION'
      );
    }
    
    // Validate each mapping
    Object.entries(this.pathMapping).forEach(([fieldKey, path]) => {
      if (!fieldKey || fieldKey.trim() === '') {
        throw new DomainError(
          'Field key cannot be empty',
          'INVALID_FIELD_KEY',
          { fieldKey }
        );
      }
      
      if (!path || path.trim() === '') {
        throw new DomainError(
          `Path cannot be empty for field key: ${fieldKey}`,
          'INVALID_FIELD_PATH',
          { fieldKey }
        );
      }
      
      // Validate path format
      if (!/^[a-zA-Z0-9_.]+$/.test(path)) {
        throw new DomainError(
          `Invalid path format for field key '${fieldKey}': ${path}`,
          'INVALID_PATH_FORMAT',
          { fieldKey, path }
        );
      }
    });
  }

  // PERFORMANCE & MONITORING

  /**
   * Get performance metrics for monitoring and optimization
   */
  getPerformanceMetrics(): PerformanceMetrics {
    return { ...this.performanceMetrics };
  }

  /**
   * Reset performance metrics (useful for testing)
   */
  resetMetrics(): void {
    this.performanceMetrics.totalResolutions = 0;
    this.performanceMetrics.averageResolutionTime = 0;
    this.performanceMetrics.cacheHits = 0;
    this.performanceMetrics.cacheMisses = 0;
    this.performanceMetrics.errorCount = 0;
  }

  /**
   * Clear path cache (useful for testing or configuration changes)
   */
  clearCache(): void {
    this.pathCache.clear();
  }

  // PRIVATE HELPER METHODS

  /**
   * Safely resolve a nested path in an object
   */
  private resolvePath(obj: any, path: string): any {
    const compiledPath = this.compilePath(path);
    return this.resolveCompiledPath(obj, compiledPath);
  }

  /**
   * Resolve using pre-compiled path segments for performance
   */
  private resolveCompiledPath(obj: any, pathSegments: string[]): any {
    let current = obj;
    
    for (const segment of pathSegments) {
      if (current === null || current === undefined) {
        return undefined;
      }
      
      current = current[segment];
    }
    
    return current;
  }

  /**
   * Compile path string into segments with caching for performance
   */
  private compilePath(path: string): string[] {
    let compiled = this.pathCache.get(path);
    
    if (compiled) {
      this.performanceMetrics.cacheHits++;
      return compiled;
    }
    
    this.performanceMetrics.cacheMisses++;
    compiled = path.split('.');
    this.pathCache.set(path, compiled);
    
    return compiled;
  }

  /**
   * Check if a path exists in the data structure (without retrieving value)
   */
  private pathExists(obj: any, path: string): boolean {
    const compiledPath = this.compilePath(path);
    let current = obj;
    
    for (const segment of compiledPath) {
      if (current === null || current === undefined) {
        return false;
      }
      
      if (!(segment in current)) {
        return false;
      }
      
      current = current[segment];
    }
    
    return true;
  }

  /**
   * Validate field key input
   */
  private validateFieldKey(fieldKey: string): void {
    if (!fieldKey || typeof fieldKey !== 'string') {
      throw new DomainError(
        'Field key must be a non-empty string',
        'INVALID_FIELD_KEY',
        { fieldKey }
      );
    }
  }

  /**
   * Validate data object input
   */
  private validateDataObject(data: any): void {
    if (!data || typeof data !== 'object') {
      throw new DomainError(
        'Data must be a valid object',
        'INVALID_DATA_OBJECT',
        { dataType: typeof data }
      );
    }
  }

  /**
   * Update performance metrics with timing information
   */
  private updatePerformanceMetrics(startTime: number): void {
    const duration = performance.now() - startTime;
    const total = this.performanceMetrics.totalResolutions;
    const currentAvg = this.performanceMetrics.averageResolutionTime;
    
    // Calculate rolling average
    this.performanceMetrics.averageResolutionTime = 
      ((currentAvg * (total - 1)) + duration) / total;
  }
}

/**
 * Factory function for creating TubeFieldAccessService instances
 */
export function createTubeFieldAccessService(
  pathMapping: FieldPathMapping
): TubeFieldAccessService {
  return new TubeFieldAccessService(pathMapping);
}

/**
 * Singleton instance for default tube field access
 * Can be overridden for testing or different configurations
 */
let defaultInstance: TubeFieldAccessService | null = null;

export function getDefaultTubeFieldAccessService(
  pathMapping?: FieldPathMapping
): TubeFieldAccessService {
  if (!defaultInstance || pathMapping) {
    // Use dynamic import to avoid circular dependencies
    if (pathMapping) {
      defaultInstance = new TubeFieldAccessService(pathMapping);
    } else {
      throw new Error('Default field mapping not available. Use getFieldResolverApplicationService() instead.');
    }
  }
  
  return defaultInstance;
}

/**
 * Reset default instance (useful for testing)
 */
export function resetDefaultTubeFieldAccessService(): void {
  defaultInstance = null;
}

import { NAMING_PATTERNS } from '@odysseus/shared-schemas';

import { queryKeys } from '@app/queryKeys';
import { useStorageStore } from '@domains/storage';

import type { useQueryClient } from '@tanstack/react-query';

/**
 * Data Consistency Service
 * 
 * Ensures tank IDs are consistent between configuration and actual tube data.
 * Fixes the "main-tank" vs "tank-1" mismatch issue.
 */
export class DataConsistencyService {
  private static instance: DataConsistencyService;
  
  public static getInstance(): DataConsistencyService {
    if (!DataConsistencyService.instance) {
      DataConsistencyService.instance = new DataConsistencyService();
    }
    return DataConsistencyService.instance;
  }

  /**
   * Get the authoritative tank ID based on actual tube data from React Query cache
   * This is the SINGLE SOURCE OF TRUTH for tank IDs
   */
  public getAuthoritativeTankId(queryClient?: ReturnType<typeof useQueryClient>): string {
    try {
      // Get tubes data from React Query cache
      const tubes = queryClient?.getQueryData(queryKeys.tubes.lists()) || [];
      
      // If we have tube data, use the tank ID from the actual data
      if (Array.isArray(tubes) && tubes.length > 0) {
        const actualTankIds = [...new Set(tubes.map((t: any) => t.location?.tankId || t.tankId).filter(Boolean))];
        if (actualTankIds.length > 0) {
          const authoritative = actualTankIds[0]; // Use first real tank ID
          // eslint-disable-next-line no-console -- Info logging for operational visibility
          console.log(`📋 DATA CONSISTENCY: Authoritative tank ID from React Query data: "${authoritative}"`);
          return authoritative;
        }
      }
    } catch (error) {
      // eslint-disable-next-line no-console -- Warning logging for production monitoring
      console.warn('📋 DATA CONSISTENCY: Could not access React Query cache:', error);
    }
    
    // Fallback to default
    // eslint-disable-next-line no-console -- Info logging for operational visibility
    console.log(`📋 DATA CONSISTENCY: No tube data found, using default: "${NAMING_PATTERNS.TANK.ID_PATTERN(1)}"`);
    return NAMING_PATTERNS.TANK.ID_PATTERN(1);
  }

  /**
   * Sync configuration tank IDs with actual data
   * Call this during app initialization  
   */
  public async syncConfigurationWithData(queryClient?: ReturnType<typeof useQueryClient>): Promise<void> {
    const authoritativeTankId = this.getAuthoritativeTankId(queryClient);
    const configStore = useStorageStore.getState();
    const currentTanks = configStore.getCurrentTanks();
    
    // eslint-disable-next-line no-console -- Info logging for operational visibility
    console.log(`📋 DATA CONSISTENCY: Current config tanks:`, currentTanks.map(t => ({ id: t.id, name: t.name })));
    
    // Check if configuration has mismatched tank IDs
    const hasMismatch = currentTanks.some(tank =>
      tank.id !== authoritativeTankId &&
      (tank.id === 'main-tank' || authoritativeTankId === NAMING_PATTERNS.TANK.ID_PATTERN(1))
    );
    
    if (hasMismatch) {
      // eslint-disable-next-line no-console -- Info logging for operational visibility
      console.log(`📋 DATA CONSISTENCY: Found tank ID mismatch, correcting directly in store...`);
      
      // Find the mismatched tank
      const mismatchedTank = currentTanks.find(tank => tank.id === 'main-tank');
      if (mismatchedTank) {
        // eslint-disable-next-line no-console -- Info logging for operational visibility
        console.log(`📋 DATA CONSISTENCY: Updating tank ID from "${mismatchedTank.id}" to "${authoritativeTankId}"`);
        
        // Update the tank directly in the store's state
        this.forceUpdateTankId(mismatchedTank, authoritativeTankId);
      }
    } else {
      // eslint-disable-next-line no-console -- Info logging for operational visibility
      console.log(`📋 DATA CONSISTENCY: Tank IDs are consistent`);
    }
  }

  /**
   * Force update tank ID directly in the configuration store
   */
  private forceUpdateTankId(oldTank: any, newTankId: string): void {
    const configStore = useStorageStore.getState();
    
    try {
      // Get current lab config
      const currentLab = configStore.currentLab;
      
      // Update the tank ID in the tanks array
      const updatedTanks = currentLab.equipment.tanks.map(tank => 
        tank.id === oldTank.id ? { ...tank, id: newTankId } : tank
      );
      
      // Update the lab configuration with new tank ID
      const updatedLab = {
        ...currentLab,
        equipment: {
          ...currentLab.equipment,
          tanks: updatedTanks
        }
      };
      
      // Force the store to update with corrected data
      configStore.setCurrentLab(updatedLab.id);
      
      // Also update the systemConfig to include the corrected lab
      const updatedSystemConfig = {
        ...configStore.systemConfig,
        availableLabs: configStore.systemConfig.availableLabs.map(lab =>
          lab.id === updatedLab.id ? updatedLab : lab
        )
      };
      
      // Force store state update
      useStorageStore.setState({
        currentLab: updatedLab,
        systemConfig: updatedSystemConfig
      });
      
      // eslint-disable-next-line no-console -- Info logging for operational visibility
      console.log(`📋 DATA CONSISTENCY: Tank ID forcibly updated to "${newTankId}"`);
      
    } catch (error) {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('Failed to force update tank ID:', error);
    }
  }

  /**
   * Clear persisted configuration to force rebuild with correct IDs
   */
  private clearPersistedConfiguration(): void {
    try {
      // Clear localStorage for the configuration store
      const keys = Object.keys(localStorage).filter(key => 
        key.includes('configuration-store') || 
        key.includes('odysseus-config') ||
        key.includes('lab-config')
      );
      
      keys.forEach(key => {
        // eslint-disable-next-line no-console -- Info logging for operational visibility
        console.log(`📋 DATA CONSISTENCY: Clearing cached config: ${key}`);
        localStorage.removeItem(key);
      });
      
      // Also try common Zustand persist keys
      localStorage.removeItem('odysseus-configuration-storage');
      localStorage.removeItem('configuration-storage');
      
    } catch (error) {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('Failed to clear persisted configuration:', error);
    }
  }

  /**
   * Get consistent navigation location based on actual data
   */
  public getConsistentLocation(queryClient?: ReturnType<typeof useQueryClient>): { tankId: string; rackId: number; boxId: string } {
    const authoritativeTankId = this.getAuthoritativeTankId(queryClient);
    
    return {
      tankId: authoritativeTankId,
      rackId: 1,
      boxId: 'A'
    };
  }
}

export const dataConsistencyService = DataConsistencyService.getInstance();

/**
 * Field Resolver Domain Service Contract
 * 
 * Defines the contract for resolving nested field access patterns in domain entities.
 * This interface represents the core business capability of accessing structured data
 * through consistent field identifiers.
 * 
 * Following DDD principles:
 * - Domain service interface defines business capabilities
 * - Abstracts complex field resolution logic from consumers
 * - Provides consistent API for nested data access
 * - Enables dependency inversion for testing and flexibility
 */

import type { TubeData } from '@shared/types/tubeTypes';

/**
 * Field path mapping configuration type
 * Maps flat field keys to nested object paths
 */
export type FieldPathMapping = Record<string, string>;

/**
 * Field resolution options for advanced field access
 */
export interface FieldResolutionOptions {
  /** Default value to return if field is not found */
  defaultValue?: any;
  /** Whether to throw error on missing field (default: true) */
  throwOnMissing?: boolean;
  /** Transform function applied to resolved value */
  transform?: (value: any) => any;
}

/**
 * Field resolution result with metadata
 */
export interface FieldResolutionResult<T = any> {
  /** The resolved field value */
  value: T | undefined;
  /** Whether the field was successfully resolved */
  resolved: boolean;
  /** The nested path that was used for resolution */
  resolvedPath: string;
  /** Whether the field exists in the data structure */
  exists: boolean;
}

/**
 * Domain Service Contract: FieldResolver
 *
 * Encapsulates the business logic for resolving nested field access patterns.
 * Provides a consistent interface for accessing complex data structures through
 * simple field identifiers.
 *
 * Business Rules:
 * - Field keys must be predefined in field mapping configuration
 * - Nested paths are resolved safely (no runtime errors on missing properties)
 * - Type safety is maintained through generic return types
 * - Field existence can be checked without retrieving values
 * - Bulk operations are supported for performance
 */
export interface FieldResolver {
  /**
   * Resolve a single field value from a data object
   * 
   * @param data - The source data object to resolve from
   * @param fieldKey - The field identifier to resolve
   * @param options - Additional resolution options
   * @returns The resolved field value or undefined if not found
   * 
   * @throws FieldResolutionError if fieldKey is not valid
   * @throws FieldPathError if path resolution fails and throwOnMissing is true
   */
  getValue<T = any>(
    data: TubeData, 
    fieldKey: string, 
    options?: FieldResolutionOptions
  ): T | undefined;

  /**
   * Resolve field values from multiple data objects
   * Optimized for bulk operations to avoid repeated path resolution
   * 
   * @param data - Array of source data objects
   * @param fieldKey - The field identifier to resolve
   * @param options - Additional resolution options
   * @returns Array of resolved values (same order as input)
   */
  getValues<T = any>(
    data: TubeData[], 
    fieldKey: string,
    options?: FieldResolutionOptions
  ): (T | undefined)[];

  /**
   * Check if a field has a meaningful value (not null, undefined, or empty string)
   * 
   * @param data - The source data object
   * @param fieldKey - The field identifier to check
   * @returns True if field has a meaningful value
   */
  hasValue(data: TubeData, fieldKey: string): boolean;

  /**
   * Get the nested path for a given field key
   * Useful for debugging and advanced field manipulation
   * 
   * @param fieldKey - The field identifier
   * @returns The nested object path (e.g., 'sample.cellType')
   * 
   * @throws FieldResolutionError if fieldKey is not valid
   */
  getFieldPath(fieldKey: string): string;

  /**
   * Validate if a field key is supported by this resolver
   * 
   * @param fieldKey - The field identifier to validate
   * @returns True if field key is valid and can be resolved
   */
  isValidField(fieldKey: string): boolean;

  /**
   * Get detailed field resolution result with metadata
   * Useful for debugging and validation scenarios
   * 
   * @param data - The source data object
   * @param fieldKey - The field identifier to resolve
   * @returns Detailed resolution result with metadata
   */
  resolveField<T = any>(
    data: TubeData, 
    fieldKey: string
  ): FieldResolutionResult<T>;

  /**
   * Get all available field keys that can be resolved
   * Useful for validation and debugging
   * 
   * @returns Array of all valid field keys
   */
  getAvailableFields(): string[];

  /**
   * Validate field mapping configuration for consistency
   * Ensures all paths are resolvable and no circular references exist
   * 
   * @throws DomainError if configuration is invalid
   */
  validateConfiguration(): void;
}

/**
 * Tube Form Component
 *
 * Uses API schema directly, supports both create and edit modes:
 * - Form fields match CreateTubeRequest/UpdateTubeRequest
 * - No transformation needed
 * - Media uses structured object: { type, supplements, selection }
 * - Concentration handled by ConcentrationInput with Zod preprocessing
 *
 * Compact 4-row layout:
 * - Row 1: Donor Information (Cell Type*, Internal ID, Source ID)
 * - Row 2: Sample Information Part 1 (Concentration + Unit, Media Type, Supplements, Selection)
 * - Row 3: Sample Information Part 2 (Culture Condition, Lot #, Date, Researcher)
 * - Row 4: Notes
 *
 * * = Required field (only Cell Type)
 */

import {
  type CreateTubeRequest,
  type UpdateTubeRequest,
  type Researcher,
  formatResearcherDropdownDisplay
} from '@odysseus/shared-schemas';
import { Controller } from 'react-hook-form';

import { ValidatedInput } from '@shared/ui';

import { ConcentrationInput } from '../../inputs/ConcentrationInput';

import type { Control, UseFormRegister, FieldErrors, UseFormTrigger} from 'react-hook-form';

/**
 * Form values union - supports both create and edit modes
 */
type TubeFormValues = CreateTubeRequest | UpdateTubeRequest;

export interface TubeFormProps {
  control: Control<TubeFormValues>;
  register: UseFormRegister<TubeFormValues>;
  errors: FieldErrors<TubeFormValues>;
  trigger: UseFormTrigger<TubeFormValues>;
  researchers: Researcher[];
  isLoading: boolean;
}

export const TubeForm = ({
  control,
  register,
  errors,
  trigger,
  researchers,
  isLoading
}: TubeFormProps) => {
  // Helper function to get field errors from nested React Hook Form structure
  const getFieldError = (fieldPath: string, errors: FieldErrors<CreateTubeRequest>): string | undefined => {
    const pathParts = fieldPath.split('.');
    let currentError = errors as any;

    for (const part of pathParts) {
      if (currentError?.[part]) {
        currentError = currentError[part];
      } else {
        return undefined;
      }
    }

    return currentError?.message;
  };

  // Helper to get concentration field errors (checks both nested and refinement errors)
  const getConcentrationError = (): string | undefined => {
    // Check for direct concentration field error
    const directError = getFieldError('sample.concentration', errors);
    if (directError) return directError;

    // Check for concentrationUnit field error
    const unitError = getFieldError('sample.concentrationUnit', errors);
    if (unitError) return unitError;

    // Check for refinement error at sample level (concentration/unit invariant)
    const sampleError = (errors as any)?.sample;
    if (sampleError && typeof sampleError.message === 'string') {
      return sampleError.message;
    }

    return undefined;
  };

  return (
    <div className="space-y-3">
      {/* ROW 1: DONOR INFORMATION */}
      <div className="space-y-1.5">
        <h3 className="text-xs font-semibold text-storage-tank-hover tracking-wide uppercase">Donor Information</h3>
        <div className="grid grid-cols-3 gap-2.5">
          <ValidatedInput
            label="Cell Type"
            type="text"
            placeholder="e.g., Jurkat, HEK293"
            registration={register('sample.cellType')}
            error={Boolean(getFieldError('sample.cellType', errors))}
            helperText={getFieldError('sample.cellType', errors)}
            disabled={isLoading}
            required
          />
          <ValidatedInput
            label="Internal ID"
            type="text"
            placeholder="Internal tracking ID"
            registration={register('sample.donorInternalId')}
            error={Boolean(getFieldError('sample.donorInternalId', errors))}
            helperText={getFieldError('sample.donorInternalId', errors)}
            disabled={isLoading}
          />
          <ValidatedInput
            label="Source ID"
            type="text"
            placeholder="Original source ID"
            registration={register('sample.donorSourceId')}
            error={Boolean(getFieldError('sample.donorSourceId', errors))}
            helperText={getFieldError('sample.donorSourceId', errors)}
            disabled={isLoading}
          />
        </div>
      </div>

      {/* ROW 2: SAMPLE INFORMATION (PART 1) - Media Fields */}
      <div className="space-y-1.5">
        <h3 className="text-xs font-semibold text-storage-rack-hover tracking-wide uppercase">Sample Information</h3>
        <div className="grid grid-cols-4 gap-2.5">
          <div>
            <Controller
              name="sample.concentration"
              control={control}
              render={({ field: { value, onChange } }) => (
                <Controller
                  name="sample.concentrationUnit"
                  control={control}
                  render={({ field: { value: unitValue, onChange: onUnitChange } }) => (
                    <ConcentrationInput
                      label="Concentration"
                      value={String(value ?? '')}
                      unitValue={unitValue ?? ''}
                      onChange={onChange}
                      onUnitChange={async (newUnit) => {
                        onUnitChange(newUnit);
                        await trigger('sample');
                      }}
                      placeholder="e.g., 5e6"
                      disabled={isLoading}
                      validation={{
                        error: Boolean(getConcentrationError()),
                        warning: false,
                        helperText: getConcentrationError(),
                        onBlur: () => {}
                      }}
                    />
                  )}
                />
              )}
            />
          </div>
          <ValidatedInput
            label="Media Type"
            type="text"
            placeholder="e.g., RPMI-1640"
            registration={register('sample.media.type')}
            error={Boolean(getFieldError('sample.media.type', errors))}
            helperText={getFieldError('sample.media.type', errors)}
            disabled={isLoading}
          />
          <ValidatedInput
            label="Supplements"
            type="text"
            placeholder="e.g., 10% FBS"
            registration={register('sample.media.supplements')}
            error={Boolean(getFieldError('sample.media.supplements', errors))}
            helperText={getFieldError('sample.media.supplements', errors)}
            disabled={isLoading}
          />
          <ValidatedInput
            label="Selection"
            type="text"
            placeholder="e.g., Puromycin"
            registration={register('sample.media.selection')}
            error={Boolean(getFieldError('sample.media.selection', errors))}
            helperText={getFieldError('sample.media.selection', errors)}
            disabled={isLoading}
          />
        </div>
      </div>

      {/* ROW 3: SAMPLE INFORMATION (PART 2) */}
      <div className="grid grid-cols-4 gap-2.5">
        <ValidatedInput
          label="Culture Condition"
          type="text"
          placeholder="e.g., 5% O₂, 37°C"
          registration={register('sample.cultureCondition')}
          error={Boolean(getFieldError('sample.cultureCondition', errors))}
          helperText={getFieldError('sample.cultureCondition', errors)}
          disabled={isLoading}
        />
        <ValidatedInput
          label="Lot #"
          type="text"
          placeholder="LOT001"
          registration={register('sample.lotNumber')}
          error={Boolean(getFieldError('sample.lotNumber', errors))}
          helperText={getFieldError('sample.lotNumber', errors)}
          disabled={isLoading}
        />
        <ValidatedInput
          label="Date"
          type="date"
          registration={register('sample.date')}
          error={Boolean(getFieldError('sample.date', errors))}
          helperText={getFieldError('sample.date', errors)}
          disabled={isLoading}
        />
        <ValidatedInput
          label="Researcher"
          type="select"
          registration={register('researcherId')}
          error={Boolean(getFieldError('researcherId', errors))}
          helperText={getFieldError('researcherId', errors)}
          disabled={isLoading}
          options={[
            { value: '', label: 'Select researcher...' },
            ...researchers.map(r => ({
              value: r.id,
              label: formatResearcherDropdownDisplay(r)
            }))
          ]}
        />
      </div>

      {/* ROW 4: NOTES */}
      <div className="space-y-1.5">
        <h3 className="text-xs font-semibold text-storage-box-hover tracking-wide uppercase">Notes</h3>
        <ValidatedInput
          label=""
          type="textarea"
          maxLength={500}
          placeholder="Additional notes and observations..."
          registration={register('sample.notes')}
          error={Boolean(getFieldError('sample.notes', errors))}
          helperText={getFieldError('sample.notes', errors)}
          disabled={isLoading}
        />
      </div>
    </div>
  );
};

