}

/**
* Convert TubeData to CreateTubeRequest format
* CreateTubeRequest doesn't include id (that's generated server-side)
*/
function convertTubeDataToFormData(tubeData: TubeData): Partial<CreateTubeRequest> {
  return {
    // id is not part of CreateTubeRequest - it's generated on creation
    location: tubeData.location,
    sample: {
      // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Empty cellType is validation failure, show empty for user to fill
      cellType: tubeData.sample.cellType || '',
      donorInternalId: tubeData.sample.donorInternalId,
      donorSourceId: tubeData.sample.donorSourceId,
      concentration: tubeData.sample.concentration,
      concentrationUnit: tubeData.sample.concentrationUnit,
      date: parseDate(tubeData.sample.date),
      media: tubeData.sample.media,
      cultureCondition: tubeData.sample.cultureCondition,
      lotNumber: tubeData.sample.lotNumber,
      notes: tubeData.sample.notes
    },
    researcherId: tubeData.researcherId
  };
}

/**
 * Analyze multiple tubes for conflicts and common values
 */
export function analyzeTubeConflicts(tubes: TubeData[]): ConflictInfo {
  if (tubes.length === 0) {
    return {
      hasConflicts: false,
      conflictingFields: new Set(),
      commonValues: {}
    };
  }

  if (tubes.length === 1) {
    return {
      hasConflicts: false,
      conflictingFields: new Set(),
      commonValues: convertTubeDataToFormData(tubes[0])
    };
  }

  const conflictingFields = new Set<keyof CreateTubeRequest>();
  const commonValues: Partial<CreateTubeRequest> = {};

  // Get all field keys from configuration
  const allFieldKeys = TUBE_FIELD_CONFIG
    .flatMap(section => section.fields)
    .map(field => field.key);

  // Get field resolver service for accessing nested data
  const fieldResolverService = getFieldResolverApplicationService();
  const fieldResolver = fieldResolverService.getFieldResolver();

  // Check each field for conflicts
  allFieldKeys.forEach(fieldKey => {
    const values = tubes.map(tube => {
      // Use field resolver to access nested properties
      try {
        return fieldResolver.getValue(tube as TubeData, fieldKey);
      } catch (error) {
        // If field is not configured in resolver, return undefined
        return undefined;
      }
    }).filter(value => value !== undefined && value !== null && value !== '');
    const uniqueValues = [...new Set(values)];

    if (uniqueValues.length === 1 && uniqueValues[0]) {
      // All tubes have the same value for this field
      (commonValues as any)[fieldKey] = uniqueValues[0];
    } else if (uniqueValues.length > 1) {
      // Conflicting values
      conflictingFields.add(fieldKey as keyof CreateTubeRequest);
    }
    // If uniqueValues.length === 0, field is empty in all tubes - don't add to common
  });

  return {
    hasConflicts: conflictingFields.size > 0,
    conflictingFields,
    commonValues
  };
}

/**
 * Format position ranges for display
 */
export function formatPositionRanges(tubes: TubeData[]): string {
  if (tubes.length === 0) return '';
  
  // Remove duplicates and sort positions
  const uniquePositions = [...new Set(tubes.map(t => t.location.position))].sort((a, b) => a - b);
  const ranges: string[] = [];
  
  let start = uniquePositions[0];
  let end = uniquePositions[0];
  
  for (let i = 1; i < uniquePositions.length; i++) {
    if (uniquePositions[i] === end + 1) {
      // Consecutive position
      end = uniquePositions[i];
    } else {
      // Gap found, add range
      if (start === end) {
        ranges.push(start.toString());
      } else {
        ranges.push(`${start}-${end}`);
      }
      start = end = uniquePositions[i];
    }
  }
  
  // Add final range
  if (start === end) {
    ranges.push(start.toString());
  } else {
    ranges.push(`${start}-${end}`);
  }
  
  return ranges.join(', ');
}

/**
* Get position summary for tubes
*/
export function getPositionSummary(tubes: TubeData[], tankName?: string, rackName?: string): string {
if (tubes.length === 0) return '';

const firstTube = tubes[0];
const box = firstTube.location.boxId;
const positions = formatPositionRanges(tubes);

const rackDisplay = rackName ?? `Rack ${firstTube.location.rackId}`;

if (tubes.length === 1) {
  return `${rackDisplay} • Box ${box} • Position ${positions}`;
} else {
  return `${rackDisplay} • Box ${box} • Positions ${positions}`;
  }
}

/**
 * Get tank name for display
 */
export function getTankName(tubes: TubeData[], customTankName?: string): string {
  if (tubes.length === 0) return '';
  return customTankName ?? `Tank ${tubes[0].location.tankId}`;
}

/**
 * Authentication HTTP Client
 * 
 * Dedicated HTTP client for authentication endpoints only.
 * Prevents circular dependency with SessionManager by providing
 * a pure HTTP transport layer without token injection.
 * 
 * Purpose:
 * - Handle /login, /refresh, /logout endpoints
 * - No automatic token injection (prevents circular dependency)
 * - No 401 retry logic (auth endpoints don't need token refresh)
 * - Simple, focused transport layer
 */

import { transformApiResponse } from './responseTransformers';

export interface AuthApiErrorData {
  message: string;
  status: number;
  code?: string;
  details?: any;
}

export class AuthApiError extends Error implements AuthApiErrorData {
  constructor(
    message: string,
    public status: number,
    public code?: string,
    public details?: any
  ) {
    super(message);
    this.name = 'AuthApiError';
  }
}

/**
 * Pure HTTP client for authentication operations
 * 
 * This client intentionally does NOT:
 * - Inject authentication tokens (prevents circular dependency)
 * - Handle 401 retries (auth endpoints handle their own errors)
 * - Use SessionManager (would create infinite loop)
 * - Apply complex transformations (keeps it simple)
 */
export class AuthHttpClient {
  private readonly baseURL: string;
  private readonly timeout: number;

  constructor(config: { baseURL: string; timeout?: number } = { baseURL: 'http://localhost:3001/api' }) {
    this.baseURL = config.baseURL;
    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Config default, 0/empty values are invalid
    this.timeout = config.timeout || 30000;
  }

  /**
   * POST request for authentication endpoints
   * 
   * @param path - API path (e.g., '/public/auth/login')
   * @param data - Request payload
   * @returns Promise with parsed JSON response
   */
  async post<T = any>(path: string, data: any): Promise<T> {
    return this.request<T>(path, {
      method: 'POST',
      body: JSON.stringify(data)
    });
  }

  /**
   * GET request for authentication endpoints (if needed)
   */
  async get<T = any>(path: string): Promise<T> {
    return this.request<T>(path, {
      method: 'GET'
    });
  }

  /**
   * Core request method with minimal error handling
   */
  private async request<T>(path: string, options: RequestInit): Promise<T> {
    const url = `${this.baseURL}${path}`;

    // Build headers - NO Authorization header
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      ...(options.headers as Record<string, string>)
    };

    try {
      // Create abort controller for timeout
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), this.timeout);

      const response = await fetch(url, {
        ...options,
        headers,
        signal: controller.signal
      });

      clearTimeout(timeoutId);

      // Parse response
      const responseData = await response.json().catch(() => ({}));

      if (!response.ok) {
        throw new AuthApiError(
          responseData.message || `Authentication request failed: ${response.status}`,
          response.status,
          responseData.code,
          responseData.details
        );
      }

      // Apply response transformation (converts date strings to Date objects)
      const typeHint = path.includes('/refresh') ? 'RefreshResponse' 
                     : path.includes('/login') ? 'LoginResponse'
                     : undefined;

      return transformApiResponse<T>(responseData, typeHint);

    } catch (error) {
      if (error instanceof AuthApiError) {
        throw error;
      }

      // Handle fetch errors (network, timeout, etc.)
      if ((error as Error).name === 'AbortError') {
        throw new AuthApiError('Authentication request timeout', 408);
      }

      throw new AuthApiError(
        `Authentication request failed: ${(error as Error).message}`,
        0, // Unknown status for network errors
        'NETWORK_ERROR',
        error
      );
    }
  }

  /**
   * Get base URL for debugging
   */
  getBaseURL(): string {
    return this.baseURL;
  }
}

/**
 * Default auth HTTP client instance
 */
export const authHttpClient = new AuthHttpClient();

/**
 * Type-safe API client with Zod validation
 * Provides centralized HTTP client with automatic data validation
 */

import type { ZodSchema } from 'zod';

/**
 * API error class for structured error handling
 */
export class ApiError extends Error {
  constructor(
    public status: number,
    public statusText: string,
    public data?: unknown
  ) {
    super(`API Error ${status}: ${statusText}`);
    this.name = 'ApiError';
  }
}

/**
 * Validation error for schema validation failures
 */
export class ValidationError extends Error {
  constructor(message: string, public issues: unknown[]) {
    super(`Validation Error: ${message}`);
    this.name = 'ValidationError';
  }
}

/**
 * Type-safe API client configuration
 */
interface ApiClientConfig {
  baseURL: string;
  timeout?: number;
  headers?: Record<string, string>;
}

/**
 * HTTP request options
 */
interface RequestOptions {
  headers?: Record<string, string>;
  timeout?: number;
}

/**
 * Type-safe API client class
 */
export class ApiClient {
  private baseURL: string;
  private defaultHeaders: Record<string, string>;
  private timeout: number;

  constructor(config: ApiClientConfig) {
    this.baseURL = config.baseURL.replace(/\/$/, ''); // Remove trailing slash
    this.defaultHeaders = {
      'Content-Type': 'application/json',
      ...config.headers
    };
    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Config default, 0/empty values are invalid
    this.timeout = config.timeout || 30000;
  }

  /**
   * Make a GET request with schema validation
   */
  async get<T>(
    endpoint: string, 
    schema: ZodSchema<T>, 
    options?: RequestOptions
  ): Promise<T> {
    const response = await this.fetch('GET', endpoint, undefined, options);
    return this.validateAndReturn(response, schema);
  }

  /**
   * Make a POST request with schema validation
   */
  async post<T>(
    endpoint: string,
    data: unknown,
    schema: ZodSchema<T>,
    options?: RequestOptions
  ): Promise<T> {
    const response = await this.fetch('POST', endpoint, data, options);
    return this.validateAndReturn(response, schema);
  }

  /**
   * Make a PUT request with schema validation
   */
  async put<T>(
    endpoint: string,
    data: unknown,
    schema: ZodSchema<T>,
    options?: RequestOptions
  ): Promise<T> {
    const response = await this.fetch('PUT', endpoint, data, options);
    return this.validateAndReturn(response, schema);
  }

  /**
   * Make a DELETE request with schema validation
   */
  async delete<T>(
    endpoint: string,
    schema: ZodSchema<T>,
    options?: RequestOptions
  ): Promise<T> {
    const response = await this.fetch('DELETE', endpoint, undefined, options);
    return this.validateAndReturn(response, schema);
  }

  /**
   * Raw fetch wrapper with error handling
   */
  private async fetch(
    method: string,
    endpoint: string,
    data?: unknown,
    options?: RequestOptions
  ): Promise<Response> {
    const url = `${this.baseURL}${endpoint}`;
    
    const headers = {
      ...this.defaultHeaders,
      ...options?.headers
    };

    const controller = new AbortController();
    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Config default, 0/empty values are invalid
    const timeout = options?.timeout || this.timeout;
    
    const timeoutId = setTimeout(() => controller.abort(), timeout);

    try {
      const response = await fetch(url, {
        method,
        headers,
        body: data ? JSON.stringify(data) : undefined,
        signal: controller.signal
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        throw new ApiError(response.status, response.statusText, await this.safeJsonParse(response));
      }

      return response;
    } catch (error) {
      clearTimeout(timeoutId);
      
      if (error instanceof ApiError) {
        throw error;
      }
      
      if (error instanceof DOMException && error.name === 'AbortError') {
        throw new ApiError(408, 'Request Timeout');
      }
      
      throw new ApiError(500, 'Network Error', error);
    }
  }

  /**
   * Validate response data with Zod schema
   */
  private async validateAndReturn<T>(response: Response, schema: ZodSchema<T>): Promise<T> {
    const rawData = await this.safeJsonParse(response);
    
    try {
      return schema.parse(rawData);
    } catch (error) {
      throw new ValidationError(
        'Response data validation failed',
        (error as any).issues || [error]
      );
    }
  }

  /**
   * Safely parse JSON response
   */
  private async safeJsonParse(response: Response): Promise<unknown> {
    const text = await response.text();
    
    if (!text) {
      return null;
    }
    
    try {
      return JSON.parse(text);
    } catch {
      return text;
    }
  }

  /**
   * Set authentication token
   */
  setAuthToken(token: string) {
    this.defaultHeaders['Authorization'] = `Bearer ${token}`;
  }

  /**
   * Remove authentication token
   */
  removeAuthToken() {
    delete this.defaultHeaders['Authorization'];
  }

  /**
   * Update default headers
   */
  setHeaders(headers: Record<string, string>) {
    this.defaultHeaders = { ...this.defaultHeaders, ...headers };
  }
}

/**
 * Default API client instance
 */
export const apiClient = new ApiClient({
  baseURL: 'http://localhost:3001/api',
  timeout: 30000
});

/**
 * Utility function to create API client with custom config
 */
export const createApiClient = (config: ApiClientConfig) => new ApiClient(config);

/**
 * HTTP Client for API communication
 */
import {
  successEnvelopeSchema,
  errorEnvelopeSchema,
  paginatedEnvelopeSchema,
  batchEnvelopeSchema,
  ApiError,
  type PaginatedResult,
  type BatchResult
} from '@odysseus/shared-schemas';
import { z } from 'zod';

import { transformApiResponse, ResponseTransformers } from './responseTransformers';

import type { TokenProvider } from '@shared/session/types';

export interface HttpClientConfig {
  baseURL?: string;
  timeout?: number;
  headers?: Record<string, string>;
}

export interface ApiResponse<T = unknown> {
  data: T;
  status: number;
  statusText: string;
  headers: Record<string, string>;
}

export class HttpClient {
  private baseURL: string;
  private defaultHeaders: Record<string, string>;
  private timeout: number;

  constructor(config: HttpClientConfig = {}) {
    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Config default, 0/empty values are invalid
    this.baseURL = config.baseURL || '/api';
    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Config default, 0/empty values are invalid
    this.timeout = config.timeout || 10000;
    this.defaultHeaders = {
      'Content-Type': 'application/json',
      ...config.headers
    };
  }

  private async request<T = unknown>(
    method: string,
    url: string,
    data?: unknown,
    headers?: Record<string, string>
  ): Promise<ApiResponse<T>> {
    const fullUrl = url.startsWith('http') ? url : `${this.baseURL}${url}`;
    const requestHeaders = { ...this.defaultHeaders, ...headers };

    try {
      const response = await fetch(fullUrl, {
        method,
        headers: requestHeaders,
        body: data ? JSON.stringify(data) : undefined,
        signal: AbortSignal.timeout(this.timeout)
      });

      const responseData = await response.json().catch(() => null);

      if (!response.ok) {
        const errorParsed = errorEnvelopeSchema.safeParse(responseData);
        
        if (errorParsed.success) {
          throw new ApiError(
            errorParsed.data.error,
            response.status,
            errorParsed.data.code,
            errorParsed.data.details
          );
        }
        
        throw new ApiError(
          responseData?.message || `HTTP ${response.status}: ${response.statusText}`,
          response.status,
          responseData?.code
        );
      }

      return {
        data: responseData,
        status: response.status,
        statusText: response.statusText,
        headers: Object.fromEntries(response.headers.entries())
      };
    } catch (error) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error('Network request failed');
    }
  }

  /**
   * Apply intelligent response transformation based on endpoint patterns
   */
  applyResponseTransformation(data: unknown, url: string): unknown {
    if (!data) return data;

    if (url.includes('/auth/login') || url.includes('/auth/register')) {
      return ResponseTransformers.LoginResponse(data);
    }
    else if (url.includes('/auth/refresh')) {
      return ResponseTransformers.RefreshResponse(data);
    }
    else if (url.includes('/users/me/profile')) {
      return ResponseTransformers.Person(data);
    }
    else if (url.includes('/users/me/sessions')) {
      if (Array.isArray(data)) {
        return data.map((session: any) => ResponseTransformers.ActiveSession(session));
      }
      return ResponseTransformers.ActiveSession(data);
    }
    else if (url.includes('/users/me/settings')) {
      return transformApiResponse(data, 'UserSettingsResponse');
    }
    else if (url.includes('/configuration')) {
      return transformApiResponse(data, 'ConfigurationResponse');
    }
    else if (url.includes('/tubes')) {
      return transformApiResponse(data, 'TubeData');
    }
    else if (url.includes('/researchers')) {
      return ResponseTransformers.Researcher(data);
    }
    else if (url.includes('/admin/users')) {
      if (Array.isArray(data)) {
        return data.map((user: any) => ResponseTransformers.AdminUser(user));
      }
      return ResponseTransformers.AdminUser(data);
    }
    else if (url.includes('/admin/metrics')) {
      return ResponseTransformers.SystemMetrics(data);
    }
    else if (url.includes('/admin/audit')) {
      if (Array.isArray(data)) {
        return data.map((entry: any) => ResponseTransformers.AuditLogEntry(entry));
      }
      return ResponseTransformers.AuditLogEntry(data);
    }
    else {
      return transformApiResponse(data);
    }
  }

  async get<T = unknown>(url: string, headers?: Record<string, string>): Promise<ApiResponse<T>> {
    return this.request<T>('GET', url, undefined, headers);
  }

  async post<T = unknown>(url: string, data?: unknown, headers?: Record<string, string>): Promise<ApiResponse<T>> {
    return this.request<T>('POST', url, data, headers);
  }

  async put<T = unknown>(url: string, data?: unknown, headers?: Record<string, string>): Promise<ApiResponse<T>> {
    return this.request<T>('PUT', url, data, headers);
  }

  async delete<T = unknown>(url: string, headers?: Record<string, string>): Promise<ApiResponse<T>> {
    return this.request<T>('DELETE', url, undefined, headers);
  }

  /**
   * GET request that unwraps envelope and validates data
   */
  async getData<T>(
    url: string, 
    dataSchema: z.ZodType<T>,
    headers?: Record<string, string>
  ): Promise<T> {
    const response = await this.get(url, headers);
    
    const envelope = successEnvelopeSchema(dataSchema).parse(response.data);
    
    return envelope.data;
  }

  /**
   * GET request for array responses (most common)
   */
  async getArray<T>(
    url: string,
    itemSchema: z.ZodType<T>,
    headers?: Record<string, string>
  ): Promise<T[]> {
    const response = await this.get(url, headers);

    const envelope = successEnvelopeSchema(z.array(itemSchema)).safeParse(response.data);

    if (!envelope.success) {
      throw 'error' in envelope ? envelope.error : new Error('Validation failed');
    }

    return envelope.data.data;
  }

  /**
   * POST request that unwraps envelope and validates response
   */
  async postData<TResponse, TRequest = unknown>(
    url: string,
    body: TRequest,
    responseSchema: z.ZodType<TResponse>,
    headers?: Record<string, string>
  ): Promise<TResponse> {
    const response = await this.post(url, body, headers);

    const envelope = successEnvelopeSchema(responseSchema).parse(response.data);
    return envelope.data;
  }

  /**
   * PUT request that unwraps envelope and validates response
   */
  async putData<TResponse, TRequest = unknown>(
    url: string,
    body: TRequest,
    responseSchema: z.ZodType<TResponse>,
    headers?: Record<string, string>
  ): Promise<TResponse> {
    const response = await this.put(url, body, headers);

    const envelope = successEnvelopeSchema(responseSchema).parse(response.data);

    return envelope.data;
  }

  /**
   * DELETE request (returns void)
   */
  async deleteData(
    url: string,
    headers?: Record<string, string>
  ): Promise<void> {
    await this.delete(url, headers);
  }

  /**
   * DELETE request that returns data
   * Unwraps envelope and validates response data
   */
  async deleteWithData<T>(
    url: string,
    responseSchema: z.ZodType<T>,
    headers?: Record<string, string>
  ): Promise<T> {
    const response = await this.delete(url, headers);

    const envelope = successEnvelopeSchema(responseSchema).parse(response.data);

    return envelope.data;
  }

  /**
   * GET paginated data
   */
  async getPaginated<T>(
    url: string,
    itemSchema: z.ZodType<T>,
    headers?: Record<string, string>
  ): Promise<PaginatedResult<T>> {
    const response = await this.get(url, headers);
    
    const envelope = paginatedEnvelopeSchema(itemSchema).parse(response.data);
    
    return {
      items: envelope.data,
      pagination: envelope.pagination ?? {
        total: envelope.data.length,
        page: 1,
        limit: envelope.data.length,
        totalPages: 1,
        hasNext: false,
        hasPrev: false
      }
    };
  }

  /**
   * POST/PUT batch operations
   */
  async postBatch<T>(
    url: string,
    body: unknown,
    itemSchema: z.ZodType<T>,
    headers?: Record<string, string>
  ): Promise<BatchResult<T>> {
    const response = await this.post(url, body, headers);

    const envelope = batchEnvelopeSchema(itemSchema).parse(response.data);

    return envelope.data;
  }

  setAuthToken(token: string) {
    this.defaultHeaders['Authorization'] = `Bearer ${token}`;
  }

  removeAuthToken() {
    delete this.defaultHeaders['Authorization'];
  }
}

// Configure API base URL based on environment
const API_BASE_URL = import.meta.env['VITE_API_URL'] || 'http://localhost:3001/api';

export const httpClient = new HttpClient({
  baseURL: API_BASE_URL
});

// Session Manager Integration
export function configureHttpClientWithSessionManager(sessionManager: TokenProvider) {
  // Configure the HTTP client to work with the session manager
  // This allows automatic token injection and refresh handling
  const originalGet = httpClient.get.bind(httpClient);
  const originalPost = httpClient.post.bind(httpClient);
  const originalPut = httpClient.put.bind(httpClient);
  const originalDelete = httpClient.delete.bind(httpClient);

  // Build auth headers with proactive token refresh
  async function buildAuthHeaders(sessionManager: TokenProvider): Promise<Record<string, string>> {
    const token = await sessionManager.getValidAccessToken(); // Pre-refresh if needed
    return token ? { Authorization: `Bearer ${token}` } : {};
  }

  // Token injection for methods without data (GET, DELETE)
  const injectNoData = async <T>(
    originalMethod: (url: string, headers?: Record<string, string>) => Promise<ApiResponse<T>>,
    url: string,
    headers: Record<string, string> | undefined,
    sessionManager: TokenProvider
  ) => {
    const authHeaders = await buildAuthHeaders(sessionManager);
    const requestHeaders = { ...headers, ...authHeaders };

    const response = await originalMethod(url, requestHeaders);
    if (response && response.data) {
      response.data = httpClient.applyResponseTransformation(response.data, url) as T;
    }
    return response;
  };

  // Token injection for methods with data (POST, PUT)
  const injectWithData = async <T>(
    originalMethod: (url: string, data?: unknown, headers?: Record<string, string>) => Promise<ApiResponse<T>>,
    url: string,
    data: unknown,
    headers: Record<string, string> | undefined,
    sessionManager: TokenProvider
  ) => {
    const authHeaders = await buildAuthHeaders(sessionManager);
    const requestHeaders = { ...headers, ...authHeaders };

    const response = await originalMethod(url, data, requestHeaders);
    if (response && response.data) {
      response.data = httpClient.applyResponseTransformation(response.data, url) as T;
    }
    return response;
  };

  // Override methods with correct signatures
  httpClient.get = async function<T = unknown>(url: string, headers?: Record<string, string>) {
    return injectNoData<T>(originalGet, url, headers, sessionManager);
  };

  httpClient.delete = async function<T = unknown>(url: string, headers?: Record<string, string>) {
    return injectNoData<T>(originalDelete, url, headers, sessionManager);
  };

  httpClient.post = async function<T = unknown>(url: string, data?: unknown, headers?: Record<string, string>) {
    return injectWithData<T>(originalPost, url, data, headers, sessionManager);
  };

  httpClient.put = async function<T = unknown>(url: string, data?: unknown, headers?: Record<string, string>) {
    return injectWithData<T>(originalPut, url, data, headers, sessionManager);
  };
}

/**
 * API Response Transformation Layer
 *
 * Automatic JSON deserialization with date field detection.
 *
 * Architecture principles:
 * - API layer owns serialization/deserialization
 * - Business logic works with proper types
 * - Single responsibility: transform at API boundary
 */

import { env } from '@shared/config';

// Date field detection using naming patterns and explicit mappings
const DATE_FIELD_PATTERNS = [
  /.*[Dd]ate.*$/,        // createdDate, lastDate, updateDate
  /.*[Aa]t$/,           // createdAt, updatedAt, lastActivity
  /.*[Ee]xpiry$/,       // tokenExpiry, accessTokenExpiry
  /.*[Ee]xpires$/,      // expires, sessionExpires
  /.*[Tt]imestamp$/     // timestamp, lastTimestamp
];

// Exclude fields that match date patterns but are NOT dates
const DATE_FIELD_EXCLUSIONS = [
  /.*executionTime$/,    // API execution time in milliseconds
  /.*responseTime$/,     // Response time metrics
  /.*duration$/,         // Duration values
  /.*timeout$/,          // Timeout values
  /.*interval$/,         // Interval values
  /.*delay$/,            // Delay values
];

/**
 * Explicit date field mappings for critical types
 * Ensures bulletproof transformation for known types
 */
const EXPLICIT_DATE_FIELDS: Record<string, Set<string>> = {
  'TokenPair': new Set(['accessTokenExpiry', 'refreshTokenExpiry']),
  'RefreshResponse': new Set(['accessTokenExpiry']),
  'LoginResponse': new Set(['createdAt', 'accessTokenExpiry', 'refreshTokenExpiry', 'timestamp']),
  'User': new Set(['lastActivity']),
  'Person': new Set(['createdAt', 'updatedAt']),
  'ActiveSession': new Set(['createdAt', 'lastUsedAt', 'expiresAt']),
  'TubeData': new Set(['createdAt', 'updatedAt', 'date']),
  'Researcher': new Set(['createdAt', 'updatedAt']),
  'TankConfiguration': new Set(['createdAt', 'updatedAt']),
  'LabConfiguration': new Set(['createdAt', 'updatedAt']),
  'ConfigurationResponse': new Set(['createdAt', 'updatedAt']), // Handles nested configs (labs, tanks, racks, boxes)
  'UserSettings': new Set([]), // User settings has no date fields
  'UserSettingsResponse': new Set([]), // Response envelope for user settings
  'AdminUser': new Set(['createdAt', 'lastActivity']),
  'SystemMetrics': new Set(['lastBackup']),
  'AuditLogEntry': new Set(['timestamp']),
  'SocketEventPayload': new Set(['timestamp', 'updatedAt']), // Socket.IO configuration_updated events
  'ConfigurationUpdateEvent': new Set(['timestamp', 'updatedAt']) // Socket.IO configuration events
};

// Type-safe date field detection with exclusion patterns to prevent false positives
function isDateField(key: string, typeName?: string): boolean {
  // Check exclusions first - prevents false positives
  if (DATE_FIELD_EXCLUSIONS.some(pattern => pattern.test(key))) {
    return false;
  }

  // Check explicit mapping (most reliable)
  if (typeName && EXPLICIT_DATE_FIELDS[typeName] !== undefined) {
    // Type has explicit mapping - trust it completely
    return EXPLICIT_DATE_FIELDS[typeName].has(key);
  }

  // Fallback to pattern matching (legacy behavior)
  const matched = DATE_FIELD_PATTERNS.some(pattern => pattern.test(key));

  // Warn in development when using regex fallback
  if (env.isDev() && matched) {
    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Debug logging: empty typeName should display as 'unknown'
    // eslint-disable-next-line no-console -- Warning logging for production monitoring
    console.warn(`⚠️ [API TRANSFORMER] Using regex fallback for field "${key}" in type "${typeName ?? 'unknown'}". Consider adding explicit mapping to EXPLICIT_DATE_FIELDS.`);
  }

  return matched;
}

// Only transform strings and numbers to dates, preserving booleans/arrays/objects
function isValidDateValue(value: any): boolean {
  // Only strings and numbers can be transformed to dates
  // Explicitly exclude booleans, null, objects, arrays
  return (typeof value === 'string' || typeof value === 'number') && value !== null;
}

/**
 * Safe date parsing with validation
 * Handles multiple date formats from different APIs
 */
function parseDate(value: any): Date | null {
  if (!value) return null;
  
  // Already a Date object
  if (value instanceof Date) return value;
  
  // Parse string/number to Date
  if (typeof value === 'string' || typeof value === 'number') {
    const parsed = new Date(value);
    
    // Validate parsed date
    if (isNaN(parsed.getTime())) {
      // eslint-disable-next-line no-console -- Warning logging for production monitoring
      console.warn(`[API TRANSFORMER] Invalid date value: ${value}`);
      return null;
    }
    
    return parsed;
  }
  
  // eslint-disable-next-line no-console -- Warning logging for production monitoring
  console.warn(`[API TRANSFORMER] Unparseable date type: ${typeof value}, value:`, value);
  return null;
}

// Deep transform with date field conversion, recursively handling nested objects and arrays
function transformObject(obj: any, typeName?: string): any {
  if (obj === null || obj === undefined) return obj;
  
  // Handle arrays
  if (Array.isArray(obj)) {
    return obj.map(item => transformObject(item, typeName));
  }
  
  // Handle primitive types - PRESERVE EXACTLY AS-IS
  if (typeof obj !== 'object') return obj;
  
  // Transform object properties
  const transformed: any = {};
  
  for (const [key, value] of Object.entries(obj)) {
    // Only transform if it's a date field AND a string/number
    if (isDateField(key, typeName) && isValidDateValue(value)) {
      // Transform date field
      const parsedDate = parseDate(value);
      transformed[key] = parsedDate;
    } else if (value && typeof value === 'object') {
      // Recursively transform nested objects
      transformed[key] = transformObject(value, typeName);
    } else {
      // Preserve primitive values exactly as-is (boolean, string, number, null)
      transformed[key] = value;
    }
  }
  
  return transformed;
}

/**
 * Main response transformer for HTTP client integration
 *
 * @param response - Raw API response data
 * @param typeName - Optional type hint for explicit field mapping
 * @returns Transformed response with proper Date objects
 */
export function transformApiResponse<T = any>(response: any, typeName?: string): T {
  const transformed = transformObject(response, typeName);
  return transformed as T;
}

/**
 * Type-specific transformers for common API responses
 * Provides explicit type safety for critical business objects
 */
export const ResponseTransformers = {
  TokenPair: (data: any) => transformApiResponse(data, 'TokenPair'),
  RefreshResponse: (data: any) => transformApiResponse(data, 'RefreshResponse'),
  LoginResponse: (data: any) => {
    const transformed = transformApiResponse(data, 'LoginResponse');
    // Ensure nested TokenPair is also transformed
    if (transformed.tokens) {
      transformed.tokens = transformApiResponse(transformed.tokens, 'TokenPair');
    }
    return transformed;
  },
  User: (data: any) => transformApiResponse(data, 'User'),
  Person: (data: any) => transformApiResponse(data, 'Person'),
  ActiveSession: (data: any) => transformApiResponse(data, 'ActiveSession'),
  TubeData: (data: any) => transformApiResponse(data, 'TubeData'),
  Researcher: (data: any) => transformApiResponse(data, 'Researcher'),
  AdminUser: (data: any) => transformApiResponse(data, 'AdminUser'),
  SystemMetrics: (data: any) => transformApiResponse(data, 'SystemMetrics'),
  AuditLogEntry: (data: any) => transformApiResponse(data, 'AuditLogEntry')
} as const;

/**
 * Development utilities for debugging transformations
 */
export const TransformationDebug = {
  /**
   * Log all detected date fields in an object
   */
  logDateFields(obj: any, typeName?: string): void {
    if (typeof obj !== 'object' || !obj) return;

    const _dateFields = Object.keys(obj).filter(key => isDateField(key, typeName));
  },
  
  /**
   * Test date field detection
   */
  testFieldDetection(fieldName: string, typeName?: string): boolean {
    return isDateField(fieldName, typeName);
  },
  
  /**
   * Validate transformation result
   */
  validateDates(obj: any): { valid: number; invalid: number; fields: string[] } {
    const result = { valid: 0, invalid: 0, fields: [] as string[] };
    
    function checkObject(current: any, path = ''): void {
      if (!current || typeof current !== 'object') return;
      
      for (const [key, value] of Object.entries(current)) {
        const fullPath = path ? `${path}.${key}` : key;
        
        if (value instanceof Date) {
          if (isNaN(value.getTime())) {
            result.invalid++;
            result.fields.push(`${fullPath} (invalid)`);
          } else {
            result.valid++;
            result.fields.push(`${fullPath} (valid)`);
          }
        } else if (value && typeof value === 'object') {
          checkObject(value, fullPath);
        }
      }
    }
    
    checkObject(obj);
    return result;
  }
};

/**
 * Export for development debugging
 */
if (env.isDev()) {
  (window as any).__ODYSSEUS_API_TRANSFORMER_DEBUG__ = TransformationDebug;
}

/**
 * Cache Warming Service
 * Phase 3 Step 2: Intelligent prefetching and cache warming strategies
 * 
 * Proactively loads commonly needed data to improve perceived performance.
 * Integrates with Socket → Query Cache Bridge for optimal real-time updates.
 */

import { NAMING_PATTERNS } from '@odysseus/shared-schemas';


import { DOMAIN_QUERY_OPTIONS } from '@app/queryClient';
import { queryKeys } from '@app/queryKeys';

import type { QueryClient } from '@tanstack/react-query';

/**
 * Cache warming priorities based on user behavior patterns
 */
export enum WarmingPriority {
  CRITICAL = 0,    // Load immediately (blocking)
  HIGH = 1,        // Load early (background, high priority)
  MEDIUM = 2,      // Load after critical data
  LOW = 3,         // Load when idle
}

/**
 * Cache warming strategy configuration
 */
interface WarmingStrategy {
  priority: WarmingPriority;
  prefetchTimeout?: number;    // Max time to wait for prefetch
  retryOnError?: boolean;      // Retry if prefetch fails
  dependencies?: string[];     // Other data to load first
}

/**
 * Cache Warming Service
 * 
 * Intelligently prefetches data based on user patterns and app state
 */
export class CacheWarmingService {
  private queryClient: QueryClient;
  private isWarming = false;
  private warmingQueue: Array<{ queryKey: any[]; strategy: WarmingStrategy }> = [];

  constructor(queryClient: QueryClient) {
    this.queryClient = queryClient;
  }

  /**
   * Start the cache warming process during app bootstrap
   */
  public async startWarming(): Promise<void> {
    if (this.isWarming) {
      // eslint-disable-next-line no-console -- Info logging for operational visibility
      console.log('🔥 [CacheWarming] Already in progress, skipping');
      return;
    }

    this.isWarming = true;
    // eslint-disable-next-line no-console -- Info logging for operational visibility
    console.log('🔥 [CacheWarming] Starting intelligent cache warming');

    try {
      // Phase 1: Critical data (blocking)
      await this.warmCriticalData();
      
      // Phase 2: High priority data (background)
      this.warmHighPriorityData();
      
      // Phase 3: Medium priority data (when critical data is loaded)
      setTimeout(() => this.warmMediumPriorityData(), 1000);
      
      // Phase 4: Low priority data (when app is idle)
      this.scheduleIdleWarming();
      
    } catch (error) {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('❌ [CacheWarming] Failed to start warming:', error);
    } finally {
      this.isWarming = false;
    }
  }

  /**
   * Warm critical data that users need immediately
   */
  private async warmCriticalData(): Promise<void> {
    // eslint-disable-next-line no-console -- Info logging for operational visibility
    console.log('🔥 [CacheWarming] Loading critical data');
    
    const criticalQueries = [
      // All tubes - base list that UI will reuse for filtered views
      {
        queryKey: queryKeys.tubes.lists(),
        queryFn: async () => {
          const response = await fetch('/api/tubes');
          return response.json();
        },
        ...DOMAIN_QUERY_OPTIONS.tubes
      } as const,
      
      // All researchers - single canonical query that UI will reuse
      {
        queryKey: queryKeys.researchers.lists(),
        queryFn: async () => {
          const response = await fetch('/api/researchers');
          return response.json();
        },
        ...DOMAIN_QUERY_OPTIONS.researchers
      } as const,
      
      // Lab configuration - needed for navigation
      {
        queryKey: ['laboratory', 'configuration'] as const,
        queryFn: async () => {
          const response = await fetch('/api/laboratory/configuration');
          return response.json();
        },
        ...DOMAIN_QUERY_OPTIONS.configuration
      } as const
    ] as const;

    // Load critical data in parallel with ensureQueryData (blocks until data loaded)
    const promises = criticalQueries.map(query => 
      this.queryClient.ensureQueryData(query as any).catch(error => {
        // eslint-disable-next-line no-console -- Warning logging for production monitoring
        console.warn(`Failed to load critical data for ${query.queryKey}:`, error);
        return null;
      })
    );

    await Promise.all(promises);
    // eslint-disable-next-line no-console -- Info logging for operational visibility
    console.log('[CacheWarming] Critical data loaded and cached');
  }

  /**
   * Warm high priority data in the background
   */
  private warmHighPriorityData(): void {
    // eslint-disable-next-line no-console -- Info logging for operational visibility
    console.log('🔥 [CacheWarming] Loading high priority data');

    // Get user's current location context
    const currentLocation = this.getCurrentUserLocation();
    
    if (currentLocation) {
      // Prefetch tubes for current location
      this.queryClient.prefetchQuery({
        queryKey: queryKeys.tubes.location(
          currentLocation.tankId, 
          currentLocation.rackId, 
          currentLocation.boxId
        ),
        queryFn: async () => {
          const response = await fetch(
            `/api/tubes?tankId=${currentLocation.tankId}&rackId=${currentLocation.rackId}&boxId=${currentLocation.boxId}`
          );
          return response.json();
        },
        ...DOMAIN_QUERY_OPTIONS.tubes
      }).catch(error => {
        // eslint-disable-next-line no-console -- Warning logging for production monitoring
        console.warn('Failed to prefetch location tubes:', error);
      });
    }

    // Prefetch statistics (commonly viewed)
    this.queryClient.prefetchQuery({
      queryKey: queryKeys.tubes.stats(),
      queryFn: async () => {
        const response = await fetch('/api/tubes/statistics');
        return response.json();
      },
      ...DOMAIN_QUERY_OPTIONS.statistics
    }).catch(error => {
      // eslint-disable-next-line no-console -- Warning logging for production monitoring
      console.warn('Failed to prefetch statistics:', error);
    });
  }

  /**
   * Warm medium priority data after initial load
   */
  private warmMediumPriorityData(): void {
    // eslint-disable-next-line no-console -- Info logging for operational visibility
    console.log('🔥 [CacheWarming] Loading medium priority data');

    // Prefetch adjacent locations (user might navigate there)
    const currentLocation = this.getCurrentUserLocation();
    if (currentLocation) {
      this.prefetchAdjacentLocations(currentLocation);
    }

    // Prefetch recent search results from history
    this.prefetchRecentSearches();
  }

  /**
   * Schedule low priority warming during idle time
   */
  private scheduleIdleWarming(): void {
    // Use requestIdleCallback if available
    if ('requestIdleCallback' in window) {
      (window as any).requestIdleCallback(() => {
        this.warmLowPriorityData();
      }, { timeout: 5000 });
    } else {
      // Fallback for browsers without requestIdleCallback
      setTimeout(() => this.warmLowPriorityData(), 5000);
    }
  }

  /**
   * Warm low priority data when system is idle
   */
  private warmLowPriorityData(): void {
    // eslint-disable-next-line no-console -- Info logging for operational visibility
    console.log('🔥 [CacheWarming] Loading low priority data');

    // Skip - researchers already loaded in critical phase
    // No need to fetch includeInactive separately unless specifically needed

    // Prefetch system configuration
    this.queryClient.prefetchQuery({
      queryKey: ['system', 'configuration'],
      queryFn: async () => {
        const response = await fetch('/api/system/configuration');
        return response.json();
      },
      ...DOMAIN_QUERY_OPTIONS.configuration
    }).catch(error => {
      // eslint-disable-next-line no-console -- Warning logging for production monitoring
      console.warn('Failed to prefetch system config:', error);
    });
  }

  /**
   * Smart prefetching based on navigation patterns
   */
  public prefetchForNavigation(targetLocation: { tankId: string; rackId: string; boxId: string }): void {
    // eslint-disable-next-line no-console -- Info logging for operational visibility
    console.log('🎯 [CacheWarming] Prefetching for navigation to:', targetLocation);

    // Prefetch tubes for target location
    this.queryClient.prefetchQuery({
      queryKey: queryKeys.tubes.location(
        targetLocation.tankId,
        targetLocation.rackId,
        targetLocation.boxId
      ),
      queryFn: async () => {
        const response = await fetch(
          `/api/tubes?tankId=${targetLocation.tankId}&rackId=${targetLocation.rackId}&boxId=${targetLocation.boxId}`
        );
        return response.json();
      },
      ...DOMAIN_QUERY_OPTIONS.tubes
    }).catch(error => {
      // eslint-disable-next-line no-console -- Warning logging for production monitoring
      console.warn('Failed to prefetch navigation target:', error);
    });

    // Prefetch adjacent locations as well
    this.prefetchAdjacentLocations(targetLocation);
  }

  /**
   * Prefetch data for locations adjacent to the current one
   */
  private prefetchAdjacentLocations(location: { tankId: string; rackId: string; boxId: string }): void {
    // This is a simplified example - real implementation would calculate adjacent boxes/racks
    const adjacentBoxes = this.getAdjacentBoxes(location);
    
    adjacentBoxes.forEach(box => {
      this.queryClient.prefetchQuery({
        queryKey: queryKeys.tubes.location(box.tankId, box.rackId, box.boxId),
        queryFn: async () => {
          const response = await fetch(
            `/api/tubes?tankId=${box.tankId}&rackId=${box.rackId}&boxId=${box.boxId}`
          );
          return response.json();
        },
        ...DOMAIN_QUERY_OPTIONS.tubes,
        staleTime: DOMAIN_QUERY_OPTIONS.tubes.staleTime / 2, // Shorter stale time for prefetched data
      }).catch(error => {
        // Silently fail for adjacent locations (not critical)
        // eslint-disable-next-line no-console -- Debug logging for non-critical failures
        console.debug('Adjacent location prefetch failed:', error);
      });
    });
  }

  /**
   * Prefetch recent search results from user history
   */
  private prefetchRecentSearches(): void {
    // Get recent search queries from local storage or user preferences
    const recentSearches = this.getRecentSearchQueries();
    
    recentSearches.slice(0, 3).forEach(searchQuery => {
      this.queryClient.prefetchQuery({
        queryKey: queryKeys.search.results(searchQuery.query, searchQuery.filters),
