/**
 * Error Boundary Component
 * 
 * Professional error boundary with retry functionality and proper error reporting
 * Handles runtime errors in React component tree
 */

import type { ReactNode, ErrorInfo } from 'react';
import React, { Component, useState, useCallback, useEffect, forwardRef, createElement } from 'react';

import { env } from '@shared/config';

// Error boundary state
interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
  errorId: string | null;
}

// Error boundary props
export interface ErrorBoundaryProps {
  children: ReactNode;
  
  // Error handling
  fallback?: React.ComponentType<{
    error: Error;
    errorInfo: ErrorInfo | null;
    retry: () => void;
    errorId: string;
  }> | ((props: {
    error: Error;
    errorInfo: ErrorInfo | null;
    retry: () => void;
    errorId: string;
  }) => ReactNode);
  
  // Callbacks
  onError?: (error: Error, errorInfo: ErrorInfo, errorId: string) => void;
  onRetry?: () => void;
  
  // Configuration
  isolate?: boolean; // Prevent error propagation
  level?: 'page' | 'section' | 'component'; // Error boundary level
  
  // Debugging
  name?: string; // For debugging purposes
}

// Default error fallback component
interface DefaultErrorFallbackProps {
  error: Error;
  errorInfo: ErrorInfo | null;
  retry: () => void;
  errorId: string;
  level?: string;
  name?: string;
}

const DefaultErrorFallback: React.FC<DefaultErrorFallbackProps> = ({ error, retry, errorId, level = 'component', name }) => {
  const isDevelopment = env.isDev();
  
  return (
    <div
      className="flex flex-col items-center justify-center p-8 min-h-[200px] border-2 border-dashed border-error-300 bg-error-50 rounded-lg"
      role="alert"
      // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Cascading fallback for display: empty name falls through to level
      aria-label={`Error in ${name || level}`}
    >
      <div className="text-error-500 mb-4">
        <svg className="w-16 h-16 mx-auto" viewBox="0 0 24 24" fill="none" stroke="currentColor">
          <circle cx="12" cy="12" r="10" />
          <line x1="15" y1="9" x2="9" y2="15" />
          <line x1="9" y1="9" x2="15" y2="15" />
        </svg>
      </div>
      
      <h2 className="text-xl font-bold text-error-900 mb-2">
        Something went wrong
      </h2>
      
      <p className="text-error-700 text-center mb-4 max-w-md">
        {isDevelopment 
          ? error.message 
          : `An error occurred while rendering this ${level}.`
        }
      </p>
      
      {isDevelopment && (
        <details className="mb-4 max-w-2xl w-full">
          <summary className="cursor-pointer text-error-600 font-medium mb-2">
            Error Details
          </summary>
          <div className="bg-error-100 p-4 rounded border text-sm font-mono text-error-800 overflow-auto max-h-40">
            <div className="mb-2">
              <strong>Error ID:</strong> {errorId}
            </div>
            <div className="mb-2">
              {/* eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Debug display: empty name shows 'Unknown' */}
              <strong>Component:</strong> {name || 'Unknown'}
            </div>
            <div className="mb-2">
              <strong>Message:</strong> {error.message}
            </div>
            {error.stack && (
              <div>
                <strong>Stack:</strong>
                <pre className="mt-1 whitespace-pre-wrap">{error.stack}</pre>
              </div>
            )}
          </div>
        </details>
      )}
      
      <div className="flex space-x-3">
        <button
          onClick={retry}
          className="btn px-4 py-2 bg-error-600 text-white rounded-md hover:bg-error-700 transition-colors"
        >
          Try Again
        </button>

        {isDevelopment && (
          <button
            onClick={() => {
              // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Debug logging: empty name shows 'Unknown'
              // eslint-disable-next-line no-console -- Development-only error logging (environment-gated)
              console.group(`🚨 Error Boundary: ${name ?? 'Unknown'}`);
              // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
              console.error('Error:', error);
              // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
              console.error('Error ID:', errorId);
              // eslint-disable-next-line no-console -- Development-only error logging (environment-gated)
              console.groupEnd();
            }}
            className="btn px-4 py-2 bg-neutral-600 text-white rounded-md hover:bg-neutral-700 transition-colors"
          >
            Log to Console
          </button>
        )}
      </div>
      
      {level === 'page' && (
        <button
          onClick={() => window.location.reload()}
          className="mt-3 text-error-600 hover:text-error-800 underline text-sm"
        >
          Reload Page
        </button>
      )}
    </div>
  );
};

// Generate unique error ID
const generateErrorId = (): string => {
  return `err_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
};

// Main Error Boundary class component
export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  private errorId: string = '';
  
  constructor(props: ErrorBoundaryProps) {
    super(props);
    
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
      errorId: null,
    };
  }
  
  static getDerivedStateFromError(error: Error): Partial<ErrorBoundaryState> {
    const errorId = generateErrorId();
    
    return {
      hasError: true,
      error,
      errorId,
    };
  }
  
  override componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Empty error ID is invalid, generate unique ID
    const errorId = this.state.errorId || generateErrorId();
    
    this.setState({
      errorInfo,
      errorId,
    });
    
    // Log error for monitoring
    if (env.isDev()) {
      // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Debug logging: empty name shows 'Unknown'
      // eslint-disable-next-line no-console -- Development-only error logging (environment-gated)
      console.group(`🚨 Error Boundary Caught Error: ${this.props.name ?? 'Unknown'}`);
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('Error:', error);
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('Error Info:', errorInfo);
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('Error ID:', errorId);
      // eslint-disable-next-line no-console -- Development-only error logging (environment-gated)
      console.groupEnd();
    }
    
    // Call error callback
    this.props.onError?.(error, errorInfo, errorId);
    
    // In production, you might want to send this to an error reporting service
    if (env.isProd()) {
      // Example: Send to error reporting service
      // errorReportingService.captureException(error, {
      //   tags: {
      //     errorBoundary: this.props.name || 'unknown',
      //     errorId,
      //   },
      //   extra: errorInfo,
      // });
    }
  }
  
  handleRetry = () => {
    this.props.onRetry?.();
    
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
      errorId: null,
    });
  };
  
  override render() {
    if (this.state.hasError && this.state.error) {
      const FallbackComponent = this.props.fallback ?? DefaultErrorFallback;
      
      const fallbackProps = {
        error: this.state.error,
        errorInfo: this.state.errorInfo,
        retry: this.handleRetry,
        errorId: this.state.errorId!,
        level: this.props.level,
        name: this.props.name,
      };
      
      // Handle function vs component fallback
      if (typeof FallbackComponent === 'function') {
        return <FallbackComponent {...fallbackProps} />;
      } else {
        return createElement(FallbackComponent, fallbackProps);
      }
    }
    
    return this.props.children;
  }
}

// Hook for handling errors in functional components
export const useErrorHandler = () => {
  const [error, setError] = useState<Error | null>(null);

  const handleError = useCallback((error: Error) => {
    setError(error);

    // Log error
    if (env.isDev()) {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error('Handled error:', error);
    }
  }, []);

  const clearError = useCallback(() => {
    setError(null);
  }, []);

  // Re-throw error to be caught by error boundary
  useEffect(() => {
    if (error) {
      throw error;
    }
  }, [error]);

  return { handleError, clearError, error };
};

// Higher-order component for error boundary
export const withErrorBoundary = <P extends object>(
  Component: React.ComponentType<P>,
  errorBoundaryConfig?: Omit<ErrorBoundaryProps, 'children'>
) => {
  const WrappedComponent = forwardRef<any, P>((props, ref) => (
    <ErrorBoundary {...errorBoundaryConfig}>
      <Component {...(props as any)} ref={ref} />
    </ErrorBoundary>
  ));

  // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Cascading fallback for React displayName
  WrappedComponent.displayName = `withErrorBoundary(${Component.displayName || Component.name})`;

  return WrappedComponent;
};

// Error boundary for specific scenarios
export const PageErrorBoundary: React.FC<Omit<ErrorBoundaryProps, 'level'>> = (props) => (
  <ErrorBoundary {...props} level="page" />
);

export const SectionErrorBoundary: React.FC<Omit<ErrorBoundaryProps, 'level'>> = (props) => (
  <ErrorBoundary {...props} level="section" />
);

export const ComponentErrorBoundary: React.FC<Omit<ErrorBoundaryProps, 'level'>> = (props) => (
  <ErrorBoundary {...props} level="component" />
);

/**
 * Suspense Boundary Component
 * 
 * Professional Suspense boundary with proper error handling and loading states
 * Provides consistent lazy loading experience across the application
 */

import type { ReactNode } from 'react';
import React, { Suspense, useCallback, useState, forwardRef } from 'react';

import { env } from '@shared/config';

import { ErrorBoundary, type ErrorBoundaryProps } from './ErrorBoundary';

// Suspense boundary configuration
interface SuspenseBoundaryProps {
  children: ReactNode;
  
  // Loading fallback
  fallback?: ReactNode;
  
  // Error handling
  onError?: (error: Error, errorInfo: React.ErrorInfo) => void;
  errorFallback?: ErrorBoundaryProps['fallback'];
  
  // Accessibility
  'aria-label'?: string;
  
  // Performance
  timeout?: number; // Max time before showing error
  
  // Styling
  className?: string;
  
  // Debug info
  name?: string; // For debugging lazy loading
}

// Default loading fallback
interface DefaultLoadingFallbackProps {
  name?: string;
  className?: string;
  'aria-label'?: string;
}

const DefaultLoadingFallback: React.FC<DefaultLoadingFallbackProps> = ({ name, className = '', 'aria-label': ariaLabel }) => (
  <div 
    className={`flex items-center justify-center p-8 ${className}`}
    role="status"
    aria-label={ariaLabel ?? `Loading ${name ?? 'component'}...`}
  >
    <div className="flex items-center space-x-3">
      <div className="animate-spin rounded-full h-6 w-6 border-2 border-primary-600 border-t-transparent" />
      <span className="text-neutral-600 text-sm">
        {name ? `Loading ${name}...` : 'Loading...'}
      </span>
    </div>
  </div>
);

// Main Suspense Boundary component
export const SuspenseBoundary: React.FC<SuspenseBoundaryProps> = ({
  children,
  fallback,
  onError,
  errorFallback,
  'aria-label': ariaLabel,
  timeout: _timeout = 10000, // 10 second timeout
  className = '',
  name,
}) => {
  // Default error fallback
  const defaultErrorFallback = useCallback(
    ({ error, retry }: { error: Error; retry: () => void }) => (
      <div
        className={`flex flex-col items-center justify-center p-8 text-center ${className}`}
        role="alert"
        aria-label={`Error loading ${name ?? 'component'}`}
      >
        <div className="text-error-500 mb-4">
          <svg className="w-12 h-12 mx-auto" viewBox="0 0 24 24" fill="none" stroke="currentColor">
            <circle cx="12" cy="12" r="10" />
            <line x1="15" y1="9" x2="9" y2="15" />
            <line x1="9" y1="9" x2="15" y2="15" />
          </svg>
        </div>

        <h3 className="text-lg font-semibold text-neutral-900 mb-2">
          Failed to load {name ?? 'component'}
        </h3>

        <p className="text-neutral-600 mb-4 max-w-sm">
          {error.message || 'Something went wrong while loading this component.'}
        </p>

        <button
          onClick={retry}
          className="btn px-4 py-2 bg-primary-600 text-white rounded-md hover:bg-primary-700 transition-colors"
        >
          Try Again
        </button>
      </div>
    ),
    [className, name]
  );
  
  // Default loading fallback with timeout
  const loadingFallback = fallback ?? (
    <DefaultLoadingFallback
      name={name}
      className={className}
      aria-label={ariaLabel}
    />
  );

  // Error boundary configuration - omit children since we use JSX children pattern
  const errorBoundaryConfig: Omit<ErrorBoundaryProps, 'children'> = {
    fallback: errorFallback ?? defaultErrorFallback,
    onError: (error, errorInfo) => {
      // Log error for debugging
      if (env.isDev()) {
        // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Debug logging: empty name shows 'Unknown Component'
        // eslint-disable-next-line no-console -- Development-only error logging (environment-gated)
        console.group(`🚨 Lazy Loading Error: ${name ?? 'Unknown Component'}`);
        // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
        console.error('Error:', error);
        // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
        console.error('Error Info:', errorInfo);
        // eslint-disable-next-line no-console -- Development-only error logging (environment-gated)
        console.groupEnd();
      }
      
      // Call custom error handler
      onError?.(error, errorInfo);
    },
    isolate: true, // Prevent error propagation to parent boundaries
  };
  
  return (
    <ErrorBoundary {...errorBoundaryConfig}>
      <Suspense fallback={loadingFallback}>
        {children}
      </Suspense>
    </ErrorBoundary>
  );
};

// Convenience wrapper for lazy components
export const withSuspenseBoundary = <P extends object>(
  LazyComponent: React.ComponentType<P>,
  config?: Omit<SuspenseBoundaryProps, 'children'>
) => {
  const WrappedComponent = forwardRef<any, P>((props, ref) => (
    <SuspenseBoundary {...config}>
      <LazyComponent {...(props as any)} ref={ref} />
    </SuspenseBoundary>
  ));

  // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Cascading fallback for React displayName
  WrappedComponent.displayName = `withSuspenseBoundary(${LazyComponent.displayName || LazyComponent.name})`;

  return WrappedComponent;
};

// Hook for managing lazy loading state
export const useLazyLoadingState = (componentName?: string) => {
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const handleLoadComplete = useCallback(() => {
    setIsLoading(false);
    setError(null);
  }, []);

  const handleLoadError = useCallback((error: Error) => {
    setIsLoading(false);
    setError(error);

    if (env.isDev()) {
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error(`Failed to load lazy component: ${componentName}`, error);
    }
  }, [componentName]);

  const retry = useCallback(() => {
    setIsLoading(true);
    setError(null);
    // Component will re-mount and attempt to load again
  }, []);

  return {
    isLoading,
    error,
    handleLoadComplete,
    handleLoadError,
    retry,
  };
};

// Preloading utilities for better UX
export const preloadLazyComponent = async (
  importFn: () => Promise<{ default: React.ComponentType<any> }>
): Promise<void> => {
  try {
    await importFn();
  } catch (error) {
    if (env.isDev()) {
      // eslint-disable-next-line no-console -- Warning logging for production monitoring
      console.warn('Failed to preload lazy component:', error);
    }
  }
};

// Batch preloader for multiple components
export const preloadLazyComponents = async (
  importFns: Array<() => Promise<{ default: React.ComponentType<any> }>>
): Promise<void> => {
  try {
    await Promise.all(importFns.map(preloadLazyComponent));
  } catch (error) {
    if (env.isDev()) {
      // eslint-disable-next-line no-console -- Warning logging for production monitoring
      console.warn('Failed to preload some lazy components:', error);
    }
  }
};

/**
 * Grid Component
 * 
 * Flexible CSS Grid layout primitive following design system tokens
 * Supports responsive breakpoints and consistent spacing
