// Table row data
export interface TableRow {
  id: string | number;
  [key: string]: any;
}

// Sort configuration
export interface SortConfig {
  columnId: string;
  direction: 'asc' | 'desc';
}

// Table component props
export interface TableProps<T = TableRow> {
  // Data
  columns: TableColumn<T>[];
  data: T[];
  
  // Features
  sortable?: boolean;
  selectable?: boolean;
  multiSelect?: boolean;
  striped?: boolean;
  hoverable?: boolean;
  
  // State
