// Checkbox component for selection
interface TableCheckboxProps {
  checked: boolean;
  indeterminate?: boolean;
  onChange: (checked: boolean) => void;
  'aria-label'?: string;
}

const TableCheckbox: React.FC<TableCheckboxProps> = ({ checked, indeterminate, onChange, 'aria-label': ariaLabel }) => (
  <input
    type="checkbox"
    checked={checked}
    ref={input => {
      if (input) input.indeterminate = Boolean(indeterminate);
    }}
    onChange={e => onChange(e.target.checked)}
    className="rounded border-neutral-300 text-primary-600 focus:ring-primary-500"
    aria-label={ariaLabel}
  />
);

// Table Header component
export const TableHeader = <T,>({ 
  columns, 
  className = '' 
}: { 
  columns: TableColumn<T>[];
  className?: string;
}) => {
  const { 
    selectable, 
    multiSelect, 
    selectedRows, 
    onSelectionChange, 
    sortConfig, 
    onSort 
  } = useTableContext();
  
  const handleSelectAll = (checked: boolean) => {
    // This would need access to all row IDs
    // In a real implementation, you'd pass this through context
    onSelectionChange(checked ? [] : []); // Simplified
  };
  
  const handleSort = (columnId: string) => {
    if (!onSort) return;
    
    const newDirection = 
      sortConfig?.columnId === columnId && sortConfig.direction === 'asc'
        ? 'desc'
        : 'asc';
    
    onSort({ columnId, direction: newDirection });
  };
  
  return (
    <thead className={className}>
      <tr>
        {selectable && (
          <th className={headerVariants({})}>
            {multiSelect && (
              <TableCheckbox
                checked={selectedRows.length > 0}
                indeterminate={selectedRows.length > 0 && selectedRows.length < 100} // Simplified
                onChange={handleSelectAll}
                aria-label="Select all rows"
              />
            )}
          </th>
        )}
        
        {columns.map(column => {
          const isSorted = sortConfig?.columnId === column.id;
          const sortDirection = isSorted ? sortConfig.direction : undefined;
          
          return (
            <th
              key={column.id}
              className={headerVariants({
                sortable: column.sortable,
                sticky: column.sticky,
                align: column.align,
              })}
              style={{
                width: column.width,
                minWidth: column.minWidth,
              }}
              onClick={column.sortable ? () => handleSort(column.id) : undefined}
              role={column.sortable ? 'columnheader button' : 'columnheader'}
              aria-sort={
                isSorted 
                  ? sortDirection === 'asc' ? 'ascending' : 'descending'
                  : column.sortable ? 'none' : undefined
              }
            >
              <div className="flex items-center">
                {column.header}
                {column.sortable && (
                  <SortIndicator direction={sortDirection} />
                )}
              </div>
            </th>
          );
        })}
      </tr>
    </thead>
  );
};

// Table Body component
export const TableBody = <T extends TableRow>({ 
  columns,
  data,
  striped = false,
  hoverable = false,
  rowClassName,
  onRowClick,
  className = ''
}: {
  columns: TableColumn<T>[];
  data: T[];
  striped?: boolean;
  hoverable?: boolean;
  rowClassName?: string | ((row: T, index: number) => string);
  onRowClick?: (row: T, index: number) => void;
  className?: string;
}) => {
  const { selectable, selectedRows, onSelectionChange } = useTableContext();
  
  const handleRowSelect = (rowId: string | number, checked: boolean) => {
    const newSelection = checked
      ? [...selectedRows, rowId]
      : selectedRows.filter(id => id !== rowId);
    
    onSelectionChange(newSelection);
  };
  
  const getCellValue = (column: TableColumn<T>, row: T) => {
    if (column.render) {
      return column.render(
        column.accessor ? 
          (typeof column.accessor === 'function' ? column.accessor(row) : row[column.accessor]) 
          : undefined,
        row,
        0 // index would be passed from parent
      );
    }
    
    if (column.accessor) {
      return typeof column.accessor === 'function' 
        ? column.accessor(row)
        : row[column.accessor];
    }
    
    return null;
  };
  
  return (
    <tbody className={className}>
      {data.map((row, index) => {
        const isSelected = selectedRows.includes(row.id);
        const finalRowClassName = typeof rowClassName === 'function'
          ? rowClassName(row, index)
          : rowClassName ?? '';
        
        return (
          <tr
            key={row.id}
            className={rowVariants({
              striped,
              hoverable: hoverable || Boolean(onRowClick),
              selectable,
              selected: isSelected,
              className: finalRowClassName,
            })}
            onClick={onRowClick ? () => onRowClick(row, index) : undefined}
          >
            {selectable && (
              <td className={cellVariants({})}>
                <TableCheckbox
                  checked={isSelected}
                  onChange={(checked) => handleRowSelect(row.id, checked)}
                  aria-label={`Select row ${index + 1}`}
                />
              </td>
            )}
            
            {columns.map(column => (
              <td
                key={column.id}
                className={cellVariants({ align: column.align })}
                style={{
                  width: column.width,
                  minWidth: column.minWidth,
                }}
              >
                {getCellValue(column, row)}
              </td>
            ))}
          </tr>
        );
      })}
    </tbody>
  );
};

// Main Table component
export const Table = forwardRef<HTMLTableElement, TableProps>(
  (
    {
      columns,
      data,
      sortable = false,
      selectable = false,
      multiSelect = false,
      striped = false,
      hoverable = true,
      selectedRows = [],
      sortConfig,
      loading = false,
      variant = 'default',
      size = 'md',
      stickyHeader = false,
      pagination: _pagination,
      onSort,
      onSelectionChange = () => {},
      onRowClick,
      emptyMessage = 'No data available',
      loadingMessage = 'Loading...',
      'aria-label': ariaLabel,
      className,
      headerClassName,
      bodyClassName,
      rowClassName,
      maxHeight,
      virtualized: _virtualized = false,
      ...props
    },
    ref
  ) => {
    // Table classes
    const tableClasses = tableVariants({ variant, size, className });
    
    // Context value
    const contextValue: TableContextValue = {
      selectable,
      multiSelect,
      selectedRows,
      onSelectionChange,
      sortConfig,
      onSort: sortable ? onSort : undefined,
    };
    
    // Loading state
    if (loading) {
      return (
        <div className="flex items-center justify-center py-8">
          <div className="text-neutral-500">{loadingMessage}</div>
        </div>
      );
    }
    
    // Empty state
    if (data.length === 0) {
      return (
        <div className="flex items-center justify-center py-8">
          <div className="text-neutral-500">{emptyMessage}</div>
        </div>
      );
    }
    
    const tableContent = (
      <TableContext.Provider value={contextValue}>
        <table
          ref={ref}
          className={tableClasses}
          role="table"
          aria-label={ariaLabel}
          {...props}
        >
          <TableHeader columns={columns} className={headerClassName} />
          <TableBody
            columns={columns}
            data={data}
            striped={striped}
            hoverable={hoverable}
            rowClassName={rowClassName}
            onRowClick={onRowClick}
            className={bodyClassName}
          />
        </table>
      </TableContext.Provider>
    );
    
    // Wrap in container for max height or sticky header
    if (maxHeight ?? stickyHeader) {
      return (
        <div
          className={`overflow-auto ${stickyHeader ? 'relative' : ''}`}
          style={{ maxHeight }}
        >
          {tableContent}
        </div>
      );
    }
    
    return tableContent;
  }
);

Table.displayName = 'Table';

export type TableVariantsProps = VariantProps<typeof tableVariants>;

/**
 * Enhanced concentration conversion utilities
 * Handles all scientific notation formats scientists use
 * 
 * ⚠️ DEPRECATED - Use utilities from @odysseus/shared-schemas instead
 * 
 * Phase 5 Migration:
 * - For display: Use formatConcentrationDisplay() from @odysseus/shared-schemas
 * - For parsing: Use parseConcentration() from @odysseus/shared-schemas
 * - For validation: Use Zod schema validation (concentrationPreprocessor)
 * 
 * This file kept for backward compatibility during migration.
 * Will be removed in future cleanup phase.
 */

// eslint-disable-next-line @typescript-eslint/no-unused-vars
import { formatToScientificNotation } from './scientificNotation';

/**
 * Comprehensive concentration parser supporting all common scientific formats:
 * - 5e6, 5E6, 5.0e6, 5.0E6
 * - 5e+6, 5E+6, 5.0e+6, 5.0E+6  
 * - 5e06, 5E06, 5.0e06, 5.0E06
 * - 5000000 (regular numbers)
 * - "5e6" (string formats)
 */
export function normalizeConcentration(value: string | number | undefined): number | undefined {
  if (value === undefined || value === null || value === '') return undefined;

  // Handle zero explicitly
  if (value === 0 || value === '0') return 0;

  // If already a number, validate and return
  if (typeof value === 'number') {
    return isNaN(value) ? undefined : value;
  }

  // Handle string input
  const stringValue = String(value).trim();
  if (!stringValue) return undefined;

  // Remove commas and spaces that might be in user input
  const cleanValue = stringValue.replace(/[,\s]/g, '');

  // Handle scientific notation patterns
  const scientificPatterns = [
    /^(\d*\.?\d+)[eE]([+-]?\d+)$/, // Standard: 5e6, 5.0E+06
    /^(\d*\.?\d+)[eE]([+-]?0*\d+)$/, // With leading zeros: 5e06
  ];

  for (const pattern of scientificPatterns) {
    const match = cleanValue.match(pattern);
    if (match) {
      const mantissa = parseFloat(match[1]);
      const exponent = parseInt(match[2]);

      if (!isNaN(mantissa) && !isNaN(exponent)) {
        return mantissa * Math.pow(10, exponent);
      }
    }
  }

  // Fallback to regular number parsing
  const parsed = parseFloat(cleanValue);
  return isNaN(parsed) ? undefined : parsed;
}

/**
 * Convert concentration for storage (server expects number)
 */
export function concentrationForStorage(input: string | number | undefined): number | undefined {
  return normalizeConcentration(input);
}

/**
 * Convert concentration for display (consistent formatting)
 */
export function concentrationForDisplay(
  value: number | undefined, 
  unit?: 'c/v' | 'c/mL'
): string {
  if (value === undefined || value === null) return '';
  if (value === 0) return '0';

  const formatted = formatToScientificNotation(value);
  return unit ? `${formatted} ${unit}` : formatted;
}

/**
 * Validate concentration input
 */
export function validateConcentrationInput(value: string | number | undefined): {
  isValid: boolean;
  normalized?: number;
  error?: string;
} {
  if (value === '' || value === undefined || value === null) {
    return { isValid: true }; // Optional field
  }

  const normalized = normalizeConcentration(value);

  if (normalized === undefined) {
    return {
      isValid: false,
      error: 'Invalid concentration format. Use numbers or scientific notation (e.g., 5e6, 1.5E+07)'
    };
  }

  if (normalized < 0) {
    return {
      isValid: false,
      error: 'Concentration cannot be negative'
    };
  }

  if (normalized > Number.MAX_SAFE_INTEGER) {
    return {
      isValid: false, 
      error: 'Concentration value too large'
    };
  }

  return {
    isValid: true,
    normalized
  };
}

/**
 * Type guard for concentration values
 */
export function isValidConcentration(value: any): value is number {
  return typeof value === 'number' && !isNaN(value) && value >= 0;
}

/**
 * Batch normalize concentrations (useful for import/migration)
 */
export function normalizeConcentrationBatch(
  values: Array<{ id: string; concentration?: string | number }>
): Array<{ id: string; concentration?: number; error?: string }> {
  return values.map(({ id, concentration }) => {
    const validation = validateConcentrationInput(concentration);

    return {
      id,
      concentration: validation.normalized,
      ...(validation.error && { error: validation.error })
    };
  });
}

/**
 * Form Utilities - Industry-Standard Partial Update Helpers
 *
 * Implements dirty field tracking for proper PATCH semantics.
 * Only sends fields that were actually modified by the user.
 *
 * Pattern: GraphQL-style precision updates
 * - Prevents accidental data loss in batch operations
 * - Clear user intent: touched = update, untouched = preserve
 * - Futureproof: works with any form structure
 */

import type { FieldValues } from 'react-hook-form';

/**
 * Extract only dirty (modified) fields from form data
 *
 * @param formData - Complete form data from form.getValues()
 * @param dirtyFields - Dirty fields tracking from form.formState.dirtyFields
 * @returns Object containing only the fields user modified
 *
 * @example
 * const formData = { name: 'John', age: 30, email: 'john@example.com' };
 * const dirtyFields = { name: true, age: true }; // email not touched
 * const result = extractDirtyFields(formData, dirtyFields);
 * // result = { name: 'John', age: 30 } // email excluded
 *
 * @example Nested objects
 * const formData = { sample: { cellType: 'Jurkat', media: { type: 'RPMI' } } };
 * const dirtyFields = { sample: { media: { type: true } } }; // Only media.type touched
 * const result = extractDirtyFields(formData, dirtyFields);
 * // result = { sample: { media: { type: 'RPMI' } } } // Only modified nested field
 */
export function extractDirtyFields<T extends FieldValues>(
  formData: T,
  dirtyFields: Partial<Record<keyof T, any>>
): Partial<T> {
  // Base case: if no dirty fields, return empty object
  if (!dirtyFields || Object.keys(dirtyFields).length === 0) {
    return {};
  }

  const result: any = {};

  for (const key in dirtyFields) {
    if (Object.prototype.hasOwnProperty.call(dirtyFields, key)) {
      const isDirty = dirtyFields[key];
      const value = formData[key];

      // If the field is marked as dirty (boolean true), include it
      if (isDirty === true) {
        result[key] = value;
      }
      // If it's an object (nested dirtyFields), recursively extract
      else if (typeof isDirty === 'object' && isDirty !== null && !Array.isArray(isDirty)) {
        // Only recurse if the value is also an object
        if (typeof value === 'object' && value !== null) {
          const nestedDirty = extractDirtyFields(value, isDirty);
          // Only include nested object if it has dirty fields
          if (Object.keys(nestedDirty).length > 0) {
            result[key] = nestedDirty;
          }
        }
      }
      // Handle arrays - if array is dirty, include entire array
      else if (Array.isArray(isDirty) && Array.isArray(value)) {
        // For arrays, if any element is dirty, include the whole array
        // This is standard behavior for form arrays
        const hasDirtyElements = isDirty.some(item =>
          typeof item === 'boolean' ? item : Object.keys(item || {}).length > 0
        );
        if (hasDirtyElements) {
          result[key] = value;
        }
      }
    }
  }

  return result;
}

/**
 * Check if any fields are dirty in a form
 * Useful for showing "unsaved changes" warnings
 */
export function hasAnyDirtyFields(dirtyFields: Record<string, any>): boolean {
  if (!dirtyFields) return false;

  for (const key in dirtyFields) {
    if (Object.prototype.hasOwnProperty.call(dirtyFields, key)) {
      const value = dirtyFields[key];
      if (value === true) return true;
      if (typeof value === 'object' && hasAnyDirtyFields(value)) return true;
    }
  }

  return false;
}

/**
 * Extract only non-empty fields from form data
 *
 * Specifically for batch edit scenarios where:
 * - Conflicting fields start as empty strings/undefined
 * - User fills in ONLY what they want to change
 * - Empty/undefined fields should be excluded from update
 *
 * Different from extractDirtyFields: works with 'create' mode forms that don't track dirty state
 *
 * @param formData - Complete form data from form.getValues()
 * @returns Object containing only non-empty fields
 *
 * @example Batch edit scenario
 * const formData = {
 *   sample: { cellType: '', media: { type: 'RPMI-1640' } },
 *   researcherId: 'researcher_123'
 * };
 * const result = extractNonEmptyFields(formData);
 * // result = { sample: { media: { type: 'RPMI-1640' } }, researcherId: 'researcher_123' }
 * // cellType excluded because empty
 */
export function extractNonEmptyFields<T extends FieldValues>(formData: T): Partial<T> {
  const result: any = {};

  for (const key in formData) {
    if (Object.prototype.hasOwnProperty.call(formData, key)) {
      const value = formData[key];

      // Skip undefined or null values
      if (value === undefined || value === null) {
        continue;
      }

      // Handle nested objects (like sample)
      if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
        // Check if it's a Date object (type assertion needed for generic type parameter)
        if ((value as any) instanceof Date) {
          result[key] = value;
        } else {
          const nestedResult = extractNonEmptyFields(value);
          // Only include nested object if it has non-empty fields
          if (Object.keys(nestedResult).length > 0) {
            result[key] = nestedResult;
          }
        }
      }
      // Handle arrays - include if not empty
      else if (Array.isArray(value)) {
        if (value.length > 0) {
          result[key] = value;
        }
      }
      // Handle strings - include if not empty
      else if (typeof value === 'string') {
        if (value.trim() !== '') {
          result[key] = value;
        }
      }
      // Handle other primitives (numbers, booleans, dates) - always include
      else {
        result[key] = value;
      }
    }
  }

  return result;
}

/**
 * Preload Helpers for Lazy-Loaded Components
 *
 * @module PreloadHelpers
 * @category Utilities - Lazy Loading
 * @architecture Code Splitting / Performance Optimization
 *
 * ARCHITECTURAL PURPOSE:
 * =====================
 * Provides reusable utilities for smart preloading of lazy-loaded components.
 * Implements industry-standard patterns for anticipatory loading to reduce
 * perceived latency and improve user experience.
 *
 * DESIGN PHILOSOPHY:
 * - DRY (Don't Repeat Yourself): Extract common preload patterns
 * - Type-safe: Full TypeScript support with generics
 * - Performance-focused: Non-blocking, deduplication-aware
 * - User intent-driven: Preload based on behavioral signals
 * - Framework-agnostic: Works with any React lazy component
 *
 * USAGE PATTERNS:
 * ```typescript
 * // Pattern 1: Create preload hook for any lazy component
 * const useLazyModal = createPreloadHook(() => import('./MyModal'));
 * const { preload, triggerProps, isPreloaded } = useLazyModal();
 *
 * // Pattern 2: Smart selection-based preloading
 * const { preload } = useLazyModal();
 * usePreloadOnSelection(selectedItems.length, 2, preload);
 *
 * // Pattern 3: Attach to trigger button
 * <button {...triggerProps} onClick={openModal}>Open Modal</button>
 * ```
 */

import { useCallback, useState, useMemo, useEffect } from 'react';

/**
 * Create a preload hook for any lazy-loaded component
 *
 * CHARACTERISTICS:
 * - Generic: Works with any component type
 * - Idempotent: Safe to call multiple times (deduplication handled by browser)
 * - Non-blocking: Preload happens in background
 * - Error-tolerant: Failures don't throw (component lazy loads normally instead)
 * - State-tracking: Tracks whether preload succeeded
 *
 * TYPE SAFETY:
 * - T: The props type of the lazy component
 * - Uses generic to ensure type safety when using the hook
 *
 * IMPLEMENTATION NOTES:
 * - Browser automatically deduplicates identical dynamic imports
 * - HTTP/2 multiplexing ensures no blocking of critical resources
 * - Failed preloads gracefully fall back to normal lazy loading
 * - React caches successful lazy loads automatically
 *
 * @param importFn - Dynamic import function for the component
 * @returns Hook that provides preload utilities
 *
 * @example
 * ```typescript
 * // Create a reusable hook for your lazy component
 * const useLazyTubeEditor = createPreloadHook(
 *   () => import('./TubeEditorModal')
 * );
 *
 * // Use in component
 * function Dashboard() {
 *   const { preload, triggerProps, isPreloaded } = useLazyTubeEditor();
 *
 *   return <button {...triggerProps}>Add Tube</button>;
 * }
 * ```
 */
export function createPreloadHook<T = any>(
  importFn: () => Promise<T>
) {
  return function usePreload() {
    const [isPreloaded, setIsPreloaded] = useState(false);

    /**
     * Manually trigger preload
     *
     * WHEN TO CALL:
     * - User hovers over trigger button
     * - User focuses trigger button (accessibility)
     * - Selection count meets threshold
     * - Navigation to section containing component
     * - User role indicates likely usage (e.g., admin preloading admin modals)
     *
     * SAFETY:
     * - Non-throwing: Errors are logged, not thrown
     * - Idempotent: Multiple calls are safe
     * - Non-blocking: Returns immediately
     *
     * @returns Promise that resolves when chunk is loaded (optional to await)
     */
    const preload = useCallback(async () => {
      if (isPreloaded) return;

      try {
        await importFn();
        setIsPreloaded(true);
      } catch (error) {
        // eslint-disable-next-line no-console -- Warning logging for production monitoring
        console.warn('[PreloadHelpers] Preload failed, will lazy load on render:', error);
        // Don't throw - component will lazy load normally on render
        // This handles transient network errors gracefully
      }
    }, [isPreloaded]);

    /**
     * Props to attach to trigger element for anticipatory loading
     *
     * USAGE:
     * Spread these props onto buttons or links that open the lazy component.
     * They will preload the chunk when user shows intent (hover/focus).
     *
     * EVENTS:
     * - onMouseEnter: Desktop users hovering (primary UX improvement)
     * - onFocus: Keyboard users tabbing (accessibility + UX)
     *
     * BENEFITS:
     * - Reduces perceived latency by 50-100ms
     * - Chunk downloads while user decides to click
     * - No impact on initial bundle size
     *
     * @returns Props object to spread onto trigger element
     *
     * @example
     * ```typescript
     * const { triggerProps } = usePreload();
     * <button {...triggerProps} onClick={openModal}>
     *   Add Tube
     * </button>
     * ```
     */
    const triggerProps = useMemo(() => ({
      onMouseEnter: preload,
      onFocus: preload,
    }), [preload]);

    return {
      /** Manually trigger preload (for programmatic use) */
      preload,

      /** Props to attach to trigger button for anticipatory loading */
      triggerProps,

      /** Whether component chunk has been successfully preloaded */
      isPreloaded,
    };
  };
}

/**
 * Hook for smart preloading based on selection count
 *
 * HEURISTIC:
 * - Preloads component when selection count meets or exceeds threshold
 * - Common pattern: Batch operations require higher selection counts
 * - Avoids unnecessary preloading for casual browsing/single selections
 *
 * USE CASES:
 * - Grid selection: Preload batch editor when 2+ items selected
 * - Table selection: Preload bulk actions when multiple rows selected
 * - File upload: Preload processor when multiple files added
 *
 * PERFORMANCE:
 * - Only triggers preload when threshold crossed (not on every selection change)
 * - Idempotent: Safe to call on every selection change
 *
 * @param selectedCount - Current number of selected items
 * @param threshold - Minimum selection count to trigger preload (default: 2)
 * @param preloadFn - Preload function to call when threshold met
 *
 * @example
 * ```typescript
 * const { preload } = useLazyBatchEditor();
 *
 * // In component
 * const selectedIds = useSelectedTubeIds();
 * usePreloadOnSelection(selectedIds.length, 2, preload);
 * ```
 */
export function usePreloadOnSelection(
  selectedCount: number,
  threshold: number = 2,
  preloadFn: () => void | Promise<void>
) {
  useEffect(() => {
    if (selectedCount >= threshold) {
      void preloadFn();
    }
  }, [selectedCount, threshold, preloadFn]);
}

/**
 * Create trigger props for anticipatory preloading
 *
 * USAGE:
 * Functional alternative to hook-based triggerProps for static contexts.
 * Useful when you don't need the full preload hook.
 *
 * EVENTS:
 * - onMouseEnter: Preload on hover (desktop users)
 * - onFocus: Preload on focus (keyboard users)
 *
 * @param preloadFn - Preload function to call on interaction
 * @returns Props object to spread onto trigger element
 *
 * @example
 * ```typescript
 * const props = createTriggerProps(() => import('./MyModal'));
 * <button {...props} onClick={openModal}>Open</button>
 * ```
 */
export function createTriggerProps(preloadFn: () => void | Promise<void>) {
  return {
    onMouseEnter: preloadFn,
    onFocus: preloadFn,
  };
}

/**
 * Hook for preloading on route/tab navigation
 *
 * USAGE:
 * Preload components when user navigates to a route or tab where
 * the component is likely to be used.
 *
 * PATTERN:
 * - Call in route/tab component
 * - Preloads happen in background during navigation transition
 * - By the time user interacts, component is ready
 *
 * @param preloadFn - Preload function to call on mount
 * @param condition - Optional condition to gate preloading (default: true)
 *
 * @example
 * ```typescript
 * function AdminDashboard() {
 *   const { preload } = useLazyAdminSettings();
 *
 *   // Preload admin settings modal when admin dashboard loads
 *   usePreloadOnMount(preload, userRole === 'admin');
 *
 *   return <div>...</div>;
 * }
 * ```
 */
export function usePreloadOnMount(
  preloadFn: () => void | Promise<void>,
  condition: boolean = true
) {
  useEffect(() => {
    if (condition) {
      void preloadFn();
    }
  }, [preloadFn, condition]);
}

/**
 * Hook for preloading after idle timeout
 *
 * USAGE:
 * Preload low-priority components after user has been idle for a period.
 * Uses requestIdleCallback for optimal performance.
 *
 * PATTERN:
 * - Waits for specified delay
 * - Uses requestIdleCallback if available (runs during browser idle time)
 * - Fallback to setTimeout for older browsers
 * - Doesn't preload if component already mounted
 *
 * @param preloadFn - Preload function to call after idle
 * @param delayMs - Delay in milliseconds before preloading (default: 2000)
 *
 * @example
 * ```typescript
 * function App() {
 *   const { preload: preloadSettings } = useLazySettings();
 *
 *   // Preload settings modal after 2 seconds of idle time
 *   usePreloadOnIdle(preloadSettings, 2000);
 * }
 * ```
 */
export function usePreloadOnIdle(
  preloadFn: () => void | Promise<void>,
  delayMs: number = 2000
) {
  useEffect(() => {
    const timer = setTimeout(() => {
      if ('requestIdleCallback' in window) {
        requestIdleCallback(() => void preloadFn());
      } else {
        void preloadFn();
      }
    }, delayMs);

    return () => clearTimeout(timer);
  }, [preloadFn, delayMs]);
}

/**
 * Batch preload multiple components
 *
 * USAGE:
 * Preload multiple related components at once (e.g., when navigating to a section).
 * Uses Promise.allSettled to ensure one failure doesn't block others.
 *
 * PATTERN:
 * - All preloads happen in parallel
 * - Failures are logged but don't throw
 * - Returns array of results (fulfilled/rejected)
 *
 * @param importFns - Array of import functions to preload
 * @returns Promise that resolves when all preloads complete (success or failure)
 *
 * @example
 * ```typescript
 * // Preload all admin modals when entering admin section
 * await batchPreload([
 *   () => import('./AdminSettings'),
 *   () => import('./UserManagement'),
 *   () => import('./SystemLogs'),
 * ]);
 * ```
 */
export async function batchPreload(importFns: Array<() => Promise<any>>): Promise<PromiseSettledResult<any>[]> {
  const results = await Promise.allSettled(importFns.map(fn => fn()));

  // Log failures in development
  if (process.env['NODE_ENV'] === 'development') {
    results.forEach((result, index) => {
      if (result.status === 'rejected') {
        // eslint-disable-next-line no-console -- Warning logging for production monitoring
        console.warn(`[PreloadHelpers] Batch preload failed for import #${index}:`, result.reason);
      }
    });
  }

  return results;
}

/**
 * PreloadHelpers namespace for organized exports
 *
 * USAGE:
 * ```typescript
 * import { PreloadHelpers } from '@shared/utils/lazy/PreloadHelpers';
 *
 * const useLazyModal = PreloadHelpers.createHook(() => import('./Modal'));
 * PreloadHelpers.useOnSelection(count, 2, preload);
 * ```
 */
export const PreloadHelpers = {
  createHook: createPreloadHook,
  createTriggerProps,
  useOnSelection: usePreloadOnSelection,
  useOnMount: usePreloadOnMount,
  useOnIdle: usePreloadOnIdle,
  batchPreload,
} as const;

/**
 * Lazy Component Utilities
 *
 * Utilities for managing lazy component loading, preloading, and performance monitoring
 */

import type { ComponentType } from 'react';
import { lazy } from 'react';

import { env } from '@shared/config';

// Lazy loading configuration
export interface LazyLoadConfig {
  // Preloading
  preloadDelay?: number; // Delay before auto-preloading (ms)
  preloadOnHover?: boolean; // Preload on hover
  preloadOnFocus?: boolean; // Preload on focus
  preloadOnViewport?: boolean; // Preload when component enters viewport
  
  // Performance
  timeout?: number; // Loading timeout (ms)
  retryAttempts?: number; // Number of retry attempts
  
  // Caching
  cacheComponents?: boolean; // Cache loaded components
  
  // Monitoring
  enableMetrics?: boolean; // Enable performance metrics
}

// Default configuration
const defaultConfig: LazyLoadConfig = {
  preloadDelay: 0,
  preloadOnHover: true,
  preloadOnFocus: true,
  preloadOnViewport: false,
  timeout: 10000,
  retryAttempts: 3,
  cacheComponents: true,
  enableMetrics: env.isDev(),
};

// Component cache for lazy loaded components
const componentCache = new Map<string, ComponentType<any>>();

// Performance metrics
interface LazyLoadMetrics {
  componentName: string;
  loadTime: number;
  attempts: number;
  success: boolean;
  timestamp: number;
  error?: string;
}

const metricsCollection: LazyLoadMetrics[] = [];

// Enhanced lazy loading function
export const createLazyComponent = <T extends ComponentType<any>>(
  importFn: () => Promise<{ default: T } | T>,
  componentName: string,
  config: LazyLoadConfig = {}
) => {
  const finalConfig = { ...defaultConfig, ...config };
  const cacheKey = componentName;
  
  // Check cache first
  if (finalConfig.cacheComponents && componentCache.has(cacheKey)) {
    return componentCache.get(cacheKey)!;
  }
  
  // Create lazy component with enhanced error handling and retries
  const LazyComponent = lazy(async () => {
    const startTime = performance.now();
    let lastError: Error | null = null;

    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- 0 retry attempts is invalid, default to 3
    for (let attempt = 1; attempt <= (finalConfig.retryAttempts || 3); attempt++) {
      try {
        // Add timeout handling
        const loadPromise = importFn();
        const timeoutPromise = new Promise<never>((_, reject) => {
          setTimeout(() => {
            reject(new Error(`Lazy loading timeout after ${finalConfig.timeout}ms`));
          }, finalConfig.timeout);
        });
        
        const result = await Promise.race([loadPromise, timeoutPromise]);
        const endTime = performance.now();
        const loadTime = endTime - startTime;
        
        // Handle different module formats
        const component = 'default' in result ? result.default : result;
        
        // Cache the component
        if (finalConfig.cacheComponents) {
          componentCache.set(cacheKey, component);
        }
        
        // Record metrics
        if (finalConfig.enableMetrics) {
          metricsCollection.push({
            componentName,
            loadTime,
            attempts: attempt,
            success: true,
            timestamp: Date.now(),
          });
          
          // eslint-disable-next-line no-console -- Performance metrics logging (only when enableMetrics is true)
          console.log(`Lazy loaded ${componentName} in ${loadTime.toFixed(2)}ms (attempt ${attempt})`);
        }
        
        return { default: component };
      } catch (error) {
        lastError = error as Error;
        
        if (finalConfig.enableMetrics) {
          // eslint-disable-next-line no-console -- Warning logging for production monitoring
          console.warn(`⚠️ Failed to load ${componentName} (attempt ${attempt}/${finalConfig.retryAttempts}):`, error);
        }
        
        // Wait before retry (exponential backoff)
        // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- 0 retry attempts is invalid, default to 3
        if (attempt < (finalConfig.retryAttempts || 3)) {
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt - 1) * 1000));
        }
      }
    }
    
    // All attempts failed
    const endTime = performance.now();
    const totalTime = endTime - startTime;
    
    if (finalConfig.enableMetrics) {
      metricsCollection.push({
        componentName,
        loadTime: totalTime,
        // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- 0 retry attempts is invalid, default to 3
        attempts: finalConfig.retryAttempts || 3,
        success: false,
        timestamp: Date.now(),
        error: lastError?.message,
      });
      
      // eslint-disable-next-line no-console -- Error logging needed for debugging production issues
      console.error(`❌ Failed to load ${componentName} after ${finalConfig.retryAttempts} attempts in ${totalTime.toFixed(2)}ms`);
    }

    throw lastError ?? new Error(`Failed to load ${componentName} after ${finalConfig.retryAttempts} attempts`);
  });
  
  // Set displayName for debugging - type assertion for LazyExoticComponent
  (LazyComponent as any).displayName = `Lazy(${componentName})`;
  
  return LazyComponent;
};

// Preloading utilities
export class PreloadManager {
  private static preloadPromises = new Map<string, Promise<void>>();
  private static preloadedComponents = new Set<string>();
  
  static async preload(
    importFn: () => Promise<any>,
    componentName: string,
    priority: 'high' | 'medium' | 'low' = 'medium'
  ): Promise<void> {
    if (this.preloadedComponents.has(componentName)) {
      return;
    }
    
    if (this.preloadPromises.has(componentName)) {
      return this.preloadPromises.get(componentName);
    }
    
    const preloadPromise = this.executePreload(importFn, componentName, priority);
    this.preloadPromises.set(componentName, preloadPromise);
    
    return preloadPromise;
  }
  
  private static async executePreload(
    importFn: () => Promise<any>,
    componentName: string,
    priority: 'high' | 'medium' | 'low'
  ): Promise<void> {
    try {
      const startTime = performance.now();
      
      // Delay for lower priority preloads to not block critical resources
      const delay = priority === 'high' ? 0 : priority === 'medium' ? 100 : 500;
      if (delay > 0) {
        await new Promise(resolve => setTimeout(resolve, delay));
      }
      
      await importFn();

      const endTime = performance.now();
      const _loadTime = endTime - startTime;

      this.preloadedComponents.add(componentName);
      this.preloadPromises.delete(componentName);
    } catch (error) {
      this.preloadPromises.delete(componentName);
      
      if (env.isDev()) {
        // eslint-disable-next-line no-console -- Warning logging for production monitoring
        console.warn(`Failed to preload ${componentName}:`, error);
      }
    }
  }
  
  // Batch preload multiple components
  static async batchPreload(
    components: Array<{
      importFn: () => Promise<any>;
      name: string;
      priority?: 'high' | 'medium' | 'low';
    }>
  ): Promise<void> {
    const preloadPromises = components.map(({ importFn, name, priority }) =>
      this.preload(importFn, name, priority)
    );
    
    try {
      await Promise.allSettled(preloadPromises);
    } catch (error) {
      if (env.isDev()) {
        // eslint-disable-next-line no-console -- Warning logging for production monitoring
        console.warn('Some components failed to preload during batch operation:', error);
      }
    }
  }
  
  // Preload components based on user interaction patterns
  static preloadOnInteraction(
    element: HTMLElement,
    importFn: () => Promise<any>,
    componentName: string,
    options: {
      onHover?: boolean;
      onFocus?: boolean;
      onViewport?: boolean;
      delay?: number;
    } = {}
  ): () => void {
    const { onHover = true, onFocus = true, onViewport = false, delay = 0 } = options;
    const listeners: Array<() => void> = [];
    
    const preloadWithDelay = () => {
      setTimeout(() => {
        void this.preload(importFn, componentName, 'medium');
      }, delay);
    };
    
    if (onHover) {
      const hoverHandler = () => preloadWithDelay();
      element.addEventListener('mouseenter', hoverHandler);
      listeners.push(() => element.removeEventListener('mouseenter', hoverHandler));
    }
    
    if (onFocus) {
      const focusHandler = () => preloadWithDelay();
      element.addEventListener('focus', focusHandler);
      listeners.push(() => element.removeEventListener('focus', focusHandler));
    }
    
    if (onViewport && 'IntersectionObserver' in window) {
      const observer = new IntersectionObserver(
        (entries) => {
          if (entries[0].isIntersecting) {
            preloadWithDelay();
            observer.disconnect();
          }
        },
        { threshold: 0.1 }
      );
      
      observer.observe(element);
      listeners.push(() => observer.disconnect());
    }
    
    // Return cleanup function
    return () => {
      listeners.forEach(cleanup => cleanup());
    };
  }
  
  // Get preload status
  static getPreloadStatus(): {
    preloaded: string[];
    loading: string[];
    total: number;
  } {
    return {
      preloaded: Array.from(this.preloadedComponents),
      loading: Array.from(this.preloadPromises.keys()),
      total: this.preloadedComponents.size + this.preloadPromises.size,
    };
  }
}

// Performance metrics utilities
export const LazyLoadMetrics = {
  // Get all metrics
  getMetrics(): LazyLoadMetrics[] {
    return [...metricsCollection];
  },
  
  // Get metrics for a specific component
  getComponentMetrics(componentName: string): LazyLoadMetrics[] {
    return metricsCollection.filter(m => m.componentName === componentName);
  },
  
  // Get performance summary
  getSummary() {
    const successful = metricsCollection.filter(m => m.success);
    const failed = metricsCollection.filter(m => !m.success);
    
    const avgLoadTime = successful.length > 0
      ? successful.reduce((sum, m) => sum + m.loadTime, 0) / successful.length
      : 0;
    
    return {
      total: metricsCollection.length,
      successful: successful.length,
      failed: failed.length,
      successRate: metricsCollection.length > 0 
        ? (successful.length / metricsCollection.length) * 100 
        : 0,
      averageLoadTime: avgLoadTime,
      slowestComponent: successful.reduce((slowest, current) => 
        current.loadTime > slowest.loadTime ? current : slowest, 
        successful[0] || { componentName: 'none', loadTime: 0 }
      ),
    };
  },
  
  // Clear metrics
  clear() {
    metricsCollection.length = 0;
  },
  
  // Export metrics to JSON
  export() {
    return JSON.stringify({
      metrics: metricsCollection,
      summary: this.getSummary(),
      timestamp: Date.now(),
    }, null, 2);
  },
};

// Development utilities
if (env.isDev()) {
  (window as any).lazyLoadUtils = {
    preloadManager: PreloadManager,
    metrics: LazyLoadMetrics,
    componentCache,
  };
}

